// MARK: - Embedded images (base64)

let homeB64 = ""
let headB64 = ""
let tile6B64 = ""
let bombB64 = ""

func imageFromB64(_ s: String) -> UIImage {
    if let d = Data(base64Encoded: s), let i = UIImage(data: d) { return i }
    return UIImage()
}

let homeImage: UIImage = imageFromB64(homeB64)
let headImage: UIImage = imageFromB64(headB64)

// MARK: - App + screens

@main
struct LetsGooApp: App {
    var body: some Scene {
        WindowGroup { RootView() }
    }
}

enum Screen { case welcome, photoRun, photoMatch, photoShoot, game, match, shoot, crime, geass }

struct RootView: View {
    @State private var screen: Screen = .welcome

    var body: some View {
        ZStack {
            if screen == .welcome {
                WelcomeView(onGo: { screen = .photoRun }, onCandy: { screen = .photoMatch }, onFinger: { screen = .photoShoot }, onEnter: { screen = .crime }, onGeass: { screen = .geass })
            } else if screen == .photoRun {
                PhotoView(onUnlock: { screen = .game })
            } else if screen == .photoMatch {
                PhotoView(onUnlock: { screen = .match })
            } else if screen == .photoShoot {
                PhotoView(onUnlock: { screen = .shoot })
            } else if screen == .game {
                GameView(onExit: { screen = .welcome })
            } else if screen == .shoot {
                ShootView(onExit: { screen = .welcome })
            } else if screen == .crime {
                CrimeView(onExit: { screen = .welcome })
            } else if screen == .geass {
                GeassGameView(onExit: { screen = .welcome })
            } else {
                MatchView(onExit: { screen = .welcome })
            }
        }
    }
}

