struct PhotoView: View {
    var onUnlock: () -> Void
    @State private var taps = 0
    @State private var pop = false

    var body: some View {
        ZStack {
            Color.black.ignoresSafeArea()
            VStack(spacing: 16) {
                Image(uiImage: homeImage)
                    .resizable()
                    .scaledToFit()
                    .cornerRadius(20)
                    .padding(24)
                    .scaleEffect(pop ? 0.94 : 1.0)
                    .onTapGesture {
                        taps += 1
                        withAnimation(.easeOut(duration: 0.08)) { pop = true }
                        DispatchQueue.main.asyncAfter(deadline: .now() + 0.1) {
                            withAnimation(.easeOut(duration: 0.08)) { pop = false }
                        }
                        if taps >= 5 {
                            taps = 0
                            onUnlock()
                        }
                    }
                Text("tap the pic 5 times")
                    .font(.footnote)
                    .foregroundColor(.gray)
            }
        }
    }
}

struct GameView: View {
    var onExit: () -> Void
    @State private var scene: GameScene = GameScene.make()

    var body: some View {
        ZStack(alignment: .topLeading) {
            SpriteView(scene: scene)
                .ignoresSafeArea()
            Button(action: onExit) {
                Text("✕")
                    .font(.system(size: 20, weight: .bold))
                    .foregroundColor(.white)
                    .frame(width: 40, height: 40)
                    .background(Color.black.opacity(0.45))
                    .clipShape(Circle())
            }
            .padding(12)
        }
        .background(Color.black.ignoresSafeArea())
    }
}

// MARK: - Game helpers

enum Kind { case block, low, overhead, coin, scenery }

final class Thing {
    let node: SKNode
    let kind: Kind
    let lane: CGFloat
    var d: CGFloat
    var done = false

    init(node: SKNode, kind: Kind, lane: CGFloat, d: CGFloat) {
        self.node = node
        self.kind = kind
        self.lane = lane
        self.d = d
    }
}

func rectNode(_ x: CGFloat, _ y: CGFloat, _ w: CGFloat, _ h: CGFloat, _ c: UIColor) -> SKSpriteNode {
    let s = SKSpriteNode(color: c, size: CGSize(width: w, height: h))
    s.anchorPoint = CGPoint.zero
    s.position = CGPoint(x: x, y: y)
    return s
}

func limbNode(_ w: CGFloat, _ h: CGFloat, _ c: UIColor) -> SKNode {
    let p = SKNode()
    p.addChild(rectNode(-w / 2, -h, w, h, c))
    return p
}

func makeLabel(_ text: String, _ fs: CGFloat, _ color: UIColor) -> SKLabelNode {
    let l = SKLabelNode(fontNamed: "AvenirNext-Bold")
    l.text = text
    l.fontSize = fs
    l.fontColor = color
    return l
}

func makeBlock() -> SKNode {
    let n = SKNode()
    n.addChild(rectNode(-48, 0, 96, 120, UIColor(red: 0.85, green: 0.2, blue: 0.2, alpha: 1)))
    n.addChild(rectNode(-48, 92, 96, 28, UIColor(red: 0.6, green: 0.1, blue: 0.1, alpha: 1)))
    n.addChild(rectNode(-36, 50, 30, 28, UIColor(white: 0.92, alpha: 1)))
    n.addChild(rectNode(6, 50, 30, 28, UIColor(white: 0.92, alpha: 1)))
    n.addChild(rectNode(-48, 0, 96, 12, UIColor(white: 0.15, alpha: 1)))
    return n
}

func makeLow() -> SKNode {
    let n = SKNode()
    n.addChild(rectNode(-48, 0, 96, 34, UIColor(red: 1.0, green: 0.6, blue: 0.1, alpha: 1)))
    n.addChild(rectNode(-48, 10, 96, 12, UIColor(white: 1, alpha: 1)))
    n.addChild(rectNode(-48, 0, 8, 34, UIColor(white: 0.2, alpha: 1)))
    n.addChild(rectNode(40, 0, 8, 34, UIColor(white: 0.2, alpha: 1)))
    return n
}

func makeOverhead() -> SKNode {
    let n = SKNode()
    n.addChild(rectNode(-46, 0, 10, 102, UIColor(white: 0.45, alpha: 1)))
    n.addChild(rectNode(36, 0, 10, 102, UIColor(white: 0.45, alpha: 1)))
    n.addChild(rectNode(-48, 64, 96, 38, UIColor(red: 1.0, green: 0.85, blue: 0.1, alpha: 1)))
    n.addChild(rectNode(-30, 64, 14, 38, UIColor(white: 0.1, alpha: 1)))
    n.addChild(rectNode(2, 64, 14, 38, UIColor(white: 0.1, alpha: 1)))
    return n
}

func makeCoin() -> SKNode {
    let n = SKNode()
    let c = SKShapeNode(circleOfRadius: 12)
    c.fillColor = UIColor(red: 1.0, green: 0.84, blue: 0.1, alpha: 1)
    c.strokeColor = UIColor(red: 0.85, green: 0.55, blue: 0.0, alpha: 1)
    c.lineWidth = 3
    c.position = CGPoint(x: 0, y: 38)
    n.addChild(c)
    return n
}

func makeBuilding() -> SKNode {
    let n = SKNode()
    let h = CGFloat.random(in: 140...340)
    let colors: [UIColor] = [
        UIColor(red: 0.55, green: 0.45, blue: 0.70, alpha: 1),
        UIColor(red: 0.40, green: 0.50, blue: 0.75, alpha: 1),
        UIColor(red: 0.75, green: 0.50, blue: 0.50, alpha: 1),
        UIColor(red: 0.45, green: 0.65, blue: 0.60, alpha: 1)
    ]
    n.addChild(rectNode(-45, 0, 90, h, colors.randomElement()!))
    var y: CGFloat = 20
    while y < h - 30 {
        n.addChild(rectNode(-30, y, 18, 16, UIColor(white: 1, alpha: 0.55)))
        n.addChild(rectNode(12, y, 18, 16, UIColor(white: 1, alpha: 0.55)))
        y += 40
    }
    return n
}

// MARK: - Game scene (3-lane endless runner)

final class GameScene: SKScene {
    static func make() -> GameScene {
        let s = GameScene(size: UIScreen.main.bounds.size)
        s.scaleMode = .aspectFill
        return s
    }

    // layout
    let d0: CGFloat = 60
    let farD: CGFloat = 520
    var u: CGFloat = 1
    var cx: CGFloat = 0
    var horizonY: CGFloat = 0
    var baseY: CGFloat = 0
    var laneW: CGFloat = 0

    // state
    var lane = 0
    var laneX: CGFloat = 0
    var jumpT: CGFloat = -1
    var slideT: CGFloat = -1
    var jumpH: CGFloat = 0
    let jumpDur: CGFloat = 0.75
    let slideDur: CGFloat = 0.7
    var runSpeed: CGFloat = 230
    var distance: CGFloat = 0
    var coins = 0
    var dead = false
    var diedAt: TimeInterval = 0
    var lastTime: TimeInterval = 0
    var spawnAcc: CGFloat = 0
    var nextGap: CGFloat = 160
    var sceneryAcc: CGFloat = 0
    var sceneryRight = false
    var stripeOff: CGFloat = 0
    var runPhase: CGFloat = 0
    var didSetup = false

    // nodes
    var things: [Thing] = []
    var world = SKNode()
    var player: SKNode!
    var rig: SKNode!
    var shadow: SKShapeNode!
    var legL: SKNode!
    var legR: SKNode!
    var armL: SKNode!
    var armR: SKNode!
    var head: SKSpriteNode!
    var scoreLabel: SKLabelNode!
    var coinLabel: SKLabelNode!
    var overlay: SKNode?
    var stripes: [SKSpriteNode] = []
    var gestures: [UISwipeGestureRecognizer] = []

    func yAt(_ t: CGFloat) -> CGFloat {
        return horizonY + (baseY - horizonY) * t
    }

    // MARK: setup

    override func didMove(to view: SKView) {
        if !didSetup {
            didSetup = true
            setup()
        }
        let dirs: [UISwipeGestureRecognizer.Direction] = [.left, .right, .up, .down]
        for dir in dirs {
            let g = UISwipeGestureRecognizer(target: self, action: #selector(swiped(_:)))
            g.direction = dir
            view.addGestureRecognizer(g)
            gestures.append(g)
        }
    }

    override func willMove(from view: SKView) {
        for g in gestures { view.removeGestureRecognizer(g) }
        gestures.removeAll()
    }

    func setup() {
        u = size.width / 375
        cx = size.width / 2
        horizonY = size.height * 0.60
        baseY = size.height * 0.20
        laneW = 112 * u
        backgroundColor = UIColor(red: 0.45, green: 0.75, blue: 0.95, alpha: 1)

        // sun
        let sun = SKShapeNode(circleOfRadius: 38 * u)
        sun.fillColor = UIColor(red: 1, green: 0.95, blue: 0.5, alpha: 1)
        sun.strokeColor = UIColor.clear
        sun.position = CGPoint(x: cx + 100 * u, y: horizonY + 120 * u)
        sun.zPosition = -95
        addChild(sun)

        // far hills
        let hillColor = UIColor(red: 0.35, green: 0.55, blue: 0.75, alpha: 1)
        addChild(triangle(cx - 110 * u, 220 * u, 90 * u, hillColor))
        addChild(triangle(cx + 60 * u, 260 * u, 120 * u, hillColor))
        addChild(triangle(cx + 170 * u, 200 * u, 70 * u, hillColor))

        // ground
        let ground = SKSpriteNode(color: UIColor(red: 0.35, green: 0.60, blue: 0.35, alpha: 1),
                                  size: CGSize(width: size.width, height: horizonY))
        ground.anchorPoint = CGPoint(x: 0.5, y: 1)
        ground.position = CGPoint(x: cx, y: horizonY)
        ground.zPosition = -90
        addChild(ground)

        // road
        let tEnd: CGFloat = 1.9
        let roadPath = CGMutablePath()
        roadPath.move(to: CGPoint(x: cx, y: horizonY))
        roadPath.addLine(to: CGPoint(x: cx - 1.5 * laneW * tEnd, y: yAt(tEnd)))
        roadPath.addLine(to: CGPoint(x: cx + 1.5 * laneW * tEnd, y: yAt(tEnd)))
        roadPath.closeSubpath()
        let road = SKShapeNode(path: roadPath)
        road.fillColor = UIColor(red: 0.27, green: 0.27, blue: 0.32, alpha: 1)
        road.strokeColor = UIColor.clear
        road.zPosition = -80
        addChild(road)

        // lane lines
        let fs: [CGFloat] = [-1.5, -0.5, 0.5, 1.5]
        for f in fs {
            let p = CGMutablePath()
            p.move(to: CGPoint(x: cx, y: horizonY))
            p.addLine(to: CGPoint(x: cx + f * laneW * tEnd, y: yAt(tEnd)))
            let l = SKShapeNode(path: p)
            let edge = abs(f) > 1
            l.strokeColor = edge ? UIColor.white : UIColor(white: 1, alpha: 0.5)
            l.lineWidth = (edge ? 4 : 2) * u
            l.zPosition = -79
            addChild(l)
        }

        // moving stripes
        for _ in 0..<14 {
            let s = SKSpriteNode(color: UIColor(white: 0, alpha: 0.18), size: CGSize(width: 10, height: 2))
            s.zPosition = -78
            addChild(s)
            stripes.append(s)
        }

        world.zPosition = 0
        addChild(world)

        buildPlayer()

        // HUD
        scoreLabel = makeLabel("0", 30 * u, UIColor.white)
        scoreLabel.position = CGPoint(x: cx, y: size.height - 90)
        scoreLabel.zPosition = 100
        addChild(scoreLabel)

        coinLabel = makeLabel("Coins: 0", 20 * u, UIColor.yellow)
        coinLabel.horizontalAlignmentMode = .right
        coinLabel.position = CGPoint(x: size.width - 16, y: size.height - 88)
        coinLabel.zPosition = 100
        addChild(coinLabel)

        restart()
    }

    func triangle(_ x: CGFloat, _ w: CGFloat, _ h: CGFloat, _ c: UIColor) -> SKShapeNode {
        let p = CGMutablePath()
        p.move(to: CGPoint(x: x - w / 2, y: horizonY))
        p.addLine(to: CGPoint(x: x, y: horizonY + h))
        p.addLine(to: CGPoint(x: x + w / 2, y: horizonY))
        p.closeSubpath()
        let n = SKShapeNode(path: p)
        n.fillColor = c
        n.strokeColor = UIColor.clear
        n.zPosition = -92
        return n
    }

    func buildPlayer() {
        player = SKNode()
        player.zPosition = 10
        player.setScale(u)
        addChild(player)

        shadow = SKShapeNode(ellipseOf: CGSize(width: 56, height: 16))
        shadow.fillColor = UIColor(white: 0, alpha: 0.3)
        shadow.strokeColor = UIColor.clear
        shadow.zPosition = -1
        player.addChild(shadow)

        rig = SKNode()
        player.addChild(rig)

        let pants = UIColor(red: 0.15, green: 0.20, blue: 0.50, alpha: 1)
        let hoodie = UIColor(red: 1.0, green: 0.50, blue: 0.10, alpha: 1)
        let sleeve = UIColor(red: 0.90, green: 0.40, blue: 0.05, alpha: 1)

        legL = limbNode(14, 44, pants)
        legL.position = CGPoint(x: -10, y: 44)
        legR = limbNode(14, 44, pants)
        legR.position = CGPoint(x: 10, y: 44)
        rig.addChild(legL)
        rig.addChild(legR)

        rig.addChild(rectNode(-22, 42, 44, 48, hoodie))

        armL = limbNode(12, 34, sleeve)
        armL.position = CGPoint(x: -27, y: 86)
        armR = limbNode(12, 34, sleeve)
        armR.position = CGPoint(x: 27, y: 86)
        rig.addChild(armL)
        rig.addChild(armR)

        let tex = SKTexture(image: headImage)
        head = SKSpriteNode(texture: tex, size: CGSize(width: 46, height: 64))
        head.position = CGPoint(x: 0, y: 118)
        rig.addChild(head)
    }

    // MARK: game flow

    func restart() {
        overlay?.removeFromParent()
        overlay = nil
        for t in things { t.node.removeFromParent() }
        things.removeAll()
        lane = 0
        laneX = 0
        jumpT = -1
        slideT = -1
        jumpH = 0
        runSpeed = 230
        distance = 0
        coins = 0
        dead = false
        spawnAcc = 0
        nextGap = 160
        sceneryAcc = 0
        lastTime = 0
        rig.zRotation = 0
        coinLabel.text = "Coins: 0"
        scoreLabel.text = "0"
        for i in 0..<6 {
            sceneryRight.toggle()
            let side: CGFloat = sceneryRight ? 1.95 : -1.95
            add(makeBuilding(), .scenery, side, CGFloat(i) * 85 + 30)
        }
    }

    func crash() {
        if dead { return }
        dead = true
        diedAt = lastTime
        rig.zRotation = 1.3
        UIImpactFeedbackGenerator(style: .heavy).impactOccurred()
        showGameOver()
    }

    func showGameOver() {
        let sc = Int(distance / 10)
        let best = max(sc, UserDefaults.standard.integer(forKey: "best"))
        UserDefaults.standard.set(best, forKey: "best")

        let o = SKNode()
        o.zPosition = 200
        let dim = SKSpriteNode(color: UIColor(white: 0, alpha: 0.65), size: size)
        dim.position = CGPoint(x: cx, y: size.height / 2)
        o.addChild(dim)

        let t1 = makeLabel("GAME OVER", 44 * u, UIColor.white)
        t1.position = CGPoint(x: cx, y: size.height * 0.62)
        o.addChild(t1)
        let t2 = makeLabel("Score: \(sc)   Coins: \(coins)", 24 * u, UIColor.yellow)
        t2.position = CGPoint(x: cx, y: size.height * 0.55)
        o.addChild(t2)
        let t3 = makeLabel("Best: \(best)", 22 * u, UIColor.white)
        t3.position = CGPoint(x: cx, y: size.height * 0.50)
        o.addChild(t3)
        let t4 = makeLabel("tap to play again", 20 * u, UIColor.lightGray)
        t4.position = CGPoint(x: cx, y: size.height * 0.42)
        o.addChild(t4)

        addChild(o)
        overlay = o
    }

    override func touchesBegan(_ touches: Set<UITouch>, with event: UIEvent?) {
        if dead && (lastTime - diedAt) > 0.6 {
            restart()
        }
    }

    @objc func swiped(_ g: UISwipeGestureRecognizer) {
        if dead { return }
        switch g.direction {
        case .left:
            if lane > -1 { lane -= 1 }
        case .right:
            if lane < 1 { lane += 1 }
        case .up:
            if jumpT < 0 {
                jumpT = 0
                slideT = -1
                UIImpactFeedbackGenerator(style: .light).impactOccurred()
            }
        case .down:
            if jumpT >= 0 { jumpT = jumpDur * 0.7 }
            if slideT < 0 { slideT = 0 }
        default:
            break
        }
    }

    // MARK: spawning

    func place(_ t: Thing) {
        let tt = d0 / (t.d + d0)
        t.node.position = CGPoint(x: cx + t.lane * laneW * tt, y: yAt(tt))
        t.node.setScale(u * tt)
        t.node.zPosition = tt * 10
        t.node.alpha = min(1, max(0, (tt - 0.10) * 10))
    }

    func add(_ n: SKNode, _ k: Kind, _ lane: CGFloat, _ d: CGFloat) {
        let t = Thing(node: n, kind: k, lane: lane, d: d)
        world.addChild(n)
        place(t)
        things.append(t)
    }

    func spawnPattern() {
        let lanes: [CGFloat] = [-1, 0, 1]
        let r = Int.random(in: 0..<5)
        switch r {
        case 0, 1:
            let ls = lanes.shuffled()
            let count = Int.random(in: 1...2)
            for i in 0..<count { add(makeBlock(), .block, ls[i], farD) }
        case 2:
            let ls = lanes.shuffled()
            let count = Int.random(in: 1...3)
            for i in 0..<count { add(makeLow(), .low, ls[i], farD) }
        case 3:
            let ls = lanes.shuffled()
            let count = Int.random(in: 1...3)
            for i in 0..<count { add(makeOverhead(), .overhead, ls[i], farD) }
        default:
            let l = lanes.randomElement()!
            for i in 0..<6 { add(makeCoin(), .coin, l, farD + CGFloat(i) * 26) }
        }
    }

    // MARK: update loop

    override func update(_ currentTime: TimeInterval) {
        if lastTime == 0 {
            lastTime = currentTime
            return
        }
        var dt = CGFloat(currentTime - lastTime)
        lastTime = currentTime
        if dt > 0.05 { dt = 0.05 }
        if dt <= 0 { return }
        if dead { return }

        runSpeed = min(540, runSpeed + 5 * dt)
        distance += runSpeed * dt
        scoreLabel.text = String(Int(distance / 10))

        // jump / slide timers
        var hj: CGFloat = 0
        if jumpT >= 0 {
            jumpT += dt
            if jumpT >= jumpDur {
                jumpT = -1
            } else {
                let p = jumpT / jumpDur
                hj = 4 * 90 * p * (1 - p)
            }
        }
        jumpH = hj
        if slideT >= 0 {
            slideT += dt
            if slideT >= slideDur { slideT = -1 }
        }
        let sliding = slideT >= 0

        // player
        laneX += (CGFloat(lane) - laneX) * min(1, dt * 14)
        player.position = CGPoint(x: cx + laneX * laneW, y: baseY)
        rig.position = CGPoint(x: 0, y: hj)
        rig.yScale = sliding ? 0.5 : 1.0
        rig.zRotation = (CGFloat(lane) - laneX) * 0.35
        shadow.setScale(max(0.4, 1 - hj / 160))

        if hj > 0 {
            legL.zRotation = 0.6
            legR.zRotation = -0.6
            armL.zRotation = -2.5
            armR.zRotation = 2.5
        } else {
            runPhase += dt * runSpeed / 22
            let sw = sin(runPhase)
            legL.zRotation = sw * 0.8
            legR.zRotation = -sw * 0.8
            armL.zRotation = -sw * 0.7
            armR.zRotation = sw * 0.7
            head.position = CGPoint(x: 0, y: 118 + abs(sw) * 3)
        }

        // road stripes
        stripeOff += runSpeed * dt / farD
        stripeOff = stripeOff.truncatingRemainder(dividingBy: 1)
        for (i, s) in stripes.enumerated() {
            var f = CGFloat(i) / CGFloat(stripes.count) - stripeOff
            f = f - floor(f)
            let d = f * farD
            let tt = d0 / (d + d0)
            s.position = CGPoint(x: cx, y: yAt(tt))
            s.size = CGSize(width: 3 * laneW * tt, height: max(1, 7 * u * tt))
        }

        // spawning
        spawnAcc += runSpeed * dt
        if spawnAcc >= nextGap {
            spawnAcc = 0
            nextGap = CGFloat.random(in: 200...320) + (runSpeed - 230) * 0.25
            spawnPattern()
        }
        sceneryAcc += runSpeed * dt
        if sceneryAcc >= 90 {
            sceneryAcc = 0
            sceneryRight.toggle()
            let side: CGFloat = sceneryRight ? 1.95 : -1.95
            add(makeBuilding(), .scenery, side, farD)
        }

        // move things + collisions
        var keep: [Thing] = []
        for t in things {
            t.d -= runSpeed * dt
            if t.d < -40 || t.done {
                t.node.removeFromParent()
                continue
            }
            place(t)
            if dead || t.kind == .scenery || t.d > 12 || t.d < -16 {
                keep.append(t)
                continue
            }
            if abs(laneX - t.lane) < 0.55 {
                switch t.kind {
                case .coin:
                    coins += 1
                    t.done = true
                    coinLabel.text = "Coins: \(coins)"
                case .block:
                    crash()
                case .low:
                    if jumpH < 36 { crash() }
                case .overhead:
                    if slideT < 0 { crash() }
                case .scenery:
                    break
                }
            }
            keep.append(t)
        }
        things = keep
    }
}

// MARK: - Photo storage (your 8 photos)

enum Store {
    static let names = ["Tile 1", "Tile 2", "Tile 3", "Tile 4", "Tile 5", "Tile 6", "Striped (match 4)", "Bomb (match 5)"]
    static let fruits = ["🍒", "🍋", "🍇", "🍏", "🍊", "🍉", "⭐️", "💣"]

    static func url(_ i: Int) -> URL {
        let dir = FileManager.default.urls(for: .documentDirectory, in: .userDomainMask)[0]
        return dir.appendingPathComponent("slot\(i).png")
    }

    static func load(_ i: Int) -> UIImage {
        if let d = try? Data(contentsOf: url(i)), let im = UIImage(data: d) { return im }
        if i == 5 {
            let im = imageFromB64(tile6B64)
            if im.size.width > 0 { return im }
        }
        if i == 7 {
            let im = imageFromB64(bombB64)
            if im.size.width > 0 { return im }
        }
        return emojiImage(fruits[i])
    }

    static func save(_ img: UIImage, slot i: Int) {
        let sq = squareCrop(img, 160)
        if let d = sq.pngData() {
            try? d.write(to: url(i))
        }
    }

    static func reset() {
        for i in 0..<8 {
            try? FileManager.default.removeItem(at: url(i))
        }
    }

    static func emojiImage(_ e: String) -> UIImage {
        let f = UIGraphicsImageRendererFormat.default()
        f.scale = 1
        f.opaque = false
        let r = UIGraphicsImageRenderer(size: CGSize(width: 160, height: 160), format: f)
        return r.image { _ in
            let s = NSString(string: e)
            let attrs: [NSAttributedString.Key: Any] = [.font: UIFont.systemFont(ofSize: 120)]
            let sz = s.size(withAttributes: attrs)
            s.draw(at: CGPoint(x: (160 - sz.width) / 2, y: (160 - sz.height) / 2), withAttributes: attrs)
        }
    }

    // square crop: wide photos from the center, tall photos from the top (faces are up there)
    static func squareCrop(_ img: UIImage, _ out: CGFloat) -> UIImage {
        let w = img.size.width
        let h = img.size.height
        let side = min(w, h)
        let ox = (w - side) / 2
        let scale = out / side
        let f = UIGraphicsImageRendererFormat.default()
        f.scale = 1
        f.opaque = false
        let r = UIGraphicsImageRenderer(size: CGSize(width: out, height: out), format: f)
        return r.image { _ in
            img.draw(in: CGRect(x: -ox * scale, y: 0, width: w * scale, height: h * scale))
        }
    }
}

struct PhotoPicker: UIViewControllerRepresentable {
    var onPick: (UIImage?) -> Void

    func makeUIViewController(context: Context) -> PHPickerViewController {
        var config = PHPickerConfiguration()
        config.filter = .images
        config.selectionLimit = 1
        let vc = PHPickerViewController(configuration: config)
        vc.delegate = context.coordinator
        return vc
    }

    func updateUIViewController(_ uiViewController: PHPickerViewController, context: Context) {}

    func makeCoordinator() -> Coordinator {
        return Coordinator(onPick)
    }

    final class Coordinator: NSObject, PHPickerViewControllerDelegate {
        let onPick: (UIImage?) -> Void

        init(_ onPick: @escaping (UIImage?) -> Void) {
            self.onPick = onPick
        }

        func picker(_ picker: PHPickerViewController, didFinishPicking results: [PHPickerResult]) {
            guard let provider = results.first?.itemProvider, provider.canLoadObject(ofClass: UIImage.self) else {
                onPick(nil)
                return
            }
            provider.loadObject(ofClass: UIImage.self) { obj, _ in
                DispatchQueue.main.async {
                    self.onPick(obj as? UIImage)
                }
            }
        }
    }
}

