// MARK: - Match-3 game

enum Special { case none, stripedH, stripedV, wrapped, bomb }

struct Pos: Hashable {
    let c: Int
    let r: Int
}

struct Run {
    var cells: [Pos]
    var horizontal: Bool
}

final class Tile {
    var kind: Int          // 0...5 = photo, 6 = color bomb
    var special: Special
    var node: SKNode

    init(kind: Int, special: Special, node: SKNode) {
        self.kind = kind
        self.special = special
        self.node = node
    }
}

final class MatchScene: SKScene {
    static func make() -> MatchScene {
        let s = MatchScene(size: UIScreen.main.bounds.size)
        s.scaleMode = .aspectFill
        return s
    }

    let cols = 8
    let rows = 8
    var cell: CGFloat = 44
    var x0: CGFloat = 0
    var y0: CGFloat = 0

    var grid: [[Tile?]] = []
    var board = SKNode()
    var faceTex: [SKTexture] = []
    var stripedTex: SKTexture!
    var bombTex: SKTexture!

    let kindColors: [UIColor] = [
        UIColor(red: 0.90, green: 0.25, blue: 0.30, alpha: 1),
        UIColor(red: 0.95, green: 0.60, blue: 0.15, alpha: 1),
        UIColor(red: 0.95, green: 0.85, blue: 0.20, alpha: 1),
        UIColor(red: 0.30, green: 0.75, blue: 0.35, alpha: 1),
        UIColor(red: 0.25, green: 0.55, blue: 0.95, alpha: 1),
        UIColor(red: 0.65, green: 0.35, blue: 0.85, alpha: 1)
    ]

    var score = 0
    var busy = false
    var overShown = false
    var overDate = Date()
    var overlay: SKNode?
    var scoreLabel: SKLabelNode!
    var selected: Pos?
    var selRing: SKShapeNode?
    var startPos: Pos?
    var startPoint = CGPoint.zero
    var didSetup = false
    var pendingBlasts: [Pos] = []

    // MARK: setup

    override func didMove(to view: SKView) {
        if !didSetup {
            didSetup = true
            setup()
        }
    }

    func setup() {
        backgroundColor = UIColor(red: 0.14, green: 0.07, blue: 0.24, alpha: 1)
        cell = floor((size.width - 16) / CGFloat(cols))
        x0 = (size.width - CGFloat(cols) * cell) / 2
        y0 = (size.height - CGFloat(rows) * cell) / 2 - 10

        let back = SKSpriteNode(color: UIColor(white: 1, alpha: 0.10),
                                size: CGSize(width: CGFloat(cols) * cell + 12, height: CGFloat(rows) * cell + 12))
        back.position = CGPoint(x: size.width / 2, y: y0 + CGFloat(rows) * cell / 2)
        back.zPosition = -10
        addChild(back)

        board.zPosition = 0
        addChild(board)

        scoreLabel = makeLabel("Score: 0", 28, UIColor.white)
        scoreLabel.position = CGPoint(x: size.width / 2, y: size.height - 100)
        scoreLabel.zPosition = 100
        addChild(scoreLabel)

        loadTextures()
        newGame()
    }

    func loadTextures() {
        faceTex = (0..<6).map { SKTexture(image: Store.load($0)) }
        stripedTex = SKTexture(image: Store.load(6))
        bombTex = SKTexture(image: Store.load(7))
    }

    func reloadImages() {
        loadTextures()
        newGame()
    }

    func newGame() {
        removeAllActions()
        board.removeAllActions()
        board.removeAllChildren()
        board.position = CGPoint.zero
        overlay?.removeFromParent()
        overlay = nil
        selRing = nil
        selected = nil
        startPos = nil
        score = 0
        busy = false
        overShown = false
        fillBoard()
        seedBombSetup()
        updateHUD()
    }

    func updateHUD() {
        scoreLabel.text = "Score: \(score)"
    }

    func after(_ t: TimeInterval, _ f: @escaping () -> Void) {
        run(SKAction.sequence([SKAction.wait(forDuration: t), SKAction.run(f)]))
    }

    func pos(_ c: Int, _ r: Int) -> CGPoint {
        return CGPoint(x: x0 + (CGFloat(c) + 0.5) * cell, y: y0 + (CGFloat(r) + 0.5) * cell)
    }

    func posAt(_ p: CGPoint) -> Pos? {
        let c = Int(floor((p.x - x0) / cell))
        let r = Int(floor((p.y - y0) / cell))
        if c >= 0 && c < cols && r >= 0 && r < rows {
            return Pos(c: c, r: r)
        }
        return nil
    }

    // MARK: tiles

    func makeTileNode(kind: Int, special: Special) -> SKNode {
        let w = cell - 6
        let n = SKNode()
        let bgColor = kind >= 6 ? UIColor(red: 0.20, green: 0.10, blue: 0.30, alpha: 1) : kindColors[kind]
        let bg = SKShapeNode(rectOf: CGSize(width: w, height: w), cornerRadius: w * 0.22)
        bg.fillColor = bgColor
        bg.strokeColor = UIColor(white: 1, alpha: 0.7)
        bg.lineWidth = 2
        n.addChild(bg)

        let tex: SKTexture
        if special == .bomb {
            tex = bombTex
        } else if special == .none || special == .wrapped {
            tex = faceTex[kind]
        } else {
            tex = stripedTex
        }
        let face = SKSpriteNode(texture: tex, size: CGSize(width: w * 0.84, height: w * 0.84))
        n.addChild(face)

        if special == .stripedH {
            for i in -1...1 {
                let s = SKSpriteNode(color: UIColor(white: 1, alpha: 0.7), size: CGSize(width: w * 0.9, height: 3))
                s.position = CGPoint(x: 0, y: CGFloat(i) * w * 0.28)
                n.addChild(s)
            }
        } else if special == .stripedV {
            for i in -1...1 {
                let s = SKSpriteNode(color: UIColor(white: 1, alpha: 0.7), size: CGSize(width: 3, height: w * 0.9))
                s.position = CGPoint(x: CGFloat(i) * w * 0.28, y: 0)
                n.addChild(s)
            }
        } else if special == .wrapped {
            let gold = UIColor(red: 1.0, green: 0.85, blue: 0.2, alpha: 1)
            let frame = SKShapeNode(rectOf: CGSize(width: w + 2, height: w + 2), cornerRadius: w * 0.22)
            frame.strokeColor = gold
            frame.lineWidth = 5
            frame.fillColor = UIColor.clear
            n.addChild(frame)
            let sides: [CGFloat] = [-1, 1]
            for sx in sides {
                let bow = SKShapeNode(circleOfRadius: w * 0.10)
                bow.fillColor = gold
                bow.strokeColor = UIColor.white
                bow.lineWidth = 1
                bow.position = CGPoint(x: sx * (w / 2 + 1), y: 0)
                n.addChild(bow)
            }
            let pulse = SKAction.sequence([SKAction.scale(to: 1.06, duration: 0.5), SKAction.scale(to: 0.96, duration: 0.5)])
            n.run(SKAction.repeatForever(pulse))
        } else if special == .bomb {
            let ring = SKShapeNode(circleOfRadius: w * 0.55)
            ring.strokeColor = UIColor.orange
            ring.lineWidth = 3
            ring.fillColor = UIColor.clear
            n.addChild(ring)
            let pulse = SKAction.sequence([SKAction.scale(to: 1.08, duration: 0.45), SKAction.scale(to: 0.94, duration: 0.45)])
            n.run(SKAction.repeatForever(pulse))
        }
        return n
    }

    @discardableResult
    func addTile(_ c: Int, _ r: Int, kind: Int, special: Special) -> Tile {
        let n = makeTileNode(kind: kind, special: special)
        n.position = pos(c, r)
        n.zPosition = 1
        board.addChild(n)
        let t = Tile(kind: kind, special: special, node: n)
        grid[c][r] = t
        return t
    }

    func wouldMatch(_ c: Int, _ r: Int, _ k: Int) -> Bool {
        if c >= 2, let a = grid[c - 1][r], let b = grid[c - 2][r], a.kind == k, b.kind == k { return true }
        if r >= 2, let a = grid[c][r - 1], let b = grid[c][r - 2], a.kind == k, b.kind == k { return true }
        return false
    }

    func randomKind(_ c: Int, _ r: Int) -> Int {
        var k = Int.random(in: 0..<6)
        var tries = 0
        while tries < 30 && wouldMatch(c, r, k) {
            k = Int.random(in: 0..<6)
            tries += 1
        }
        return k
    }

    func fillBoard() {
        var attempts = 0
        repeat {
            board.removeAllChildren()
            selRing = nil
            selected = nil
            grid = Array(repeating: Array<Tile?>(repeating: nil, count: rows), count: cols)
            for c in 0..<cols {
                for r in 0..<rows {
                    addTile(c, r, kind: randomKind(c, r), special: .none)
                }
            }
            attempts += 1
        } while !hasPossibleMove() && attempts < 30
    }

    // MARK: matching

    func findRuns() -> [Run] {
        var runs: [Run] = []
        for r in 0..<rows {
            var c = 0
            while c < cols {
                guard let t = grid[c][r], t.kind < 6 else {
                    c += 1
                    continue
                }
                var e = c + 1
                while e < cols, let u = grid[e][r], u.kind == t.kind {
                    e += 1
                }
                if e - c >= 3 {
                    var cells: [Pos] = []
                    for x in c..<e { cells.append(Pos(c: x, r: r)) }
                    runs.append(Run(cells: cells, horizontal: true))
                }
                c = e
            }
        }
        for c in 0..<cols {
            var r = 0
            while r < rows {
                guard let t = grid[c][r], t.kind < 6 else {
                    r += 1
                    continue
                }
                var e = r + 1
                while e < rows, let u = grid[c][e], u.kind == t.kind {
                    e += 1
                }
                if e - r >= 3 {
                    var cells: [Pos] = []
                    for y in r..<e { cells.append(Pos(c: c, r: y)) }
                    runs.append(Run(cells: cells, horizontal: false))
                }
                r = e
            }
        }
        return runs
    }

    func testSwap(_ c1: Int, _ r1: Int, _ c2: Int, _ r2: Int) -> Bool {
        let t1 = grid[c1][r1]
        let t2 = grid[c2][r2]
        grid[c1][r1] = t2
        grid[c2][r2] = t1
        let ok = !findRuns().isEmpty
        grid[c1][r1] = t1
        grid[c2][r2] = t2
        return ok
    }

    func hasPossibleMove() -> Bool {
        for c in 0..<cols {
            for r in 0..<rows {
                if let t = grid[c][r], t.special == .bomb { return true }
                if c + 1 < cols && testSwap(c, r, c + 1, r) { return true }
                if r + 1 < rows && testSwap(c, r, c, r + 1) { return true }
            }
        }
        return false
    }

    // MARK: guaranteed 5-match setup

    func setKind(_ c: Int, _ r: Int, _ k: Int) {
        guard let t = grid[c][r], t.special == .none else { return }
        let old = t.node
        let n = makeTileNode(kind: k, special: .none)
        n.position = old.position
        n.zPosition = 1
        board.addChild(n)
        old.removeFromParent()
        t.node = n
        t.kind = k
    }

    // puts "X X _ X X" in a row with an X above/below the gap, so one swap makes 5 in a row
    func seedBombSetup() {
        for _ in 0..<15 {
            let r = Int.random(in: 1..<(rows - 1))
            let c = Int.random(in: 0...(cols - 5))
            let k = Int.random(in: 0..<6)
            var m = Int.random(in: 0..<6)
            while m == k { m = Int.random(in: 0..<6) }
            let rr = Bool.random() ? r + 1 : r - 1
            let cells: [Pos] = [
                Pos(c: c, r: r), Pos(c: c + 1, r: r), Pos(c: c + 2, r: r),
                Pos(c: c + 3, r: r), Pos(c: c + 4, r: r), Pos(c: c + 2, r: rr)
            ]
            var ok = true
            var saved: [Int] = []
            for p in cells {
                if let t = grid[p.c][p.r], t.special == .none {
                    saved.append(t.kind)
                } else {
                    ok = false
                    break
                }
            }
            if !ok { continue }
            let newKinds: [Int] = [k, k, m, k, k, k]
            for (i, p) in cells.enumerated() { setKind(p.c, p.r, newKinds[i]) }
            if findRuns().isEmpty { return }
            for (i, p) in cells.enumerated() { setKind(p.c, p.r, saved[i]) }
        }
    }

    // MARK: swapping

    func trySwap(_ a: Pos, _ b: Pos) {
        if busy || overShown { return }
        guard let ta = grid[a.c][a.r], let tb = grid[b.c][b.r] else { return }
        busy = true
        grid[a.c][a.r] = tb
        grid[b.c][b.r] = ta
        ta.node.run(SKAction.move(to: pos(b.c, b.r), duration: 0.15))
        tb.node.run(SKAction.move(to: pos(a.c, a.r), duration: 0.15))
        after(0.18) {
            let sa = ta.special
            let sb = tb.special
            if sa == .bomb || sb == .bomb || (sa != .none && sb != .none) {
                let clear = self.comboSet(ta, tb, a, b)
                self.executeClear(clear, creations: [:], combo: 1)
                return
            }
            if self.findRuns().isEmpty {
                self.grid[a.c][a.r] = ta
                self.grid[b.c][b.r] = tb
                ta.node.run(SKAction.move(to: self.pos(a.c, a.r), duration: 0.15))
                tb.node.run(SKAction.move(to: self.pos(b.c, b.r), duration: 0.15))
                self.after(0.18) {
                    self.busy = false
                }
            } else {
                self.processMatches(swapA: a, swapB: b, combo: 1)
            }
        }
    }

    // helpers for special combos
    func areaCells(_ p: Pos, _ radius: Int) -> [Pos] {
        var out: [Pos] = []
        for dc in -radius...radius {
            for dr in -radius...radius {
                let c = p.c + dc
                let r = p.r + dr
                if c >= 0 && c < cols && r >= 0 && r < rows {
                    out.append(Pos(c: c, r: r))
                }
            }
        }
        return out
    }

    func makeSpecialQuiet(_ t: Tile, _ sp: Special) {
        let old = t.node
        let n = makeTileNode(kind: t.kind, special: sp)
        n.position = old.position
        n.zPosition = 5
        board.addChild(n)
        old.removeFromParent()
        t.node = n
        t.special = sp
    }

    // what gets destroyed when two specials are swapped (ta is now at b, tb is now at a)
    func comboSet(_ ta: Tile, _ tb: Tile, _ a: Pos, _ b: Pos) -> Set<Pos> {
        var clear = Set<Pos>()
        clear.insert(a)
        clear.insert(b)
        let sa = ta.special
        let sb = tb.special
        let aStriped = (sa == .stripedH || sa == .stripedV)
        let bStriped = (sb == .stripedH || sb == .stripedV)

        if sa == .bomb || sb == .bomb {
            let bombPos = (sa == .bomb) ? b : a
            explosion(at: pos(bombPos.c, bombPos.r))
            if sa == .bomb && sb == .bomb {
                // bomb + bomb: whole board
                for c in 0..<cols {
                    for r in 0..<rows {
                        clear.insert(Pos(c: c, r: r))
                    }
                }
                return clear
            }
            let other = (sa == .bomb) ? tb : ta
            var kinds = Set<Int>()
            kinds.insert(other.kind)
            if other.special == .wrapped {
                // bomb + wrapped: that color and one more random color
                var k2 = Int.random(in: 0..<6)
                var tries = 0
                while k2 == other.kind && tries < 20 {
                    k2 = Int.random(in: 0..<6)
                    tries += 1
                }
                kinds.insert(k2)
            }
            let makeStriped = (other.special == .stripedH || other.special == .stripedV)
            for c in 0..<cols {
                for r in 0..<rows {
                    if let t = grid[c][r], kinds.contains(t.kind) {
                        if makeStriped && t.special == .none {
                            makeSpecialQuiet(t, Bool.random() ? .stripedH : .stripedV)
                        }
                        clear.insert(Pos(c: c, r: r))
                    }
                }
            }
            return clear
        }

        if aStriped && bStriped {
            // striped + striped: a row and a column
            for c in 0..<cols { clear.insert(Pos(c: c, r: b.r)) }
            for r in 0..<rows { clear.insert(Pos(c: b.c, r: r)) }
            lineFlash(horizontal: true, b)
            lineFlash(horizontal: false, b)
            return clear
        }

        if sa == .wrapped && sb == .wrapped {
            // wrapped + wrapped: big 5x5 blast
            for q in areaCells(b, 2) { clear.insert(q) }
            blastFlash(b)
            return clear
        }

        // striped + wrapped: 3 rows and 3 columns
        for dr in -1...1 {
            let rr = b.r + dr
            if rr >= 0 && rr < rows {
                for c in 0..<cols { clear.insert(Pos(c: c, r: rr)) }
            }
        }
        for dc in -1...1 {
            let cc = b.c + dc
            if cc >= 0 && cc < cols {
                for r in 0..<rows { clear.insert(Pos(c: cc, r: r)) }
            }
        }
        lineFlash(horizontal: true, b)
        lineFlash(horizontal: false, b)
        return clear
    }

    func blastFlash(_ p: Pos) {
        let s = SKShapeNode(rectOf: CGSize(width: cell * 3, height: cell * 3), cornerRadius: 12)
        s.position = pos(p.c, p.r)
        s.fillColor = UIColor(red: 1.0, green: 0.9, blue: 0.4, alpha: 0.7)
        s.strokeColor = UIColor.white
        s.lineWidth = 3
        s.zPosition = 55
        board.addChild(s)
        s.run(SKAction.sequence([
            SKAction.group([SKAction.scale(to: 1.3, duration: 0.3), SKAction.fadeOut(withDuration: 0.3)]),
            SKAction.removeFromParent()
        ]))
        burst(at: pos(p.c, p.r), color: UIColor.orange, count: 10, dist: 80)
    }

    func processMatches(swapA: Pos?, swapB: Pos?, combo: Int) {
        let runs = findRuns()
        if runs.isEmpty {
            finishTurn()
            return
        }
        var clear = Set<Pos>()
        var creations: [Pos: Special] = [:]
        for run in runs {
            for p in run.cells { clear.insert(p) }
            if run.cells.count >= 4 {
                var spot = run.cells[run.cells.count / 2]
                if let a = swapA, run.cells.contains(a) {
                    spot = a
                } else if let b = swapB, run.cells.contains(b) {
                    spot = b
                }
                let sp: Special = run.cells.count >= 5 ? .bomb : (run.horizontal ? .stripedV : .stripedH)
                if creations[spot] != .bomb {
                    creations[spot] = sp
                }
            }
        }
        // L, T and + shapes: a horizontal and a vertical run crossing -> wrapped candy
        for h in runs where h.horizontal {
            for v in runs where !v.horizontal {
                for p in h.cells where v.cells.contains(p) {
                    if creations[p] != .bomb {
                        creations[p] = .wrapped
                    }
                }
            }
        }
        for (p, _) in creations {
            clear.remove(p)
        }
        executeClear(clear, creations: creations, combo: combo)
    }

    func executeClear(_ initial: Set<Pos>, creations: [Pos: Special], combo: Int) {
        var clear = initial
        var queue = Array(initial)
        var idx = 0
        while idx < queue.count {
            let p = queue[idx]
            idx += 1
            guard let t = grid[p.c][p.r] else { continue }
            var extra: [Pos] = []
            if t.special == .stripedH {
                lineFlash(horizontal: true, p)
                for c in 0..<cols { extra.append(Pos(c: c, r: p.r)) }
            } else if t.special == .stripedV {
                lineFlash(horizontal: false, p)
                for r in 0..<rows { extra.append(Pos(c: p.c, r: r)) }
            } else if t.special == .wrapped {
                blastFlash(p)
                pendingBlasts.append(p)
                extra.append(contentsOf: areaCells(p, 1))
            }
            for e in extra {
                if !clear.contains(e) && creations[e] == nil {
                    clear.insert(e)
                    queue.append(e)
                }
            }
        }

        var count = 0
        for p in clear {
            guard let t = grid[p.c][p.r] else { continue }
            grid[p.c][p.r] = nil
            count += 1
            let n = t.node
            n.removeAllActions()
            n.run(SKAction.sequence([
                SKAction.group([SKAction.scale(to: 0.1, duration: 0.18), SKAction.fadeOut(withDuration: 0.18)]),
                SKAction.removeFromParent()
            ]))
            burst(at: pos(p.c, p.r), color: kindColors[min(t.kind, 5)], count: 6, dist: 34)
        }
        for (p, sp) in creations {
            guard let t = grid[p.c][p.r] else { continue }
            convert(t, to: sp)
        }
        score += count * 10 * combo
        updateHUD()

        after(0.32) {
            let d = self.collapseAndRefill()
            self.after(d + 0.05) {
                if !self.pendingBlasts.isEmpty {
                    // wrapped candies explode a second time after the candies fall
                    let blasts = self.pendingBlasts
                    self.pendingBlasts.removeAll()
                    var set = Set<Pos>()
                    for bp in blasts {
                        self.blastFlash(bp)
                        for q in self.areaCells(bp, 1) { set.insert(q) }
                    }
                    self.executeClear(set, creations: [:], combo: combo + 1)
                } else {
                    self.processMatches(swapA: nil, swapB: nil, combo: combo + 1)
                }
            }
        }
    }

    func convert(_ t: Tile, to sp: Special) {
        let old = t.node
        let newKind = (sp == .bomb) ? 6 : t.kind
        let n = makeTileNode(kind: newKind, special: sp)
        n.position = old.position
        n.zPosition = 5
        board.addChild(n)
        old.removeFromParent()
        t.node = n
        t.special = sp
        t.kind = newKind
        n.setScale(0.2)
        n.run(SKAction.sequence([SKAction.scale(to: 1.25, duration: 0.15), SKAction.scale(to: 1.0, duration: 0.1)]))
        if sp == .bomb {
            explosion(at: n.position)
        }
    }

    func collapseAndRefill() -> TimeInterval {
        var maxDur: TimeInterval = 0.1
        for c in 0..<cols {
            var write = 0
            for r in 0..<rows {
                if let t = grid[c][r] {
                    if r != write {
                        grid[c][write] = t
                        grid[c][r] = nil
                        let dur = 0.1 + 0.06 * Double(r - write)
                        let mv = SKAction.move(to: pos(c, write), duration: dur)
                        mv.timingMode = .easeIn
                        t.node.run(mv)
                        if dur > maxDur { maxDur = dur }
                    }
                    write += 1
                }
            }
            var spawn = 0
            if write < rows {
                for r in write..<rows {
                    let t = addTile(c, r, kind: Int.random(in: 0..<6), special: .none)
                    let startRow = rows + spawn
                    spawn += 1
                    t.node.position = pos(c, startRow)
                    let dur = 0.1 + 0.06 * Double(startRow - r)
                    let mv = SKAction.move(to: pos(c, r), duration: dur)
                    mv.timingMode = .easeIn
                    t.node.run(mv)
                    if dur > maxDur { maxDur = dur }
                }
            }
        }
        return maxDur
    }

    func finishTurn() {
        board.position = CGPoint.zero
        if !hasPossibleMove() {
            fillBoard()
            showToast("No moves left - shuffled!")
        }
        seedBombSetup()
        busy = false
    }

    // MARK: effects

    func burst(at p: CGPoint, color: UIColor, count: Int, dist: CGFloat) {
        for _ in 0..<count {
            let s = SKSpriteNode(color: color, size: CGSize(width: 6, height: 6))
            s.position = p
            s.zPosition = 50
            board.addChild(s)
            let ang = CGFloat.random(in: 0..<(2 * CGFloat.pi))
            let d = CGFloat.random(in: (dist * 0.5)...dist)
            let move = SKAction.moveBy(x: cos(ang) * d, y: sin(ang) * d, duration: 0.3)
            s.run(SKAction.sequence([
                SKAction.group([move, SKAction.fadeOut(withDuration: 0.3)]),
                SKAction.removeFromParent()
            ]))
        }
    }

    func lineFlash(horizontal: Bool, _ p: Pos) {
        let center = pos(p.c, p.r)
        let s: SKSpriteNode
        if horizontal {
            s = SKSpriteNode(color: UIColor.white, size: CGSize(width: CGFloat(cols) * cell, height: cell * 0.5))
            s.position = CGPoint(x: size.width / 2, y: center.y)
        } else {
            s = SKSpriteNode(color: UIColor.white, size: CGSize(width: cell * 0.5, height: CGFloat(rows) * cell))
            s.position = CGPoint(x: center.x, y: y0 + CGFloat(rows) * cell / 2)
        }
        s.zPosition = 55
        s.alpha = 0.9
        board.addChild(s)
        s.run(SKAction.sequence([SKAction.fadeOut(withDuration: 0.35), SKAction.removeFromParent()]))
    }

    func explosion(at p: CGPoint) {
        UIImpactFeedbackGenerator(style: .heavy).impactOccurred()

        let ring = SKShapeNode(circleOfRadius: 20)
        ring.position = p
        ring.zPosition = 60
        ring.strokeColor = UIColor.orange
        ring.lineWidth = 8
        ring.fillColor = UIColor(red: 1.0, green: 0.8, blue: 0.2, alpha: 0.6)
        board.addChild(ring)
        ring.run(SKAction.sequence([
            SKAction.group([SKAction.scale(to: 9, duration: 0.45), SKAction.fadeOut(withDuration: 0.45)]),
            SKAction.removeFromParent()
        ]))

        let fire: [UIColor] = [UIColor.red, UIColor.orange, UIColor.yellow, UIColor.white]
        for col in fire {
            burst(at: p, color: col, count: 8, dist: 150)
        }

        let boom = SKLabelNode(text: "💥")
        boom.fontSize = 60
        boom.position = CGPoint(x: p.x, y: p.y - 20)
        boom.zPosition = 65
        boom.setScale(0.3)
        board.addChild(boom)
        boom.run(SKAction.sequence([
            SKAction.group([SKAction.scale(to: 3.0, duration: 0.4), SKAction.fadeOut(withDuration: 0.4)]),
            SKAction.removeFromParent()
        ]))

        let boomText = makeLabel("BOOM!", 52, UIColor.yellow)
        boomText.position = CGPoint(x: size.width / 2, y: size.height * 0.78)
        boomText.zPosition = 80
        boomText.setScale(0.4)
        addChild(boomText)
        boomText.run(SKAction.sequence([
            SKAction.scale(to: 1.2, duration: 0.2),
            SKAction.wait(forDuration: 0.5),
            SKAction.fadeOut(withDuration: 0.3),
            SKAction.removeFromParent()
        ]))

        let flash = SKSpriteNode(color: UIColor.white, size: size)
        flash.position = CGPoint(x: size.width / 2, y: size.height / 2)
        flash.zPosition = 70
        flash.alpha = 0
        addChild(flash)
        flash.run(SKAction.sequence([
            SKAction.fadeAlpha(to: 0.7, duration: 0.05),
            SKAction.fadeOut(withDuration: 0.25),
            SKAction.removeFromParent()
        ]))

        board.run(SKAction.sequence([
            SKAction.moveBy(x: 10, y: 6, duration: 0.04),
            SKAction.moveBy(x: -20, y: -12, duration: 0.04),
            SKAction.moveBy(x: 20, y: 12, duration: 0.04),
            SKAction.moveBy(x: -10, y: -6, duration: 0.04)
        ]))
    }

    func showToast(_ text: String) {
        let l = makeLabel(text, 20, UIColor.white)
        l.position = CGPoint(x: size.width / 2, y: size.height * 0.80)
        l.zPosition = 150
        addChild(l)
        l.run(SKAction.sequence([SKAction.wait(forDuration: 1.2), SKAction.fadeOut(withDuration: 0.4), SKAction.removeFromParent()]))
    }

    // MARK: game over

    func showGameOver() {
        overShown = true
        overDate = Date()
        let best = max(score, UserDefaults.standard.integer(forKey: "bestMatch"))
        UserDefaults.standard.set(best, forKey: "bestMatch")

        let o = SKNode()
        o.zPosition = 200
        let dim = SKSpriteNode(color: UIColor(white: 0, alpha: 0.7), size: size)
        dim.position = CGPoint(x: size.width / 2, y: size.height / 2)
        o.addChild(dim)

        let t1 = makeLabel("OUT OF MOVES", 38, UIColor.white)
        t1.position = CGPoint(x: size.width / 2, y: size.height * 0.60)
        o.addChild(t1)
        let t2 = makeLabel("Score: \(score)", 28, UIColor.yellow)
        t2.position = CGPoint(x: size.width / 2, y: size.height * 0.54)
        o.addChild(t2)
        let t3 = makeLabel("Best: \(best)", 22, UIColor.white)
        t3.position = CGPoint(x: size.width / 2, y: size.height * 0.49)
        o.addChild(t3)
        let t4 = makeLabel("tap to play again", 20, UIColor.lightGray)
        t4.position = CGPoint(x: size.width / 2, y: size.height * 0.42)
        o.addChild(t4)

        addChild(o)
        overlay = o
    }

    // MARK: input

    func select(_ p: Pos) {
        clearSelection()
        selected = p
        let ring = SKShapeNode(rectOf: CGSize(width: cell - 2, height: cell - 2), cornerRadius: 10)
        ring.strokeColor = UIColor.white
        ring.lineWidth = 3
        ring.fillColor = UIColor.clear
        ring.position = pos(p.c, p.r)
        ring.zPosition = 20
        board.addChild(ring)
        selRing = ring
    }

    func clearSelection() {
        selRing?.removeFromParent()
        selRing = nil
        selected = nil
    }

    func isAdjacent(_ a: Pos, _ b: Pos) -> Bool {
        return abs(a.c - b.c) + abs(a.r - b.r) == 1
    }

    override func touchesBegan(_ touches: Set<UITouch>, with event: UIEvent?) {
        guard let touch = touches.first else { return }
        if overShown {
            if Date().timeIntervalSince(overDate) > 0.6 {
                newGame()
            }
            return
        }
        if busy { return }
        let p = touch.location(in: self)
        guard let tp = posAt(p) else { return }
        if let s = selected, isAdjacent(s, tp) {
            clearSelection()
            trySwap(s, tp)
            return
        }
        startPos = tp
        startPoint = p
        select(tp)
    }

    override func touchesMoved(_ touches: Set<UITouch>, with event: UIEvent?) {
        guard let sp = startPos, !busy, let touch = touches.first else { return }
        let p = touch.location(in: self)
        let dx = p.x - startPoint.x
        let dy = p.y - startPoint.y
        if max(abs(dx), abs(dy)) > cell * 0.45 {
            var target = sp
            if abs(dx) > abs(dy) {
                target = Pos(c: sp.c + (dx > 0 ? 1 : -1), r: sp.r)
            } else {
                target = Pos(c: sp.c, r: sp.r + (dy > 0 ? 1 : -1))
            }
            startPos = nil
            clearSelection()
            if target.c >= 0 && target.c < cols && target.r >= 0 && target.r < rows {
                trySwap(sp, target)
            }
        }
    }

    override func touchesEnded(_ touches: Set<UITouch>, with event: UIEvent?) {
        startPos = nil
    }
}

// MARK: - Western shooting gallery

func pt(_ x: CGFloat, _ y: CGFloat) -> CGPoint {
    return CGPoint(x: x, y: y)
}

func poly(_ pts: [CGPoint], _ fill: UIColor, _ stroke: UIColor? = nil, _ lw: CGFloat = 1) -> SKShapeNode {
    let p = CGMutablePath()
    p.move(to: pts[0])
    for i in 1..<pts.count {
        p.addLine(to: pts[i])
    }
    p.closeSubpath()
    let n = SKShapeNode(path: p)
    n.fillColor = fill
    if let s = stroke {
        n.strokeColor = s
        n.lineWidth = lw
    } else {
        n.strokeColor = UIColor.clear
    }
    return n
}

func lineNode(_ a: CGPoint, _ b: CGPoint, _ c: UIColor, _ w: CGFloat) -> SKShapeNode {
    let p = CGMutablePath()
    p.move(to: a)
    p.addLine(to: b)
    let n = SKShapeNode(path: p)
    n.strokeColor = c
    n.lineWidth = w
    return n
}

func starPoints(_ c: CGPoint, _ rOut: CGFloat, _ rIn: CGFloat) -> [CGPoint] {
    var out: [CGPoint] = []
    for i in 0..<10 {
        let ang = CGFloat.pi / 2 + CGFloat(i) * CGFloat.pi / 5
        let r = (i % 2 == 0) ? rOut : rIn
        out.append(CGPoint(x: c.x + cos(ang) * r, y: c.y + sin(ang) * r))
    }
    return out
}

func westernLabel(_ text: String, _ fs: CGFloat, _ color: UIColor) -> SKLabelNode {
    let l = SKLabelNode(fontNamed: "Copperplate-Bold")
    l.text = text
    l.fontSize = fs
    l.fontColor = color
    return l
}

func gradientImage(_ size: CGSize, _ colors: [UIColor], _ locs: [CGFloat]) -> UIImage {
    let f = UIGraphicsImageRendererFormat.default()
    f.scale = 1
    let r = UIGraphicsImageRenderer(size: size, format: f)
    return r.image { ctx in
        let cs = CGColorSpaceCreateDeviceRGB()
        let cg = colors.map { $0.cgColor } as CFArray
        if let g = CGGradient(colorsSpace: cs, colors: cg, locations: locs) {
            ctx.cgContext.drawLinearGradient(g, start: CGPoint(x: 0, y: 0), end: CGPoint(x: 0, y: size.height), options: [])
        }
    }
}

func radialImage(_ size: CGSize, _ radius: CGFloat, _ colors: [UIColor], _ locs: [CGFloat]) -> UIImage {
    let f = UIGraphicsImageRendererFormat.default()
    f.scale = 1
    let r = UIGraphicsImageRenderer(size: size, format: f)
    return r.image { ctx in
        let cs = CGColorSpaceCreateDeviceRGB()
        let cg = colors.map { $0.cgColor } as CFArray
        let c = CGPoint(x: size.width / 2, y: size.height / 2)
        if let g = CGGradient(colorsSpace: cs, colors: cg, locations: locs) {
            ctx.cgContext.drawRadialGradient(g, startCenter: c, startRadius: 0, endCenter: c, endRadius: radius, options: [.drawsAfterEndLocation])
        }
    }
}

func groundImage(_ size: CGSize) -> UIImage {
    let f = UIGraphicsImageRendererFormat.default()
    f.scale = 1
    let r = UIGraphicsImageRenderer(size: size, format: f)
    return r.image { ctx in
        let cs = CGColorSpaceCreateDeviceRGB()
        let colors: [UIColor] = [
            UIColor(red: 0.96, green: 0.66, blue: 0.38, alpha: 1),
            UIColor(red: 0.78, green: 0.50, blue: 0.30, alpha: 1),
            UIColor(red: 0.40, green: 0.25, blue: 0.16, alpha: 1)
        ]
        let locs: [CGFloat] = [0, 0.5, 1]
        let cg = colors.map { $0.cgColor } as CFArray
        if let g = CGGradient(colorsSpace: cs, colors: cg, locations: locs) {
            ctx.cgContext.drawLinearGradient(g, start: CGPoint(x: 0, y: 0), end: CGPoint(x: 0, y: size.height), options: [])
        }
        for _ in 0..<2600 {
            let x = CGFloat.random(in: 0..<size.width)
            let y = CGFloat.random(in: 0..<size.height)
            let a = CGFloat.random(in: 0.04...0.18)
            let dark = Bool.random()
            let col = dark ? UIColor(white: 0, alpha: a) : UIColor(white: 1, alpha: a * 0.6)
            ctx.cgContext.setFillColor(col.cgColor)
            let sz = CGFloat.random(in: 1...3)
            ctx.cgContext.fill(CGRect(x: x, y: y, width: sz, height: sz * 0.6))
        }
    }
}

// MARK: target pieces

enum TKind { case bottle, can, bandit, sheriff, pigeon }

final class GTarget {
    let node: SKNode
    let kind: TKind
    let w: CGFloat
    let h: CGFloat
    var life: CGFloat
    let key: Int
    var cover: SKNode?
    var vx: CGFloat = 0
    var vy: CGFloat = 0
    var hit = false

    init(node: SKNode, kind: TKind, w: CGFloat, h: CGFloat, life: CGFloat, key: Int) {
        self.node = node
        self.kind = kind
        self.w = w
        self.h = h
        self.life = life
        self.key = key
    }
}

func makeBottleNode() -> SKNode {
    let n = SKNode()
    let g = UIColor(red: 0.15, green: 0.55, blue: 0.25, alpha: 0.95)
    let gd = UIColor(red: 0.08, green: 0.35, blue: 0.16, alpha: 1)
    n.addChild(rectNode(-9, 0, 18, 34, g))
    n.addChild(poly([pt(-9, 34), pt(9, 34), pt(4, 46), pt(-4, 46)], g))
    n.addChild(rectNode(-4, 46, 8, 14, gd))
    n.addChild(rectNode(-5, 58, 10, 4, UIColor(red: 0.85, green: 0.70, blue: 0.30, alpha: 1)))
    n.addChild(rectNode(-9, 8, 18, 12, UIColor(red: 0.90, green: 0.85, blue: 0.70, alpha: 0.9)))
    n.addChild(rectNode(-6, 3, 3, 30, UIColor(white: 1, alpha: 0.35)))
    return n
}

func makeCanNode() -> SKNode {
    let n = SKNode()
    n.addChild(rectNode(-12, 0, 24, 30, UIColor(white: 0.70, alpha: 1)))
    n.addChild(rectNode(-12, 8, 24, 14, UIColor(red: 0.78, green: 0.18, blue: 0.14, alpha: 1)))
    n.addChild(rectNode(-12, 28, 24, 3, UIColor(white: 0.45, alpha: 1)))
    n.addChild(rectNode(-12, 0, 24, 3, UIColor(white: 0.45, alpha: 1)))
    n.addChild(rectNode(-8, 2, 3, 26, UIColor(white: 1, alpha: 0.45)))
    return n
}

func makeOutlawNode(sheriff: Bool) -> SKNode {
    let n = SKNode()
    let wood = UIColor(red: 0.45, green: 0.30, blue: 0.16, alpha: 1)
    let coat = sheriff ? UIColor(red: 0.62, green: 0.50, blue: 0.30, alpha: 1) : UIColor(red: 0.20, green: 0.15, blue: 0.14, alpha: 1)
    let hat = sheriff ? UIColor(red: 0.92, green: 0.88, blue: 0.78, alpha: 1) : UIColor(red: 0.10, green: 0.08, blue: 0.07, alpha: 1)
    let skin = UIColor(red: 0.80, green: 0.58, blue: 0.42, alpha: 1)
    n.addChild(rectNode(-4, 0, 8, 30, wood))
    n.addChild(poly([pt(-26, 24), pt(26, 24), pt(20, 70), pt(-20, 70)], coat, UIColor.black, 1.5))
    let head = SKShapeNode(circleOfRadius: 13)
    head.fillColor = skin
    head.strokeColor = UIColor.black
    head.lineWidth = 1.5
    head.position = pt(0, 82)
    n.addChild(head)
    if sheriff {
        n.addChild(poly(starPoints(pt(0, 52), 9, 4), UIColor(red: 1.0, green: 0.84, blue: 0.2, alpha: 1), UIColor.black, 1))
    } else {
        n.addChild(poly([pt(-13, 74), pt(13, 74), pt(10, 84), pt(-10, 84)], UIColor(red: 0.75, green: 0.12, blue: 0.10, alpha: 1)))
        n.addChild(rectNode(-20, 32, 40, 5, UIColor(red: 0.35, green: 0.22, blue: 0.10, alpha: 1)))
    }
    let brim = SKShapeNode(ellipseOf: CGSize(width: 42, height: 9))
    brim.fillColor = hat
    brim.strokeColor = UIColor.black
    brim.lineWidth = 1
    brim.position = pt(0, 91)
    n.addChild(brim)
    n.addChild(rectNode(-10, 91, 20, 13, hat))
    return n
}

func makeCrateNode() -> SKNode {
    let n = SKNode()
    let w = UIColor(red: 0.50, green: 0.33, blue: 0.17, alpha: 1)
    let d = UIColor(red: 0.28, green: 0.17, blue: 0.08, alpha: 1)
    n.addChild(rectNode(-32, 0, 64, 38, w))
    n.addChild(rectNode(-32, 0, 64, 4, d))
    n.addChild(rectNode(-32, 34, 64, 4, d))
    n.addChild(rectNode(-32, 0, 4, 38, d))
    n.addChild(rectNode(28, 0, 4, 38, d))
    n.addChild(rectNode(-1, 4, 2, 30, d))
    n.addChild(lineNode(pt(-28, 4), pt(28, 34), d, 3))
    return n
}

func makePigeonNode() -> SKNode {
    let n = SKNode()
    let d = SKShapeNode(ellipseOf: CGSize(width: 44, height: 14))
    d.fillColor = UIColor(red: 1.0, green: 0.45, blue: 0.10, alpha: 1)
    d.strokeColor = UIColor(red: 0.60, green: 0.20, blue: 0.05, alpha: 1)
    d.lineWidth = 2
    n.addChild(d)
    let top = SKShapeNode(ellipseOf: CGSize(width: 28, height: 6))
    top.fillColor = UIColor(red: 1.0, green: 0.70, blue: 0.30, alpha: 1)
    top.strokeColor = UIColor.clear
    top.position = pt(0, 2)
    n.addChild(top)
    return n
}

func makeCactusNode() -> SKNode {
    let n = SKNode()
    let g = UIColor(red: 0.12, green: 0.27, blue: 0.15, alpha: 1)
    let body = SKShapeNode(rectOf: CGSize(width: 12, height: 70), cornerRadius: 6)
    body.fillColor = g
    body.strokeColor = UIColor.clear
    body.position = pt(0, 35)
    n.addChild(body)
    let armL = SKShapeNode(rectOf: CGSize(width: 18, height: 8), cornerRadius: 4)
    armL.fillColor = g
    armL.strokeColor = UIColor.clear
    armL.position = pt(-12, 36)
    n.addChild(armL)
    let armLUp = SKShapeNode(rectOf: CGSize(width: 8, height: 24), cornerRadius: 4)
    armLUp.fillColor = g
    armLUp.strokeColor = UIColor.clear
    armLUp.position = pt(-18, 46)
    n.addChild(armLUp)
    let armR = SKShapeNode(rectOf: CGSize(width: 16, height: 8), cornerRadius: 4)
    armR.fillColor = g
    armR.strokeColor = UIColor.clear
    armR.position = pt(11, 24)
    n.addChild(armR)
    let armRUp = SKShapeNode(rectOf: CGSize(width: 8, height: 20), cornerRadius: 4)
    armRUp.fillColor = g
    armRUp.strokeColor = UIColor.clear
    armRUp.position = pt(15, 32)
    n.addChild(armRUp)
    return n
}

// MARK: SwiftUI wrapper

struct ShootView: View {
    var onExit: () -> Void
    @State private var scene: ShootScene = ShootScene.make()

    var body: some View {
        ZStack(alignment: .topLeading) {
            SpriteView(scene: scene)
                .ignoresSafeArea()
            Button(action: onExit) {
                Text("✕")
                    .font(.system(size: 20, weight: .bold))
                    .foregroundColor(.white)
                    .frame(width: 40, height: 40)
                    .background(Color.black.opacity(0.45))
                    .clipShape(Circle())
            }
            .padding(12)
        }
        .background(Color.black.ignoresSafeArea())
    }
}

// MARK: scene

final class ShootScene: SKScene {
    static func make() -> ShootScene {
        let s = ShootScene(size: UIScreen.main.bounds.size)
        s.scaleMode = .aspectFill
        return s
    }

    var world = SKNode()
    var horizonY: CGFloat = 0
    var rowY: [CGFloat] = []
    let rowScale: [CGFloat] = [0.55, 0.80, 1.10]
    let slotCount = 5

    var targets: [GTarget] = []
    var occupied = Set<Int>()

    var gun: SKNode!
    var gunBody: SKNode!
    var muzzle: SKNode!

    var ammo = 6
    var reloading = false
    var score = 0
    var combo = 0
    var timeLeft: CGFloat = 60
    var spawnTimer: CGFloat = 0.5
    var over = false
    var overDate = Date()
    var lastTime: TimeInterval = 0
    var didSetup = false

    var scoreLabel: SKLabelNode!
    var timerLabel: SKLabelNode!
    var comboLabel: SKLabelNode!
    var reloadLabel: SKLabelNode!
    var bullets: [SKSpriteNode] = []
    var reloadBtn: SKShapeNode!
    var overlay: SKNode?

    override func didMove(to view: SKView) {
        if !didSetup {
            didSetup = true
            setup()
        }
    }

    func after(_ t: TimeInterval, _ f: @escaping () -> Void) {
        run(SKAction.sequence([SKAction.wait(forDuration: t), SKAction.run(f)]))
    }

    // MARK: setup

    func setup() {
        horizonY = size.height * 0.50
        rowY = [size.height * 0.455, size.height * 0.37, size.height * 0.27]
        backgroundColor = UIColor.black
        addChild(world)
        buildScenery()
        buildGun()
        buildOverlays()
        buildHUD()
        newGame()
    }

    func ridge(baseY: CGFloat, minH: CGFloat, maxH: CGFloat, color: UIColor, z: CGFloat, step: CGFloat) -> SKShapeNode {
        let p = CGMutablePath()
        var x: CGFloat = -20
        var h = CGFloat.random(in: minH...maxH)
        p.move(to: CGPoint(x: x, y: baseY))
        p.addLine(to: CGPoint(x: x, y: baseY + h))
        while x < size.width + 20 {
            x += CGFloat.random(in: step...(step * 2.2))
            p.addLine(to: CGPoint(x: x, y: baseY + h))
            let nh = CGFloat.random(in: minH...maxH)
            x += CGFloat.random(in: 6...18)
            p.addLine(to: CGPoint(x: x, y: baseY + nh))
            h = nh
        }
        p.addLine(to: CGPoint(x: x, y: baseY))
        p.closeSubpath()
        let n = SKShapeNode(path: p)
        n.fillColor = color
        n.strokeColor = UIColor.clear
        n.zPosition = z
        return n
    }

    func buildScenery() {
        let w = size.width
        let h = size.height
        let cx = w / 2

        // sky
        let skyColors: [UIColor] = [
            UIColor(red: 0.10, green: 0.12, blue: 0.30, alpha: 1),
            UIColor(red: 0.40, green: 0.24, blue: 0.46, alpha: 1),
            UIColor(red: 0.93, green: 0.48, blue: 0.33, alpha: 1),
            UIColor(red: 1.00, green: 0.78, blue: 0.45, alpha: 1)
        ]
        let skyLocs: [CGFloat] = [0, 0.45, 0.80, 1]
        let sky = SKSpriteNode(texture: SKTexture(image: gradientImage(CGSize(width: 8, height: 256), skyColors, skyLocs)))
        sky.size = CGSize(width: w, height: h - horizonY + 60)
        sky.anchorPoint = CGPoint(x: 0.5, y: 0)
        sky.position = CGPoint(x: cx, y: horizonY - 60)
        sky.zPosition = -100
        world.addChild(sky)

        // sun + glow + god rays
        let sunPos = CGPoint(x: cx + 70, y: horizonY + 38)
        let glowColors: [UIColor] = [
            UIColor(red: 1.0, green: 0.85, blue: 0.50, alpha: 0.95),
            UIColor(red: 1.0, green: 0.55, blue: 0.25, alpha: 0.35),
            UIColor(red: 1.0, green: 0.40, blue: 0.20, alpha: 0.0)
        ]
        let glowLocs: [CGFloat] = [0, 0.35, 1]
        let glow = SKSpriteNode(texture: SKTexture(image: radialImage(CGSize(width: 256, height: 256), 128, glowColors, glowLocs)),
                                size: CGSize(width: 520, height: 520))
        glow.position = sunPos
        glow.zPosition = -96
        glow.blendMode = .add
        world.addChild(glow)

        let sun = SKShapeNode(circleOfRadius: 26)
        sun.fillColor = UIColor(red: 1.0, green: 0.96, blue: 0.80, alpha: 1)
        sun.strokeColor = UIColor.clear
        sun.position = sunPos
        sun.zPosition = -95
        world.addChild(sun)

        let angles: [CGFloat] = [-0.8, -0.4, 0.0, 0.4, 0.8]
        for a in angles {
            let len = h
            let p1 = CGPoint(x: sunPos.x + sin(a - 0.05) * len, y: sunPos.y + cos(a - 0.05) * len)
            let p2 = CGPoint(x: sunPos.x + sin(a + 0.05) * len, y: sunPos.y + cos(a + 0.05) * len)
            let beam = poly([sunPos, p1, p2], UIColor(white: 1, alpha: 0.07))
            beam.blendMode = .add
            beam.zPosition = -94
            world.addChild(beam)
        }

        // clouds
        for _ in 0..<5 {
            let cy = horizonY + CGFloat.random(in: 90...(h - horizonY - 40))
            let cw = CGFloat.random(in: 120...220)
            let cl = SKShapeNode(ellipseOf: CGSize(width: cw, height: cw * 0.16))
            cl.fillColor = UIColor(red: 1.0, green: 0.62, blue: 0.50, alpha: 0.35)
            cl.strokeColor = UIColor.clear
            cl.position = pt(CGFloat.random(in: 0...w), cy)
            cl.zPosition = -92
            world.addChild(cl)
            let dur = TimeInterval(CGFloat.random(in: 70...120))
            cl.run(SKAction.repeatForever(SKAction.sequence([
                SKAction.moveBy(x: -(w + 300), y: 0, duration: dur),
                SKAction.moveBy(x: w + 300, y: 0, duration: 0)
            ])))
        }

        // mesas
        world.addChild(ridge(baseY: horizonY - 4, minH: 45, maxH: 110, color: UIColor(red: 0.62, green: 0.36, blue: 0.42, alpha: 1), z: -90, step: 40))
        world.addChild(ridge(baseY: horizonY - 8, minH: 28, maxH: 70, color: UIColor(red: 0.48, green: 0.28, blue: 0.33, alpha: 1), z: -88, step: 60))
        world.addChild(ridge(baseY: horizonY - 14, minH: 14, maxH: 40, color: UIColor(red: 0.34, green: 0.20, blue: 0.24, alpha: 1), z: -86, step: 80))

        // horizon haze
        let hazeColors: [UIColor] = [
            UIColor(red: 1.0, green: 0.70, blue: 0.40, alpha: 0.0),
            UIColor(red: 1.0, green: 0.70, blue: 0.40, alpha: 0.55)
        ]
        let hazeLocs: [CGFloat] = [0, 1]
        let haze = SKSpriteNode(texture: SKTexture(image: gradientImage(CGSize(width: 8, height: 64), hazeColors, hazeLocs)))
        haze.size = CGSize(width: w, height: 110)
        haze.anchorPoint = CGPoint(x: 0.5, y: 0)
        haze.position = CGPoint(x: cx, y: horizonY - 14)
        haze.zPosition = -84
        world.addChild(haze)

        // ground
        let ground = SKSpriteNode(texture: SKTexture(image: groundImage(CGSize(width: 375, height: 512))))
        ground.size = CGSize(width: w, height: horizonY - 16)
        ground.anchorPoint = CGPoint(x: 0.5, y: 0)
        ground.position = CGPoint(x: cx, y: 0)
        ground.zPosition = -80
        world.addChild(ground)

        // cacti near the horizon
        for _ in 0..<5 {
            let c = makeCactusNode()
            let s = CGFloat.random(in: 0.5...0.95)
            c.setScale(s)
            c.position = pt(CGFloat.random(in: 10...(w - 10)), horizonY - 18 - CGFloat.random(in: 0...8))
            c.zPosition = -78
            c.alpha = 0.9
            world.addChild(c)
        }

        // rocks and dry grass
        for _ in 0..<16 {
            let rw = CGFloat.random(in: 6...16)
            let rock = SKShapeNode(ellipseOf: CGSize(width: rw, height: rw * 0.55))
            rock.fillColor = UIColor(red: 0.35, green: 0.22, blue: 0.15, alpha: 0.8)
            rock.strokeColor = UIColor.clear
            rock.position = pt(CGFloat.random(in: 0...w), CGFloat.random(in: 10...(horizonY - 40)))
            rock.zPosition = -70
            world.addChild(rock)
        }
        for _ in 0..<22 {
            let gx = CGFloat.random(in: 0...w)
            let gy = CGFloat.random(in: 10...(horizonY - 30))
            let tuft = poly([pt(-5, 0), pt(-2, 9), pt(0, 2), pt(3, 11), pt(5, 0)], UIColor(red: 0.55, green: 0.50, blue: 0.25, alpha: 0.85))
            tuft.position = pt(gx, gy)
            tuft.zPosition = -70
            world.addChild(tuft)
        }

        // tumbleweed
        let twColor = UIColor(red: 0.45, green: 0.32, blue: 0.18, alpha: 1)
        let tw = SKShapeNode(circleOfRadius: 11)
        tw.fillColor = UIColor.clear
        tw.strokeColor = twColor
        tw.lineWidth = 2
        tw.addChild(lineNode(pt(-10, -3), pt(10, 4), twColor, 1.5))
        tw.addChild(lineNode(pt(-4, -10), pt(5, 10), twColor, 1.5))
        tw.position = pt(-30, horizonY - 60)
        tw.zPosition = 5
        world.addChild(tw)
        tw.run(SKAction.repeatForever(SKAction.sequence([
            SKAction.group([
                SKAction.moveBy(x: w + 80, y: 0, duration: 9),
                SKAction.rotate(byAngle: -16, duration: 9)
            ]),
            SKAction.moveBy(x: -(w + 80), y: 0, duration: 0),
            SKAction.wait(forDuration: 4)
        ])))

        // fence rows
        for i in 0..<3 {
            let s = rowScale[i]
            let y = rowY[i]
            let rowZ = CGFloat(10 + i * 10)
            let plank = rectNode(-10, y - 10 * s, w + 20, 10 * s, UIColor(red: 0.42, green: 0.27, blue: 0.14, alpha: 1))
            plank.zPosition = rowZ
            world.addChild(plank)
            let low = rectNode(-10, y - 10 * s, w + 20, 2 * s, UIColor(red: 0.20, green: 0.12, blue: 0.07, alpha: 1))
            low.zPosition = rowZ
            world.addChild(low)
            let top = rectNode(-10, y - 2 * s, w + 20, 2 * s, UIColor(red: 0.62, green: 0.42, blue: 0.24, alpha: 1))
            top.zPosition = rowZ
            world.addChild(top)
            var px: CGFloat = 20
            while px < w {
                let post = rectNode(px - 5 * s, y - 52 * s, 10 * s, 42 * s, UIColor(red: 0.34, green: 0.21, blue: 0.11, alpha: 1))
                post.zPosition = rowZ - 1
                world.addChild(post)
                px += 78
            }
        }
    }

    func buildGun() {
        gun = SKNode()
        gun.position = pt(size.width / 2, -70)
        gun.zPosition = 80
        gun.setScale(0.85)
        addChild(gun)
        gunBody = SKNode()
        gun.addChild(gunBody)

        let steelD = UIColor(white: 0.14, alpha: 1)
        let steelM = UIColor(white: 0.30, alpha: 1)
        let steelL = UIColor(white: 0.58, alpha: 1)
        let wood = UIColor(red: 0.40, green: 0.22, blue: 0.11, alpha: 1)
        let woodL = UIColor(red: 0.58, green: 0.35, blue: 0.18, alpha: 1)
        let black = UIColor.black

        // grip
        gunBody.addChild(poly([pt(-32, -80), pt(32, -80), pt(23, 40), pt(-23, 40)], wood, black, 1.5))
        for i in 0..<5 {
            let x = CGFloat(i - 2) * 9
            gunBody.addChild(lineNode(pt(x * 0.85, -74), pt(x * 0.7, 36), woodL.withAlphaComponent(0.55), 1.5))
        }
        // frame
        gunBody.addChild(poly([pt(-27, 30), pt(27, 30), pt(25, 96), pt(-25, 96)], steelM, black, 1.5))
        gunBody.addChild(poly([pt(-27, 30), pt(-14, 30), pt(-14, 96), pt(-25, 96)], steelD))
        // hammer
        gunBody.addChild(poly([pt(-6, 92), pt(6, 92), pt(9, 112), pt(-1, 120), pt(-9, 104)], steelD, black, 1))
        // cylinder
        let cyl = SKShapeNode(rectOf: CGSize(width: 62, height: 54), cornerRadius: 9)
        cyl.fillColor = steelM
        cyl.strokeColor = black
        cyl.lineWidth = 1.5
        cyl.position = pt(0, 120)
        gunBody.addChild(cyl)
        for i in 0..<5 {
            let x = CGFloat(i - 2) * 12
            gunBody.addChild(lineNode(pt(x, 98), pt(x, 142), steelD, 2))
        }
        gunBody.addChild(lineNode(pt(-26, 142), pt(26, 142), steelL, 2))
        // barrel
        gunBody.addChild(poly([pt(-15, 146), pt(15, 146), pt(9, 300), pt(-9, 300)], steelD, black, 1.5))
        gunBody.addChild(poly([pt(-9, 146), pt(-3, 146), pt(-2, 298), pt(-6, 298)], steelL))
        gunBody.addChild(poly([pt(-3, 146), pt(3, 146), pt(2, 300), pt(-2, 300)], steelM))
        // sights
        gunBody.addChild(poly([pt(-4, 300), pt(4, 300), pt(0, 316)], steelD, black, 1))
        gunBody.addChild(poly([pt(-12, 146), pt(-5, 146), pt(-5, 156), pt(-12, 156)], steelD))
        gunBody.addChild(poly([pt(5, 146), pt(12, 146), pt(12, 156), pt(5, 156)], steelD))

        muzzle = SKNode()
        muzzle.position = pt(0, 316)
        gunBody.addChild(muzzle)
    }

    func buildOverlays() {
        let center = CGPoint(x: size.width / 2, y: size.height / 2)
        let vigColors: [UIColor] = [UIColor(white: 0, alpha: 0), UIColor(white: 0, alpha: 0), UIColor(white: 0, alpha: 0.62)]
        let vigLocs: [CGFloat] = [0, 0.55, 1]
        let vig = SKSpriteNode(texture: SKTexture(image: radialImage(CGSize(width: 256, height: 512), hypot(128, 256), vigColors, vigLocs)),
                               size: size)
        vig.position = center
        vig.zPosition = 90
        addChild(vig)

        let tint = SKSpriteNode(color: UIColor(red: 1.0, green: 0.55, blue: 0.20, alpha: 0.07), size: size)
        tint.position = center
        tint.zPosition = 91
        addChild(tint)

        for _ in 0..<22 {
            let r = CGFloat.random(in: 1...2.5)
            let m = SKShapeNode(circleOfRadius: r)
            m.fillColor = UIColor(red: 1.0, green: 0.92, blue: 0.75, alpha: CGFloat.random(in: 0.2...0.45))
            m.strokeColor = UIColor.clear
            m.position = pt(CGFloat.random(in: 0...size.width), CGFloat.random(in: 0...size.height))
            m.zPosition = 85
            addChild(m)
            let dx = CGFloat.random(in: -40...40)
            let dy = CGFloat.random(in: -20...40)
            let d = TimeInterval(CGFloat.random(in: 6...12))
            m.run(SKAction.repeatForever(SKAction.sequence([
                SKAction.moveBy(x: dx, y: dy, duration: d),
                SKAction.moveBy(x: -dx, y: -dy, duration: d)
            ])))
        }
    }

    func buildHUD() {
        scoreLabel = westernLabel("0", 36, UIColor.white)
        scoreLabel.position = pt(size.width / 2, size.height - 102)
        scoreLabel.zPosition = 100
        addChild(scoreLabel)

        timerLabel = westernLabel("60", 28, UIColor.yellow)
        timerLabel.horizontalAlignmentMode = .right
        timerLabel.position = pt(size.width - 18, size.height - 98)
        timerLabel.zPosition = 100
        addChild(timerLabel)

        comboLabel = westernLabel("", 20, UIColor(red: 1.0, green: 0.85, blue: 0.3, alpha: 1))
        comboLabel.position = pt(size.width / 2, size.height - 132)
        comboLabel.zPosition = 100
        addChild(comboLabel)

        reloadLabel = westernLabel("RELOADING...", 22, UIColor.white)
        reloadLabel.position = pt(size.width / 2, size.height * 0.60)
        reloadLabel.zPosition = 100
        reloadLabel.isHidden = true
        addChild(reloadLabel)

        for i in 0..<6 {
            let b = SKSpriteNode(color: UIColor(red: 0.88, green: 0.68, blue: 0.22, alpha: 1), size: CGSize(width: 9, height: 24))
            b.anchorPoint = CGPoint(x: 0, y: 0)
            b.position = pt(18 + CGFloat(i) * 15, 40)
            b.zPosition = 100
            addChild(b)
            bullets.append(b)
        }

        reloadBtn = SKShapeNode(rectOf: CGSize(width: 84, height: 36), cornerRadius: 10)
        reloadBtn.fillColor = UIColor(white: 0, alpha: 0.45)
        reloadBtn.strokeColor = UIColor(white: 1, alpha: 0.7)
        reloadBtn.lineWidth = 2
        reloadBtn.position = pt(size.width - 56, 52)
        reloadBtn.zPosition = 100
        let rl = westernLabel("RELOAD", 14, UIColor.white)
        rl.verticalAlignmentMode = .center
        reloadBtn.addChild(rl)
        addChild(reloadBtn)
    }

    func updateHUD() {
        scoreLabel.text = "\(score)"
        timerLabel.text = "\(Int(ceil(timeLeft)))"
        if combo >= 3 {
            comboLabel.text = "COMBO x\(min(5, 1 + combo / 3))"
        } else {
            comboLabel.text = ""
        }
        for i in 0..<bullets.count {
            bullets[i].alpha = i < ammo ? 1.0 : 0.18
        }
    }

    // MARK: game flow

    func newGame() {
        removeAllActions()
        for t in targets {
            t.node.removeFromParent()
            t.cover?.removeFromParent()
        }
        targets.removeAll()
        occupied.removeAll()
        overlay?.removeFromParent()
        overlay = nil
        score = 0
        combo = 0
        ammo = 6
        reloading = false
        timeLeft = 60
        spawnTimer = 0.6
        over = false
        lastTime = 0
        gun.zRotation = 0
        gunBody.removeAllActions()
        gunBody.position = CGPoint.zero
        gunBody.zRotation = 0
        reloadLabel.isHidden = true
        updateHUD()
    }

    func endGame() {
        over = true
        overDate = Date()
        let best = max(score, UserDefaults.standard.integer(forKey: "bestShoot"))
        UserDefaults.standard.set(best, forKey: "bestShoot")
        let rank: String
        if score >= 600 {
            rank = "Legend of the West"
        } else if score >= 350 {
            rank = "Gunslinger"
        } else if score >= 150 {
            rank = "Deputy"
        } else {
            rank = "Greenhorn"
        }

        let o = SKNode()
        o.zPosition = 200
        let dim = SKSpriteNode(color: UIColor(white: 0, alpha: 0.72), size: size)
        dim.position = pt(size.width / 2, size.height / 2)
        o.addChild(dim)

        let t1 = westernLabel("TIME'S UP", 40, UIColor.white)
        t1.position = pt(size.width / 2, size.height * 0.62)
        o.addChild(t1)
        let t2 = westernLabel(rank, 24, UIColor(red: 1.0, green: 0.85, blue: 0.3, alpha: 1))
        t2.position = pt(size.width / 2, size.height * 0.56)
        o.addChild(t2)
        let t3 = westernLabel("Score: \(score)", 28, UIColor.white)
        t3.position = pt(size.width / 2, size.height * 0.50)
        o.addChild(t3)
        let t4 = westernLabel("Best: \(best)", 22, UIColor.lightGray)
        t4.position = pt(size.width / 2, size.height * 0.45)
        o.addChild(t4)
        let t5 = westernLabel("tap to play again", 20, UIColor.lightGray)
        t5.position = pt(size.width / 2, size.height * 0.38)
        o.addChild(t5)

        addChild(o)
        overlay = o
    }

    // MARK: spawning

    func spawnTarget() {
        if Int.random(in: 0..<100) < 18 {
            spawnPigeon()
            return
        }
        let row = Int.random(in: 0..<3)
        let slot = Int.random(in: 0..<slotCount)
        let key = row * 10 + slot
        if occupied.contains(key) { return }
        occupied.insert(key)
        let s = rowScale[row]
        let y = rowY[row]
        let x = size.width * (0.12 + 0.19 * CGFloat(slot)) + CGFloat.random(in: -6...6)
        let roll = Int.random(in: 0..<100)
        let rowZ = CGFloat(10 + row * 10)
        let t: GTarget
        if roll < 30 {
            let n = makeBottleNode()
            n.position = pt(x, y)
            n.setScale(s)
            n.zPosition = rowZ + 1
            world.addChild(n)
            t = GTarget(node: n, kind: .bottle, w: 18, h: 62, life: CGFloat.random(in: 2.2...3.5), key: key)
        } else if roll < 55 {
            let n = makeCanNode()
            n.position = pt(x, y)
            n.setScale(s)
            n.zPosition = rowZ + 1
            world.addChild(n)
            t = GTarget(node: n, kind: .can, w: 24, h: 31, life: CGFloat.random(in: 2.2...3.5), key: key)
        } else {
            let sheriff = roll >= 85
            let n = makeOutlawNode(sheriff: sheriff)
            n.setScale(s)
            n.position = pt(x, y - 100 * s)
            n.zPosition = rowZ + 1
            world.addChild(n)
            let cover = makeCrateNode()
            cover.setScale(s)
            cover.position = pt(x, y)
            cover.zPosition = rowZ + 2
            world.addChild(cover)
            let rise = SKAction.moveTo(y: y, duration: 0.22)
            rise.timingMode = .easeOut
            n.run(rise)
            t = GTarget(node: n, kind: sheriff ? .sheriff : .bandit, w: 56, h: 104, life: CGFloat.random(in: 1.3...2.0), key: key)
            t.cover = cover
        }
        targets.append(t)
    }

    func spawnPigeon() {
        let fromLeft = Bool.random()
        let y = CGFloat.random(in: (size.height * 0.58)...(size.height * 0.80))
        let s = CGFloat.random(in: 0.8...1.2)
        let n = makePigeonNode()
        n.setScale(s)
        n.position = pt(fromLeft ? -30 : size.width + 30, y)
        n.zPosition = 40
        world.addChild(n)
        let t = GTarget(node: n, kind: .pigeon, w: 44, h: 14, life: 10, key: -1)
        t.vx = (fromLeft ? 1 : -1) * CGFloat.random(in: 150...230)
        t.vy = CGFloat.random(in: 10...50)
        targets.append(t)
    }

    // MARK: shooting

    func hitTest(_ p: CGPoint, _ t: GTarget) -> Bool {
        let s = t.node.xScale
        let n = t.node.position
        if t.kind == .pigeon {
            return hypot(p.x - n.x, p.y - n.y) < 30 * s + 8
        }
        let pad: CGFloat = 10
        if abs(p.x - n.x) > t.w * s / 2 + pad { return false }
        var low = n.y - pad
        if t.kind == .bandit || t.kind == .sheriff {
            low = n.y + 36 * s
        }
        return p.y >= low && p.y <= n.y + t.h * s + pad
    }

    func fire(at p: CGPoint) {
        if ammo <= 0 || reloading || over { return }
        ammo -= 1
        aimGun(at: p)
        muzzleFlash()
        recoil()
        shake()
        tracer(to: p)
        UIImpactFeedbackGenerator(style: .medium).impactOccurred()

        var best: GTarget?
        for t in targets {
            if t.hit || !hitTest(p, t) { continue }
            if let b = best, t.node.zPosition <= b.node.zPosition { continue }
            best = t
        }
        if let b = best {
            hitTarget(b, at: p)
        } else {
            missAt(p)
        }
        updateHUD()
        if ammo == 0 {
            startReload()
        }
    }

    func aimGun(at p: CGPoint) {
        let dx = p.x - gun.position.x
        let dy = max(40, p.y - gun.position.y)
        var ang = -atan2(dx, dy)
        ang = max(-0.5, min(0.5, ang))
        gun.zRotation = ang
    }

    func recoil() {
        gunBody.removeAllActions()
        let kick = SKAction.group([
            SKAction.moveBy(x: 0, y: -18, duration: 0.04),
            SKAction.rotate(toAngle: 0.07, duration: 0.04)
        ])
        let back = SKAction.group([
            SKAction.move(to: CGPoint.zero, duration: 0.14),
            SKAction.rotate(toAngle: 0, duration: 0.14)
        ])
        gunBody.run(SKAction.sequence([kick, back]))
    }

    func shake() {
        world.removeAllActions()
        world.position = CGPoint.zero
        world.run(SKAction.sequence([
            SKAction.moveBy(x: 4, y: 5, duration: 0.03),
            SKAction.moveBy(x: -8, y: -10, duration: 0.03),
            SKAction.moveBy(x: 4, y: 5, duration: 0.03)
        ]))
    }

    func muzzleFlash() {
        let f = SKNode()
        let outer = poly(starPoints(pt(0, 0), 46, 16), UIColor(red: 1.0, green: 0.55, blue: 0.10, alpha: 0.9))
        outer.blendMode = .add
        let mid = poly(starPoints(pt(0, 0), 32, 11), UIColor(red: 1.0, green: 0.85, blue: 0.30, alpha: 1))
        mid.blendMode = .add
        let core = SKShapeNode(circleOfRadius: 12)
        core.fillColor = UIColor.white
        core.strokeColor = UIColor.clear
        f.addChild(outer)
        f.addChild(mid)
        f.addChild(core)
        f.zRotation = CGFloat.random(in: 0..<(2 * CGFloat.pi))
        f.setScale(0.4)
        muzzle.addChild(f)
        f.run(SKAction.sequence([
            SKAction.scale(to: 1.1, duration: 0.04),
            SKAction.fadeOut(withDuration: 0.06),
            SKAction.removeFromParent()
        ]))

        let mp = muzzle.convert(CGPoint.zero, to: self)
        for _ in 0..<5 {
            let sm = SKShapeNode(circleOfRadius: CGFloat.random(in: 6...11))
            sm.fillColor = UIColor(white: 0.85, alpha: 0.45)
            sm.strokeColor = UIColor.clear
            sm.position = mp
            sm.zPosition = 79
            addChild(sm)
            sm.run(SKAction.sequence([
                SKAction.group([
                    SKAction.moveBy(x: CGFloat.random(in: -25...25), y: CGFloat.random(in: 30...80), duration: 0.9),
                    SKAction.scale(to: 3.5, duration: 0.9),
                    SKAction.fadeOut(withDuration: 0.9)
                ]),
                SKAction.removeFromParent()
            ]))
        }

        let flash = SKSpriteNode(color: UIColor.white, size: size)
        flash.position = pt(size.width / 2, size.height / 2)
        flash.zPosition = 95
        flash.alpha = 0.18
        addChild(flash)
        flash.run(SKAction.sequence([SKAction.fadeOut(withDuration: 0.1), SKAction.removeFromParent()]))
    }

    func tracer(to p: CGPoint) {
        let from = muzzle.convert(CGPoint.zero, to: self)
        let l = lineNode(from, p, UIColor(red: 1.0, green: 0.90, blue: 0.60, alpha: 0.8), 2)
        l.zPosition = 70
        addChild(l)
        l.run(SKAction.sequence([SKAction.fadeOut(withDuration: 0.1), SKAction.removeFromParent()]))
    }

    func startReload() {
        if reloading || ammo == 6 { return }
        reloading = true
        reloadLabel.isHidden = false
        gunBody.removeAllActions()
        gunBody.run(SKAction.sequence([
            SKAction.moveBy(x: 0, y: -40, duration: 0.2),
            SKAction.wait(forDuration: 0.7),
            SKAction.move(to: CGPoint.zero, duration: 0.2)
        ]))
        after(1.1) {
            self.ammo = 6
            self.reloading = false
            self.reloadLabel.isHidden = true
            self.updateHUD()
        }
    }

    // MARK: hits and effects

    func registerHit(_ pts: Int, at p: CGPoint) {
        if pts < 0 {
            combo = 0
            score = max(0, score + pts)
            popup("\(pts)", at: p, color: UIColor.red)
            return
        }
        combo += 1
        let mult = min(5, 1 + combo / 3)
        let gained = pts * mult
        score += gained
        popup(mult > 1 ? "+\(gained) x\(mult)" : "+\(gained)", at: p, color: UIColor.yellow)
    }

    func hitTarget(_ t: GTarget, at p: CGPoint) {
        t.hit = true
        targets.removeAll(where: { $0 === t })
        occupied.remove(t.key)
        let s = t.node.xScale
        let np = t.node.position
        switch t.kind {
        case .bottle:
            shatter(at: CGPoint(x: np.x, y: np.y + 30 * s), color: UIColor(red: 0.2, green: 0.7, blue: 0.3, alpha: 0.9), count: 12, size: 7 * s)
            t.node.removeFromParent()
            registerHit(10, at: p)
        case .can:
            let up = SKAction.moveBy(x: CGFloat.random(in: -50...50), y: 100, duration: 0.25)
            up.timingMode = .easeOut
            let down = SKAction.moveBy(x: 0, y: -260, duration: 0.35)
            down.timingMode = .easeIn
            t.node.run(SKAction.sequence([
                SKAction.group([SKAction.sequence([up, down]), SKAction.rotate(byAngle: 9, duration: 0.6)]),
                SKAction.removeFromParent()
            ]))
            shatter(at: p, color: UIColor(red: 1.0, green: 0.9, blue: 0.5, alpha: 1), count: 6, size: 4 * s)
            registerHit(5, at: p)
        case .bandit, .sheriff:
            let drop = SKAction.moveBy(x: 0, y: -t.h * s, duration: 0.2)
            drop.timingMode = .easeIn
            t.node.run(SKAction.sequence([drop, SKAction.removeFromParent()]))
            t.cover?.run(SKAction.sequence([SKAction.wait(forDuration: 0.3), SKAction.removeFromParent()]))
            shatter(at: p, color: UIColor(red: 0.5, green: 0.33, blue: 0.17, alpha: 1), count: 8, size: 5 * s)
            registerHit(t.kind == .bandit ? 25 : -30, at: p)
        case .pigeon:
            shatter(at: np, color: UIColor(red: 1.0, green: 0.5, blue: 0.1, alpha: 1), count: 14, size: 6 * s)
            t.node.removeFromParent()
            registerHit(15, at: p)
        }
    }

    func despawn(_ t: GTarget) {
        occupied.remove(t.key)
        let s = t.node.xScale
        switch t.kind {
        case .bandit, .sheriff:
            let drop = SKAction.moveBy(x: 0, y: -t.h * s, duration: 0.22)
            drop.timingMode = .easeIn
            t.node.run(SKAction.sequence([drop, SKAction.removeFromParent()]))
            t.cover?.run(SKAction.sequence([SKAction.wait(forDuration: 0.3), SKAction.removeFromParent()]))
        case .bottle, .can:
            t.node.run(SKAction.sequence([SKAction.fadeOut(withDuration: 0.25), SKAction.removeFromParent()]))
        case .pigeon:
            t.node.removeFromParent()
        }
    }

    func missAt(_ p: CGPoint) {
        combo = 0
        if p.y < horizonY - 10 {
            dustPuff(at: p)
            let h = SKShapeNode(circleOfRadius: 3)
            h.fillColor = UIColor(white: 0.05, alpha: 0.9)
            h.strokeColor = UIColor(white: 0, alpha: 0.35)
            h.lineWidth = 2
            h.position = p
            h.zPosition = 2
            world.addChild(h)
            h.run(SKAction.sequence([
                SKAction.wait(forDuration: 3),
                SKAction.fadeOut(withDuration: 1),
                SKAction.removeFromParent()
            ]))
        }
    }

    func dustPuff(at p: CGPoint) {
        for _ in 0..<7 {
            let d = SKShapeNode(circleOfRadius: CGFloat.random(in: 4...9))
            d.fillColor = UIColor(red: 0.85, green: 0.65, blue: 0.45, alpha: 0.7)
            d.strokeColor = UIColor.clear
            d.position = p
            d.zPosition = 48
            world.addChild(d)
            d.run(SKAction.sequence([
                SKAction.group([
                    SKAction.moveBy(x: CGFloat.random(in: -30...30), y: CGFloat.random(in: 10...40), duration: 0.5),
                    SKAction.scale(to: 2.5, duration: 0.5),
                    SKAction.fadeOut(withDuration: 0.5)
                ]),
                SKAction.removeFromParent()
            ]))
        }
    }

    func shatter(at p: CGPoint, color: UIColor, count: Int, size sz: CGFloat) {
        for _ in 0..<count {
            let s = poly([pt(0, 0), pt(sz, sz * 0.3), pt(sz * 0.3, sz)], color)
            s.position = p
            s.zPosition = 50
            world.addChild(s)
            let ang = CGFloat.random(in: 0..<(2 * CGFloat.pi))
            let sp = CGFloat.random(in: 40...140)
            let dx = cos(ang) * sp
            let dy = sin(ang) * sp + 60
            let up = SKAction.moveBy(x: dx * 0.5, y: dy, duration: 0.22)
            up.timingMode = .easeOut
            let down = SKAction.moveBy(x: dx * 0.5, y: -dy * 1.6, duration: 0.3)
            down.timingMode = .easeIn
            s.run(SKAction.sequence([
                SKAction.group([
                    SKAction.sequence([up, down]),
                    SKAction.rotate(byAngle: CGFloat.random(in: -8...8), duration: 0.52),
                    SKAction.fadeOut(withDuration: 0.52)
                ]),
                SKAction.removeFromParent()
            ]))
        }
    }

    func popup(_ text: String, at p: CGPoint, color: UIColor) {
        let l = westernLabel(text, 26, color)
        l.position = p
        l.zPosition = 60
        addChild(l)
        l.run(SKAction.sequence([
            SKAction.group([SKAction.moveBy(x: 0, y: 60, duration: 0.7), SKAction.fadeOut(withDuration: 0.7)]),
            SKAction.removeFromParent()
        ]))
    }

    // MARK: input and loop

    override func touchesBegan(_ touches: Set<UITouch>, with event: UIEvent?) {
        guard let touch = touches.first else { return }
        if over {
            if Date().timeIntervalSince(overDate) > 0.7 {
                newGame()
            }
            return
        }
        let p = touch.location(in: self)
        if reloadBtn.contains(p) {
            startReload()
            return
        }
        fire(at: p)
    }

    override func update(_ currentTime: TimeInterval) {
        if lastTime == 0 {
            lastTime = currentTime
            return
        }
        var dt = CGFloat(currentTime - lastTime)
        lastTime = currentTime
        if dt > 0.05 { dt = 0.05 }
        if dt <= 0 || over { return }

        timeLeft -= dt
        if timeLeft <= 0 {
            timeLeft = 0
            updateHUD()
            endGame()
            return
        }
        timerLabel.text = "\(Int(ceil(timeLeft)))"

        spawnTimer -= dt
        if spawnTimer <= 0 {
            spawnTarget()
            spawnTimer = CGFloat.random(in: 0.35...0.8)
        }

        var keep: [GTarget] = []
        for t in targets {
            if t.kind == .pigeon {
                t.node.position = CGPoint(x: t.node.position.x + t.vx * dt, y: t.node.position.y + t.vy * dt)
                t.vy -= 30 * dt
                if t.node.position.x < -70 || t.node.position.x > size.width + 70 || t.node.position.y < horizonY {
                    t.node.removeFromParent()
                    continue
                }
                keep.append(t)
                continue
            }
            t.life -= dt
            if t.life <= 0 {
                despawn(t)
                continue
            }
            keep.append(t)
        }
        targets = keep
    }
}

// MARK: - Crime city: helpers and art

func gDist(_ a: CGPoint, _ b: CGPoint) -> CGFloat {
    return hypot(a.x - b.x, a.y - b.y)
}

func gAngle(_ a: CGPoint, _ b: CGPoint) -> CGFloat {
    return atan2(b.y - a.y, b.x - a.x)
}

func gVec(_ a: CGFloat, _ l: CGFloat) -> CGVector {
    return CGVector(dx: cos(a) * l, dy: sin(a) * l)
}

func gClamp(_ v: CGFloat, _ lo: CGFloat, _ hi: CGFloat) -> CGFloat {
    return max(lo, min(hi, v))
}

func gAngDiff(_ a: CGFloat, _ b: CGFloat) -> CGFloat {
    var d = a - b
    while d > CGFloat.pi { d -= 2 * CGFloat.pi }
    while d < -CGFloat.pi { d += 2 * CGFloat.pi }
    return d
}

let CITY: CGFloat = 2400
let PITCH: CGFloat = 400

enum CarType: Int { case sports, muscle, police, truck, van, bike, tank, swat }

struct CarSpec {
    let len: CGFloat
    let wid: CGFloat
    let maxSpeed: CGFloat
    let accel: CGFloat
    let turn: CGFloat
    let hp: CGFloat
    let radius: CGFloat
}

func carSpec(_ t: CarType) -> CarSpec {
    switch t {
    case .sports: return CarSpec(len: 54, wid: 26, maxSpeed: 430, accel: 560, turn: 2.9, hp: 260, radius: 16)
    case .muscle: return CarSpec(len: 58, wid: 28, maxSpeed: 390, accel: 480, turn: 2.5, hp: 330, radius: 17)
    case .police: return CarSpec(len: 56, wid: 27, maxSpeed: 410, accel: 520, turn: 2.7, hp: 330, radius: 17)
    case .truck: return CarSpec(len: 88, wid: 34, maxSpeed: 270, accel: 270, turn: 1.6, hp: 650, radius: 22)
    case .van: return CarSpec(len: 64, wid: 31, maxSpeed: 310, accel: 320, turn: 1.9, hp: 420, radius: 19)
    case .swat: return CarSpec(len: 66, wid: 32, maxSpeed: 330, accel: 330, turn: 1.9, hp: 600, radius: 20)
    case .bike: return CarSpec(len: 40, wid: 16, maxSpeed: 460, accel: 640, turn: 3.5, hp: 120, radius: 9)
    case .tank: return CarSpec(len: 92, wid: 46, maxSpeed: 110, accel: 120, turn: 0.9, hp: 1400, radius: 26)
    }
}

func shade(_ c: UIColor, _ f: CGFloat) -> UIColor {
    var r: CGFloat = 0
    var g: CGFloat = 0
    var b: CGFloat = 0
    var a: CGFloat = 0
    _ = c.getRed(&r, green: &g, blue: &b, alpha: &a)
    return UIColor(red: min(1, r * f), green: min(1, g * f), blue: min(1, b * f), alpha: a)
}

func fillGradientPath(_ c: CGContext, _ path: UIBezierPath, _ top: UIColor, _ bottom: UIColor) {
    let b = path.bounds
    let cs = CGColorSpaceCreateDeviceRGB()
    let cols = [top.cgColor, bottom.cgColor] as CFArray
    let locs: [CGFloat] = [0, 1]
    if let g = CGGradient(colorsSpace: cs, colors: cols, locations: locs) {
        c.saveGState()
        path.addClip()
        c.drawLinearGradient(g, start: CGPoint(x: b.minX, y: b.minY), end: CGPoint(x: b.minX, y: b.maxY), options: [])
        c.restoreGState()
    }
}

func drawGlow(_ c: CGContext, _ p: CGPoint, _ radius: CGFloat, _ color: UIColor, _ alpha: CGFloat) {
    let cs = CGColorSpaceCreateDeviceRGB()
    let cols = [color.withAlphaComponent(alpha).cgColor, color.withAlphaComponent(0).cgColor] as CFArray
    let locs: [CGFloat] = [0, 1]
    if let g = CGGradient(colorsSpace: cs, colors: cols, locations: locs) {
        c.drawRadialGradient(g, startCenter: p, startRadius: 0, endCenter: p, endRadius: radius, options: [])
    }
}

func drawRoofText(_ c: CGContext, _ s: String, _ center: CGPoint, _ size: CGFloat, _ color: UIColor) {
    c.saveGState()
    c.translateBy(x: center.x, y: center.y)
    c.scaleBy(x: 1, y: -1)
    let attrs: [NSAttributedString.Key: Any] = [.font: UIFont.boldSystemFont(ofSize: size), .foregroundColor: color]
    let ns = NSString(string: s)
    let sz = ns.size(withAttributes: attrs)
    ns.draw(at: CGPoint(x: -sz.width / 2, y: -sz.height / 2), withAttributes: attrs)
    c.restoreGState()
}

// MARK: vehicle and character textures

func carImage(_ type: CarType, _ color: UIColor) -> UIImage {
    let sp = carSpec(type)
    let L = sp.len
    let W = sp.wid
    let f = UIGraphicsImageRendererFormat.default()
    f.scale = 3
    f.opaque = false
    let r = UIGraphicsImageRenderer(size: CGSize(width: L, height: W), format: f)
    return r.image { rc in
        let c = rc.cgContext
        let black = UIColor(white: 0.05, alpha: 1)
        let glass = UIColor(red: 0.07, green: 0.10, blue: 0.16, alpha: 1)

        if type == .bike {
            c.setFillColor(black.cgColor)
            c.fill(CGRect(x: 2, y: W * 0.38, width: L * 0.2, height: W * 0.24))
            c.fill(CGRect(x: L * 0.78, y: W * 0.38, width: L * 0.2, height: W * 0.24))
            let body = UIBezierPath(roundedRect: CGRect(x: L * 0.18, y: W * 0.28, width: L * 0.6, height: W * 0.44), cornerRadius: W * 0.2)
            fillGradientPath(c, body, shade(color, 1.25), shade(color, 0.7))
            c.setFillColor(UIColor(white: 0.2, alpha: 1).cgColor)
            c.fill(CGRect(x: L * 0.66, y: W * 0.06, width: 3, height: W * 0.88))
            c.setFillColor(UIColor(red: 0.15, green: 0.15, blue: 0.2, alpha: 1).cgColor)
            c.fillEllipse(in: CGRect(x: L * 0.34, y: W * 0.1, width: L * 0.26, height: W * 0.8))
            c.setFillColor(UIColor(red: 0.9, green: 0.75, blue: 0.6, alpha: 1).cgColor)
            c.fillEllipse(in: CGRect(x: L * 0.42, y: W * 0.3, width: L * 0.14, height: W * 0.4))
            return
        }

        if type == .tank {
            c.setFillColor(UIColor(white: 0.12, alpha: 1).cgColor)
            c.fill(CGRect(x: 2, y: 1, width: L - 4, height: W * 0.2))
            c.fill(CGRect(x: 2, y: W * 0.8 - 1, width: L - 4, height: W * 0.2))
            let hull = UIBezierPath(roundedRect: CGRect(x: 4, y: W * 0.16, width: L - 8, height: W * 0.68), cornerRadius: 6)
            fillGradientPath(c, hull, UIColor(red: 0.38, green: 0.42, blue: 0.24, alpha: 1), UIColor(red: 0.2, green: 0.24, blue: 0.12, alpha: 1))
            c.setStrokeColor(UIColor(white: 0, alpha: 0.4).cgColor)
            c.setLineWidth(1)
            var x: CGFloat = 8
            while x < L - 6 {
                c.move(to: CGPoint(x: x, y: 2))
                c.addLine(to: CGPoint(x: x, y: W * 0.2))
                c.move(to: CGPoint(x: x, y: W * 0.8))
                c.addLine(to: CGPoint(x: x, y: W - 2))
                x += 7
            }
            c.strokePath()
            return
        }

        // wheels poking out
        c.setFillColor(black.cgColor)
        let wy: [CGFloat] = [0.3, 0.7]
        for fx in wy {
            c.fill(CGRect(x: L * 0.14, y: 0.3, width: L * 0.16, height: 2.6))
            c.fill(CGRect(x: L * 0.14, y: W - 2.9, width: L * 0.16, height: 2.6))
            c.fill(CGRect(x: L * 0.68, y: 0.3, width: L * 0.16, height: 2.6))
            c.fill(CGRect(x: L * 0.68, y: W - 2.9, width: L * 0.16, height: 2.6))
            _ = fx
        }

        if type == .truck {
            let box = UIBezierPath(roundedRect: CGRect(x: 1, y: 1.5, width: L * 0.66, height: W - 3), cornerRadius: 3)
            fillGradientPath(c, box, UIColor(white: 0.93, alpha: 1), UIColor(white: 0.70, alpha: 1))
            c.setStrokeColor(UIColor(white: 0.45, alpha: 0.8).cgColor)
            c.setLineWidth(0.7)
            var x: CGFloat = 8
            while x < L * 0.66 {
                c.move(to: CGPoint(x: x, y: 2.5))
                c.addLine(to: CGPoint(x: x, y: W - 2.5))
                x += 9
            }
            c.strokePath()
            let cab = UIBezierPath(roundedRect: CGRect(x: L * 0.68, y: 2, width: L * 0.31, height: W - 4), cornerRadius: 5)
            fillGradientPath(c, cab, shade(color, 1.3), shade(color, 0.7))
            c.setFillColor(glass.cgColor)
            c.fill(CGRect(x: L * 0.86, y: W * 0.14, width: L * 0.1, height: W * 0.72))
            c.setFillColor(UIColor(white: 1, alpha: 0.9).cgColor)
            c.fillEllipse(in: CGRect(x: L * 0.965, y: W * 0.12, width: 2.5, height: 4))
            c.fillEllipse(in: CGRect(x: L * 0.965, y: W * 0.88 - 4, width: 2.5, height: 4))
            c.setFillColor(UIColor(red: 0.9, green: 0.1, blue: 0.1, alpha: 1).cgColor)
            c.fill(CGRect(x: 0.5, y: W * 0.1, width: 1.5, height: 4))
            c.fill(CGRect(x: 0.5, y: W * 0.9 - 4, width: 1.5, height: 4))
            return
        }

        // body
        let body = UIBezierPath(roundedRect: CGRect(x: 1, y: 2, width: L - 2, height: W - 4), cornerRadius: W * 0.3)
        fillGradientPath(c, body, shade(color, 1.35), shade(color, 0.68))
        c.setStrokeColor(UIColor(white: 0, alpha: 0.55).cgColor)
        c.setLineWidth(0.7)
        body.stroke()

        if type == .muscle {
            c.setFillColor(UIColor(white: 1, alpha: 0.85).cgColor)
            c.fill(CGRect(x: 3, y: W * 0.38, width: L - 6, height: W * 0.07))
            c.fill(CGRect(x: 3, y: W * 0.55, width: L - 6, height: W * 0.07))
        }
        if type == .police {
            c.setFillColor(UIColor(white: 0.95, alpha: 1).cgColor)
            c.fill(CGRect(x: L * 0.3, y: 2.5, width: L * 0.3, height: 2.2))
            c.fill(CGRect(x: L * 0.3, y: W - 4.7, width: L * 0.3, height: 2.2))
            c.fill(CGRect(x: L * 0.3, y: W * 0.1, width: L * 0.3, height: W * 0.8))
        }
        if type == .van || type == .swat {
            let roof = UIBezierPath(roundedRect: CGRect(x: L * 0.08, y: W * 0.12, width: L * 0.66, height: W * 0.76), cornerRadius: 4)
            fillGradientPath(c, roof, shade(color, 1.45), shade(color, 0.9))
        } else {
            let roof = UIBezierPath(roundedRect: CGRect(x: L * 0.34, y: W * 0.2, width: L * 0.28, height: W * 0.6), cornerRadius: 4)
            fillGradientPath(c, roof, shade(color, 1.45), shade(color, 0.85))
            // rear window
            c.setFillColor(glass.cgColor)
            c.fill(CGRect(x: L * 0.27, y: W * 0.24, width: L * 0.07, height: W * 0.52))
        }
        // windshield
        let ws = UIBezierPath()
        ws.move(to: CGPoint(x: L * 0.64, y: W * 0.2))
        ws.addLine(to: CGPoint(x: L * 0.78, y: W * 0.3))
        ws.addLine(to: CGPoint(x: L * 0.78, y: W * 0.7))
        ws.addLine(to: CGPoint(x: L * 0.64, y: W * 0.8))
        ws.close()
        glass.setFill()
        ws.fill()
        c.setFillColor(UIColor(white: 1, alpha: 0.18).cgColor)
        c.fill(CGRect(x: L * 0.68, y: W * 0.3, width: L * 0.03, height: W * 0.4))
        // hood lines
        c.setStrokeColor(UIColor(white: 0, alpha: 0.25).cgColor)
        c.setLineWidth(0.6)
        c.move(to: CGPoint(x: L * 0.8, y: W * 0.3))
        c.addLine(to: CGPoint(x: L * 0.96, y: W * 0.3))
        c.move(to: CGPoint(x: L * 0.8, y: W * 0.7))
        c.addLine(to: CGPoint(x: L * 0.96, y: W * 0.7))
        c.strokePath()
        // lights
        c.setFillColor(UIColor(red: 1, green: 0.97, blue: 0.8, alpha: 1).cgColor)
        c.fillEllipse(in: CGRect(x: L * 0.94, y: W * 0.12, width: 3.2, height: W * 0.18))
        c.fillEllipse(in: CGRect(x: L * 0.94, y: W * 0.7, width: 3.2, height: W * 0.18))
        c.setFillColor(UIColor(red: 0.95, green: 0.08, blue: 0.08, alpha: 1).cgColor)
        c.fill(CGRect(x: 1, y: W * 0.12, width: 2, height: W * 0.18))
        c.fill(CGRect(x: 1, y: W * 0.7, width: 2, height: W * 0.18))
        if type == .sports {
            c.setFillColor(UIColor(white: 0.1, alpha: 0.9).cgColor)
            c.fill(CGRect(x: 1, y: W * 0.1, width: L * 0.07, height: W * 0.8))
        }
    }
}

func pedImage(shirt: UIColor, cap: UIColor?, skin: UIColor, gun: Bool, hair: UIColor?) -> UIImage {
    let S: CGFloat = 26
    let f = UIGraphicsImageRendererFormat.default()
    f.scale = 3
    f.opaque = false
    let r = UIGraphicsImageRenderer(size: CGSize(width: S, height: S), format: f)
    return r.image { rc in
        let c = rc.cgContext
        c.setFillColor(UIColor(white: 0, alpha: 0.28).cgColor)
        c.fillEllipse(in: CGRect(x: 4, y: 7, width: 18, height: 14))
        let sh = UIBezierPath(roundedRect: CGRect(x: 8, y: 4, width: 9, height: 18), cornerRadius: 4.5)
        fillGradientPath(c, sh, shade(shirt, 1.25), shade(shirt, 0.72))
        c.setFillColor(shade(shirt, 0.9).cgColor)
        if gun {
            c.fill(CGRect(x: 12, y: 15, width: 10, height: 3))
            c.fill(CGRect(x: 12, y: 8, width: 9, height: 3))
            c.setFillColor(UIColor(white: 0.1, alpha: 1).cgColor)
            c.fill(CGRect(x: 19, y: 11, width: 7, height: 3))
        } else {
            c.fill(CGRect(x: 8, y: 2, width: 6, height: 3))
            c.fill(CGRect(x: 8, y: 21, width: 6, height: 3))
        }
        c.setFillColor(skin.cgColor)
        c.fillEllipse(in: CGRect(x: 9, y: 8, width: 9, height: 10))
        if let h = hair {
            c.setFillColor(h.cgColor)
            c.fillEllipse(in: CGRect(x: 8.5, y: 8, width: 6, height: 10))
        }
        if let cp = cap {
            c.setFillColor(cp.cgColor)
            c.fillEllipse(in: CGRect(x: 8.5, y: 7.5, width: 10, height: 11))
            c.fill(CGRect(x: 16, y: 10, width: 4, height: 6))
        }
    }
}

func coneImage() -> UIImage {
    let f = UIGraphicsImageRendererFormat.default()
    f.scale = 1
    f.opaque = false
    let r = UIGraphicsImageRenderer(size: CGSize(width: 180, height: 120), format: f)
    return r.image { rc in
        let c = rc.cgContext
        let cs = CGColorSpaceCreateDeviceRGB()
        let cols = [UIColor(red: 1, green: 0.96, blue: 0.8, alpha: 0.6).cgColor, UIColor(red: 1, green: 0.96, blue: 0.8, alpha: 0).cgColor] as CFArray
        let locs: [CGFloat] = [0, 1]
        let p = UIBezierPath()
        p.move(to: CGPoint(x: 0, y: 60))
        p.addLine(to: CGPoint(x: 180, y: 0))
        p.addLine(to: CGPoint(x: 180, y: 120))
        p.close()
        c.saveGState()
        p.addClip()
        if let g = CGGradient(colorsSpace: cs, colors: cols, locations: locs) {
            c.drawLinearGradient(g, start: CGPoint(x: 0, y: 60), end: CGPoint(x: 180, y: 60), options: [])
        }
        c.restoreGState()
    }
}

// MARK: city data

struct Bld {
    var rect: CGRect
    var kind: Int      // 0 normal, 1 bank, 2 jewelry, 3 house, 4 crate
    var tone: CGFloat
    var h: CGFloat
}

final class CityData {
    var blds: [Bld] = []
    var blocks: [[[Int]]] = Array(repeating: Array(repeating: [Int](), count: 6), count: 6)
    var parks: [CGRect] = []
    var trees: [CGPoint] = []
    var neon: [(CGPoint, UIColor)] = []
    var bankDoor = CGPoint.zero
    var jewelDoor = CGPoint.zero
    var houseDoor = CGPoint.zero
    var bankRect = CGRect.zero
    var jewelRect = CGRect.zero
    var houseRect = CGRect.zero
    let paintPos = CGPoint(x: 800, y: 1000)
    let manholes: [CGPoint] = [CGPoint(x: 1200, y: 600), CGPoint(x: 2000, y: 1000), CGPoint(x: 600, y: 1600), CGPoint(x: 1600, y: 2000)]
    let terr: [CGPoint] = [CGPoint(x: 1800, y: 1800), CGPoint(x: 600, y: 600)]

    init() {
        generate()
    }

    func blockOf(_ v: CGFloat) -> Int {
        return max(0, min(5, Int(v / PITCH)))
    }

    func addBld(_ rect: CGRect, _ kind: Int, _ bx: Int, _ by: Int) {
        let b = Bld(rect: rect, kind: kind, tone: CGFloat.random(in: 0...1), h: CGFloat.random(in: 8...24))
        blocks[bx][by].append(blds.count)
        blds.append(b)
    }

    func generate() {
        let neonColors: [UIColor] = [
            UIColor(red: 1.0, green: 0.2, blue: 0.6, alpha: 1),
            UIColor(red: 0.1, green: 0.9, blue: 1.0, alpha: 1),
            UIColor(red: 1.0, green: 0.6, blue: 0.1, alpha: 1),
            UIColor(red: 0.3, green: 1.0, blue: 0.4, alpha: 1),
            UIColor(red: 0.7, green: 0.3, blue: 1.0, alpha: 1)
        ]
        let S: CGFloat = 284
        for bx in 0..<6 {
            for by in 0..<6 {
                let x0 = CGFloat(bx) * PITCH + 58
                let y0 = CGFloat(by) * PITCH + 58
                let key = bx * 10 + by
                if key == 22 || key == 53 || key == 4 {
                    parks.append(CGRect(x: x0, y: y0, width: S, height: S))
                    for _ in 0..<10 {
                        trees.append(CGPoint(x: x0 + CGFloat.random(in: 24...(S - 24)), y: y0 + CGFloat.random(in: 24...(S - 24))))
                    }
                    continue
                }
                if key == 44 || key == 11 {
                    for _ in 0..<8 {
                        let cx = x0 + CGFloat.random(in: 40...(S - 40))
                        let cy = y0 + CGFloat.random(in: 40...(S - 40))
                        if hypot(cx - (x0 + S / 2), cy - (y0 + S / 2)) < 70 { continue }
                        addBld(CGRect(x: cx - 14, y: cy - 14, width: 28, height: 28), 4, bx, by)
                    }
                    continue
                }
                if key == 32 {
                    let r = CGRect(x: x0 + 30, y: y0 + 90, width: 224, height: 150)
                    addBld(r, 1, bx, by)
                    bankRect = r
                    bankDoor = CGPoint(x: r.midX, y: r.minY - 14)
                    neon.append((CGPoint(x: r.midX, y: r.minY), neonColors[2]))
                    continue
                }
                if key == 14 {
                    let r = CGRect(x: x0 + 60, y: y0 + 24, width: 170, height: 110)
                    addBld(r, 2, bx, by)
                    jewelRect = r
                    jewelDoor = CGPoint(x: r.midX, y: r.minY - 14)
                    neon.append((CGPoint(x: r.midX, y: r.minY), neonColors[1]))
                    continue
                }
                if key == 41 {
                    let r = CGRect(x: x0 + 86, y: y0 + 70, width: 112, height: 92)
                    addBld(r, 3, bx, by)
                    houseRect = r
                    houseDoor = CGPoint(x: r.midX, y: r.minY - 14)
                    neon.append((CGPoint(x: r.midX, y: r.minY), neonColors[3]))
                    continue
                }
                for cx in 0..<2 {
                    for cy in 0..<2 {
                        if Int.random(in: 0..<100) < 15 { continue }
                        let inset = CGFloat.random(in: 0...12)
                        let r = CGRect(x: x0 + CGFloat(cx) * 148 + inset,
                                       y: y0 + CGFloat(cy) * 148 + inset,
                                       width: 136 - inset * 1.2,
                                       height: 136 - inset * 1.2)
                        addBld(r, 0, bx, by)
                        if Int.random(in: 0..<100) < 35 {
                            let col = neonColors[Int.random(in: 0..<neonColors.count)]
                            let side = Int.random(in: 0..<4)
                            var p = CGPoint(x: r.midX, y: r.minY)
                            if side == 1 { p = CGPoint(x: r.maxX, y: r.midY) }
                            if side == 2 { p = CGPoint(x: r.midX, y: r.maxY) }
                            if side == 3 { p = CGPoint(x: r.minX, y: r.midY) }
                            neon.append((p, col))
                        }
                    }
                }
            }
        }
    }

    func inBuilding(_ p: CGPoint) -> Bool {
        let bx = blockOf(p.x)
        let by = blockOf(p.y)
        for i in blocks[bx][by] {
            if blds[i].kind != 4 && blds[i].rect.contains(p) { return true }
        }
        return false
    }

    func hasLOS(_ a: CGPoint, _ b: CGPoint) -> Bool {
        let d = gDist(a, b)
        if d < 20 { return true }
        let steps = max(2, Int(d / 16))
        for i in 1..<steps {
            let t = CGFloat(i) / CGFloat(steps)
            let p = CGPoint(x: a.x + (b.x - a.x) * t, y: a.y + (b.y - a.y) * t)
            if inBuilding(p) { return false }
        }
        return true
    }

    // push a circle out of buildings; returns impact speed
    func collide(_ p: inout CGPoint, _ r: CGFloat, _ vel: inout CGVector, _ bounce: CGFloat) -> CGFloat {
        var impact: CGFloat = 0
        let bx = blockOf(p.x)
        let by = blockOf(p.y)
        for ix in max(0, bx - 1)...min(5, bx + 1) {
            for iy in max(0, by - 1)...min(5, by + 1) {
                for i in blocks[ix][iy] {
                    let rc = blds[i].rect
                    let cx = gClamp(p.x, rc.minX, rc.maxX)
                    let cy = gClamp(p.y, rc.minY, rc.maxY)
                    var dx = p.x - cx
                    var dy = p.y - cy
                    var d = hypot(dx, dy)
                    if d < r {
                        if d < 0.001 {
                            let l = p.x - rc.minX
                            let rr = rc.maxX - p.x
                            let b = p.y - rc.minY
                            let t = rc.maxY - p.y
                            let m = min(min(l, rr), min(b, t))
                            dx = 0
                            dy = 0
                            if m == l { dx = -1 } else if m == rr { dx = 1 } else if m == b { dy = -1 } else { dy = 1 }
                            d = 1
                            p.x += dx * (m + r)
                            p.y += dy * (m + r)
                        } else {
                            let nx = dx / d
                            let ny = dy / d
                            p.x += nx * (r - d)
                            p.y += ny * (r - d)
                            dx = nx
                            dy = ny
                        }
                        let vn = vel.dx * dx + vel.dy * dy
                        if vn < 0 {
                            vel.dx -= (1 + bounce) * vn * dx
                            vel.dy -= (1 + bounce) * vn * dy
                            impact = max(impact, -vn)
                        }
                    }
                }
            }
        }
        // world edge
        if p.x < 30 { p.x = 30; if vel.dx < 0 { vel.dx = -vel.dx * bounce } }
        if p.x > CITY - 30 { p.x = CITY - 30; if vel.dx > 0 { vel.dx = -vel.dx * bounce } }
        if p.y < 30 { p.y = 30; if vel.dy < 0 { vel.dy = -vel.dy * bounce } }
        if p.y > CITY - 30 { p.y = CITY - 30; if vel.dy > 0 { vel.dy = -vel.dy * bounce } }
        return impact
    }
}

// MARK: city painting (pre-rendered at launch)

func drawCity(_ c: CGContext, _ city: CityData, _ tile: CGRect) {
    c.setFillColor(UIColor(red: 0.12, green: 0.12, blue: 0.14, alpha: 1).cgColor)
    c.fill(tile)

    for _ in 0..<500 {
        let w = CGFloat.random(in: 20...90)
        let h = CGFloat.random(in: 20...90)
        let rc = CGRect(x: tile.minX + CGFloat.random(in: 0...tile.width), y: tile.minY + CGFloat.random(in: 0...tile.height), width: w, height: h)
        let a = CGFloat.random(in: 0.02...0.06)
        let col = Bool.random() ? UIColor(white: 1, alpha: a) : UIColor(white: 0, alpha: a * 1.5)
        c.setFillColor(col.cgColor)
        c.fill(rc)
    }

    // blocks
    for bx in 0..<6 {
        for by in 0..<6 {
            let blk = CGRect(x: CGFloat(bx) * PITCH + 42, y: CGFloat(by) * PITCH + 42, width: 316, height: 316)
            if !blk.intersects(tile) { continue }
            c.setFillColor(UIColor(red: 0.47, green: 0.47, blue: 0.49, alpha: 1).cgColor)
            c.fill(blk)
            c.setStrokeColor(UIColor(white: 0, alpha: 0.5).cgColor)
            c.setLineWidth(2)
            c.stroke(blk.insetBy(dx: -1, dy: -1))
            c.setStrokeColor(UIColor(white: 0.78, alpha: 0.6).cgColor)
            c.setLineWidth(1.5)
            c.stroke(blk.insetBy(dx: 1, dy: 1))
            let lot = blk.insetBy(dx: 16, dy: 16)
            let key = bx * 10 + by
            if key == 22 || key == 53 || key == 4 {
                c.setFillColor(UIColor(red: 0.17, green: 0.35, blue: 0.16, alpha: 1).cgColor)
                c.fill(lot)
                for _ in 0..<40 {
                    let e = CGRect(x: lot.minX + CGFloat.random(in: 0...lot.width), y: lot.minY + CGFloat.random(in: 0...lot.height), width: CGFloat.random(in: 14...50), height: CGFloat.random(in: 10...30))
                    c.setFillColor(UIColor(red: 0.3, green: 0.5, blue: 0.2, alpha: 0.18).cgColor)
                    c.fillEllipse(in: e)
                }
                c.setFillColor(UIColor(red: 0.62, green: 0.52, blue: 0.38, alpha: 0.9).cgColor)
                c.fill(CGRect(x: lot.minX, y: lot.midY - 8, width: lot.width, height: 16))
                c.fill(CGRect(x: lot.midX - 8, y: lot.minY, width: 16, height: lot.height))
            } else if key == 44 || key == 11 {
                c.setFillColor(UIColor(red: 0.34, green: 0.32, blue: 0.31, alpha: 1).cgColor)
                c.fill(lot)
                c.setStrokeColor(UIColor(red: 0.9, green: 0.7, blue: 0.1, alpha: 0.8).cgColor)
                c.setLineWidth(4)
                c.setLineDash(phase: 0, lengths: [14, 10])
                c.stroke(lot.insetBy(dx: 6, dy: 6))
                c.setLineDash(phase: 0, lengths: [])
                c.setFillColor(UIColor(red: 0.8, green: 0.1, blue: 0.1, alpha: 0.35).cgColor)
                c.fillEllipse(in: CGRect(x: lot.midX - 40, y: lot.midY - 40, width: 80, height: 80))
            } else {
                c.setFillColor(UIColor(red: 0.30, green: 0.30, blue: 0.33, alpha: 1).cgColor)
                c.fill(lot)
                if key == 32 {
                    c.setStrokeColor(UIColor(white: 1, alpha: 0.5).cgColor)
                    c.setLineWidth(1.5)
                    var x = lot.minX + 10
                    while x < lot.maxX - 10 {
                        c.move(to: CGPoint(x: x, y: lot.minY + 6))
                        c.addLine(to: CGPoint(x: x, y: lot.minY + 70))
                        x += 22
                    }
                    c.strokePath()
                }
            }
        }
    }

    // road markings
    let yellow = UIColor(red: 0.95, green: 0.78, blue: 0.1, alpha: 0.9)
    let white = UIColor(white: 0.92, alpha: 0.8)
    for k in 0...6 {
        let rc = CGFloat(k) * PITCH
        for j in 0..<6 {
            let a = CGFloat(j) * PITCH + 46
            let b = CGFloat(j + 1) * PITCH - 46
            // vertical road
            let vr = CGRect(x: rc - 40, y: a, width: 80, height: b - a)
            if vr.intersects(tile) {
                c.setStrokeColor(yellow.cgColor)
                c.setLineWidth(2)
                c.move(to: CGPoint(x: rc - 2, y: a)); c.addLine(to: CGPoint(x: rc - 2, y: b))
                c.move(to: CGPoint(x: rc + 2, y: a)); c.addLine(to: CGPoint(x: rc + 2, y: b))
                c.strokePath()
                c.setStrokeColor(white.cgColor)
                c.setLineWidth(2)
                c.setLineDash(phase: 0, lengths: [18, 16])
                c.move(to: CGPoint(x: rc - 21, y: a)); c.addLine(to: CGPoint(x: rc - 21, y: b))
                c.move(to: CGPoint(x: rc + 21, y: a)); c.addLine(to: CGPoint(x: rc + 21, y: b))
                c.strokePath()
                c.setLineDash(phase: 0, lengths: [])
            }
            // horizontal road
            let hr = CGRect(x: a, y: rc - 40, width: b - a, height: 80)
            if hr.intersects(tile) {
                c.setStrokeColor(yellow.cgColor)
                c.setLineWidth(2)
                c.move(to: CGPoint(x: a, y: rc - 2)); c.addLine(to: CGPoint(x: b, y: rc - 2))
                c.move(to: CGPoint(x: a, y: rc + 2)); c.addLine(to: CGPoint(x: b, y: rc + 2))
                c.strokePath()
                c.setStrokeColor(white.cgColor)
                c.setLineWidth(2)
                c.setLineDash(phase: 0, lengths: [18, 16])
                c.move(to: CGPoint(x: a, y: rc - 21)); c.addLine(to: CGPoint(x: b, y: rc - 21))
                c.move(to: CGPoint(x: a, y: rc + 21)); c.addLine(to: CGPoint(x: b, y: rc + 21))
                c.strokePath()
                c.setLineDash(phase: 0, lengths: [])
            }
        }
    }
    // crosswalks
    c.setFillColor(UIColor(white: 0.9, alpha: 0.7).cgColor)
    for kx in 0...6 {
        for ky in 0...6 {
            let cx = CGFloat(kx) * PITCH
            let cy = CGFloat(ky) * PITCH
            if !tile.insetBy(dx: -80, dy: -80).contains(CGPoint(x: cx, y: cy)) { continue }
            var s: CGFloat = -36
            while s <= 36 {
                c.fill(CGRect(x: cx + s - 3, y: cy + 46, width: 6, height: 12))
                c.fill(CGRect(x: cx + s - 3, y: cy - 58, width: 6, height: 12))
                c.fill(CGRect(x: cx + 46, y: cy + s - 3, width: 12, height: 6))
                c.fill(CGRect(x: cx - 58, y: cy + s - 3, width: 12, height: 6))
                s += 12
            }
        }
    }

    // paint shop pad and manholes
    let pp = city.paintPos
    if tile.contains(pp) {
        c.setFillColor(UIColor(red: 0.1, green: 0.4, blue: 0.9, alpha: 0.35).cgColor)
        c.fill(CGRect(x: pp.x - 36, y: pp.y - 48, width: 72, height: 96))
        c.setStrokeColor(UIColor(red: 1, green: 0.85, blue: 0.1, alpha: 0.9).cgColor)
        c.setLineWidth(3)
        c.setLineDash(phase: 0, lengths: [10, 8])
        c.stroke(CGRect(x: pp.x - 36, y: pp.y - 48, width: 72, height: 96))
        c.setLineDash(phase: 0, lengths: [])
        drawRoofText(c, "PAINT", pp, 14, UIColor(white: 1, alpha: 0.9))
    }
    for m in city.manholes where tile.contains(m) {
        c.setFillColor(UIColor(white: 0.2, alpha: 1).cgColor)
        c.fillEllipse(in: CGRect(x: m.x - 11, y: m.y - 11, width: 22, height: 22))
        c.setStrokeColor(UIColor(white: 0.5, alpha: 0.8).cgColor)
        c.setLineWidth(1.5)
        c.strokeEllipse(in: CGRect(x: m.x - 9, y: m.y - 9, width: 18, height: 18))
        c.move(to: CGPoint(x: m.x - 7, y: m.y)); c.addLine(to: CGPoint(x: m.x + 7, y: m.y))
        c.move(to: CGPoint(x: m.x, y: m.y - 7)); c.addLine(to: CGPoint(x: m.x, y: m.y + 7))
        c.strokePath()
    }

    // grain and wet puddles
    for _ in 0..<6000 {
        let x = tile.minX + CGFloat.random(in: 0...tile.width)
        let y = tile.minY + CGFloat.random(in: 0...tile.height)
        let a = CGFloat.random(in: 0.03...0.14)
        let col = Bool.random() ? UIColor(white: 0, alpha: a) : UIColor(white: 1, alpha: a * 0.6)
        c.setFillColor(col.cgColor)
        c.fill(CGRect(x: x, y: y, width: 1.4, height: 1.1))
    }
    for _ in 0..<70 {
        let x = tile.minX + CGFloat.random(in: 0...tile.width)
        let y = tile.minY + CGFloat.random(in: 0...tile.height)
        let nx = abs(x - (x / PITCH).rounded() * PITCH)
        let ny = abs(y - (y / PITCH).rounded() * PITCH)
        if nx > 36 && ny > 36 { continue }
        let w = CGFloat.random(in: 30...110)
        let h = CGFloat.random(in: 8...26)
        c.setFillColor(UIColor(red: 0.28, green: 0.32, blue: 0.42, alpha: 0.2).cgColor)
        c.fillEllipse(in: CGRect(x: x - w / 2, y: y - h / 2, width: w, height: h))
        c.setStrokeColor(UIColor(white: 1, alpha: 0.12).cgColor)
        c.setLineWidth(1)
        c.strokeEllipse(in: CGRect(x: x - w / 2, y: y - h / 2, width: w, height: h))
    }

    // trees in parks
    for t in city.trees where tile.contains(t) {
        c.setFillColor(UIColor(white: 0, alpha: 0.3).cgColor)
        c.fillEllipse(in: CGRect(x: t.x - 12, y: t.y - 20, width: 34, height: 30))
        c.setFillColor(UIColor(red: 0.08, green: 0.24, blue: 0.1, alpha: 1).cgColor)
        c.fillEllipse(in: CGRect(x: t.x - 18, y: t.y - 18, width: 36, height: 36))
        c.setFillColor(UIColor(red: 0.16, green: 0.42, blue: 0.16, alpha: 1).cgColor)
        c.fillEllipse(in: CGRect(x: t.x - 13, y: t.y - 9, width: 20, height: 20))
        c.setFillColor(UIColor(red: 0.3, green: 0.6, blue: 0.25, alpha: 0.7).cgColor)
        c.fillEllipse(in: CGRect(x: t.x - 6, y: t.y - 2, width: 10, height: 10))
    }

    // buildings
    for b in city.blds {
        let r = b.rect
        if !r.intersects(tile) { continue }
        if b.kind == 4 {
            c.setFillColor(UIColor(white: 0, alpha: 0.3).cgColor)
            c.fill(r.offsetBy(dx: 4, dy: -4))
            c.setFillColor(UIColor(red: 0.5, green: 0.36, blue: 0.2, alpha: 1).cgColor)
            c.fill(r)
            c.setStrokeColor(UIColor(red: 0.28, green: 0.18, blue: 0.08, alpha: 1).cgColor)
            c.setLineWidth(2)
            c.stroke(r)
            c.move(to: CGPoint(x: r.minX, y: r.minY)); c.addLine(to: CGPoint(x: r.maxX, y: r.maxY))
            c.move(to: CGPoint(x: r.minX, y: r.maxY)); c.addLine(to: CGPoint(x: r.maxX, y: r.minY))
            c.strokePath()
            continue
        }
        // soft shadow
        for i in 0..<5 {
            let o = b.h * (0.5 + CGFloat(i) * 0.12)
            c.setFillColor(UIColor(white: 0, alpha: 0.13).cgColor)
            c.fill(r.offsetBy(dx: o, dy: -o).insetBy(dx: CGFloat(-i) * 1.5, dy: CGFloat(-i) * 1.5))
        }
        var top = UIColor(red: 0.42 + b.tone * 0.12, green: 0.44 + b.tone * 0.08, blue: 0.5 + b.tone * 0.1, alpha: 1)
        if b.kind == 1 { top = UIColor(red: 0.72, green: 0.66, blue: 0.5, alpha: 1) }
        if b.kind == 2 { top = UIColor(red: 0.5, green: 0.65, blue: 0.78, alpha: 1) }
        if b.kind == 3 { top = UIColor(red: 0.62, green: 0.34, blue: 0.28, alpha: 1) }
        let roof = UIBezierPath(rect: r)
        fillGradientPath(c, roof, shade(top, 1.15), shade(top, 0.8))
        c.setStrokeColor(UIColor(white: 1, alpha: 0.35).cgColor)
        c.setLineWidth(3)
        c.stroke(r.insetBy(dx: 1.5, dy: 1.5))
        c.setStrokeColor(UIColor(white: 0, alpha: 0.5).cgColor)
        c.setLineWidth(1)
        c.stroke(r)
        c.setStrokeColor(UIColor(white: 0, alpha: 0.2).cgColor)
        c.stroke(r.insetBy(dx: 7, dy: 7))

        if b.kind == 0 {
            let n = Int(r.width / 45)
            for i in 0..<max(1, n) {
                let ax = r.minX + 14 + CGFloat(i) * 42 + CGFloat.random(in: 0...10)
                let ay = r.minY + 14 + CGFloat.random(in: 0...(max(1, r.height - 50)))
                let ac = CGRect(x: ax, y: ay, width: 22, height: 16)
                fillGradientPath(c, UIBezierPath(rect: ac), UIColor(white: 0.78, alpha: 1), UIColor(white: 0.5, alpha: 1))
                c.setStrokeColor(UIColor(white: 0, alpha: 0.5).cgColor)
                c.setLineWidth(0.8)
                c.stroke(ac)
                c.setFillColor(UIColor(white: 0.2, alpha: 1).cgColor)
                c.fillEllipse(in: CGRect(x: ac.midX - 5, y: ac.midY - 5, width: 10, height: 10))
            }
            if r.width > 100 {
                let sk = CGRect(x: r.maxX - 44, y: r.maxY - 36, width: 30, height: 22)
                fillGradientPath(c, UIBezierPath(rect: sk), UIColor(red: 0.5, green: 0.75, blue: 0.9, alpha: 0.9), UIColor(red: 0.2, green: 0.35, blue: 0.5, alpha: 0.9))
                c.setStrokeColor(UIColor(white: 1, alpha: 0.5).cgColor)
                c.move(to: CGPoint(x: sk.minX, y: sk.minY)); c.addLine(to: CGPoint(x: sk.maxX, y: sk.maxY))
                c.strokePath()
            }
        }
        if b.kind == 1 {
            c.setFillColor(UIColor(red: 0.85, green: 0.7, blue: 0.2, alpha: 1).cgColor)
            c.fill(CGRect(x: r.minX + 14, y: r.minY + 14, width: r.width - 28, height: 6))
            c.fill(CGRect(x: r.minX + 14, y: r.maxY - 20, width: r.width - 28, height: 6))
            drawRoofText(c, "BANK", CGPoint(x: r.midX, y: r.midY), 40, UIColor(red: 0.45, green: 0.35, blue: 0.1, alpha: 1))
        }
        if b.kind == 2 {
            drawRoofText(c, "GEMS", CGPoint(x: r.midX, y: r.midY), 36, UIColor(red: 0.15, green: 0.3, blue: 0.5, alpha: 1))
        }
        if b.kind == 3 {
            c.setStrokeColor(UIColor(red: 0.35, green: 0.15, blue: 0.1, alpha: 0.9).cgColor)
            c.setLineWidth(2)
            var y = r.minY + 10
            while y < r.maxY - 6 {
                c.move(to: CGPoint(x: r.minX + 4, y: y))
                c.addLine(to: CGPoint(x: r.maxX - 4, y: y))
                y += 10
            }
            c.strokePath()
            drawRoofText(c, "SAFE", CGPoint(x: r.midX, y: r.midY), 22, UIColor(white: 1, alpha: 0.9))
        }
    }

    // night grade
    c.setFillColor(UIColor(red: 0.03, green: 0.05, blue: 0.14, alpha: 0.34).cgColor)
    c.fill(tile)

    // lamps and neon glows (screen blend)
    c.setBlendMode(.screen)
    for kx in 0...6 {
        for ky in 0...6 {
            let cx = CGFloat(kx) * PITCH
            let cy = CGFloat(ky) * PITCH
            let corners: [CGPoint] = [CGPoint(x: cx + 52, y: cy + 52), CGPoint(x: cx - 52, y: cy + 52), CGPoint(x: cx + 52, y: cy - 52), CGPoint(x: cx - 52, y: cy - 52)]
            for p in corners where tile.insetBy(dx: -90, dy: -90).contains(p) {
                drawGlow(c, p, 95, UIColor(red: 1.0, green: 0.8, blue: 0.45, alpha: 1), 0.34)
            }
        }
    }
    for (p, col) in city.neon where tile.insetBy(dx: -100, dy: -100).contains(p) {
        drawGlow(c, p, 100, col, 0.38)
        drawGlow(c, CGPoint(x: p.x, y: p.y), 26, UIColor.white, 0.35)
    }
    c.setBlendMode(.normal)

    // neon sign bars (drawn lit)
    for (p, col) in city.neon where tile.contains(p) {
        c.setFillColor(col.cgColor)
        c.fill(CGRect(x: p.x - 14, y: p.y - 2, width: 28, height: 4))
    }
}

func renderCityTile(_ city: CityData, _ tx: Int, _ ty: Int) -> UIImage {
    let tile = CGRect(x: CGFloat(tx) * 1200, y: CGFloat(ty) * 1200, width: 1200, height: 1200)
    let f = UIGraphicsImageRendererFormat.default()
    f.scale = 1.5
    f.opaque = true
    let r = UIGraphicsImageRenderer(size: tile.size, format: f)
    return r.image { rc in
        let c = rc.cgContext
        c.translateBy(x: 0, y: tile.height)
        c.scaleBy(x: 1, y: -1)
        c.translateBy(x: -tile.minX, y: -tile.minY)
        drawCity(c, city, tile)
    }
}

// MARK: entities

enum PedKind { case civilian, cop, swat, gang, crew }

final class Ped {
    let node = SKNode()
    var sprite: SKSpriteNode
    var pos: CGPoint
    var angle: CGFloat = 0
    var hp: CGFloat = 60
    var kind: PedKind
    var vel = CGVector.zero
    var ringDir = 0
    var ringOff: CGFloat = 0
    var fear: CGFloat = 0
    var fearFrom = CGPoint.zero
    var shootCD: CGFloat = 0
    var losTimer: CGFloat = 0
    var sees = false
    var dead = false
    var deadT: CGFloat = 0
    var walk: CGFloat = 0
    var home = CGPoint.zero
    var terr = -1
    var chasing = false

    init(kind: PedKind, pos: CGPoint, tex: SKTexture) {
        self.kind = kind
        self.pos = pos
        self.sprite = SKSpriteNode(texture: tex, size: CGSize(width: 26, height: 26))
        node.addChild(sprite)
        node.position = pos
        node.zPosition = 3
    }
}

enum CarAI { case traffic, chase, player, parked, tank, still }

final class Car {
    let node = SKNode()
    var body: SKSpriteNode
    var type: CarType
    var spec: CarSpec
    var pos: CGPoint
    var angle: CGFloat
    var vel = CGVector.zero
    var hp: CGFloat
    var ai: CarAI = .parked
    var hasDriver = false
    var dir = 0
    var lastCross = -1
    var colorIdx = 0
    var stuckT: CGFloat = 0
    var reverseT: CGFloat = 0
    var skidT: CGFloat = 0
    var smokeT: CGFloat = 0
    var losTimer: CGFloat = 0
    var sees = false
    var shootCD: CGFloat = 2
    var turret: SKSpriteNode?
    var lightBar: SKNode?
    var light: SKSpriteNode?
    var lastHitByPlayer = false
    var lifeT: CGFloat = 0

    init(type: CarType, pos: CGPoint, angle: CGFloat, tex: SKTexture) {
        self.type = type
        self.spec = carSpec(type)
        self.pos = pos
        self.angle = angle
        self.hp = carSpec(type).hp
        self.body = SKSpriteNode(texture: tex, size: CGSize(width: carSpec(type).len, height: carSpec(type).wid))
        node.addChild(body)
        node.position = pos
        node.zRotation = angle
        node.zPosition = 2
    }

    var speed: CGFloat {
        return hypot(vel.dx, vel.dy)
    }
}

final class Bullet {
    let node: SKSpriteNode
    var pos: CGPoint
    var vel: CGVector
    var dmg: CGFloat
    var life: CGFloat
    var friendly: Bool
    var pierce: Bool
    var bounces = 0
    var kind: Int      // 0 bullet, 1 flame, 2 friendly rocket, 3 enemy missile, 4 pipe bomb, 5 shell
    var wall: CGFloat = 0
    var homing = false
    var dead = false

    init(node: SKSpriteNode, pos: CGPoint, vel: CGVector, dmg: CGFloat, life: CGFloat, friendly: Bool, pierce: Bool, kind: Int) {
        self.node = node
        self.pos = pos
        self.vel = vel
        self.dmg = dmg
        self.life = life
        self.friendly = friendly
        self.pierce = pierce
        self.kind = kind
    }
}

final class Flyer {
    let node = SKNode()
    var pos: CGPoint
    var kind: Int      // 0 chopper, 1 drone
    var hp: CGFloat
    var orbit: CGFloat = 0
    var cd: CGFloat = 2
    var aimT: CGFloat = 0
    var laser: SKShapeNode?
    var rotor: SKNode?

    init(kind: Int, pos: CGPoint) {
        self.kind = kind
        self.pos = pos
        self.hp = kind == 0 ? 320 : 130
        node.position = pos
        node.zPosition = 9
    }
}

final class Cash {
    let node: SKSpriteNode
    var pos: CGPoint
