    init(node: SKSpriteNode, pos: CGPoint, value: Int) {
        self.node = node
        self.pos = pos
        self.value = value
    }
}

// MARK: SwiftUI wrapper (rotated so it plays in landscape)

struct CrimeView: View {
    var onExit: () -> Void
    @State private var scene: CrimeScene = CrimeScene.make()
    @State private var flipped = false

    var body: some View {
        let sw = UIScreen.main.bounds.width
        let sh = UIScreen.main.bounds.height
        ZStack {
            Color.black.ignoresSafeArea()
            ZStack(alignment: .topLeading) {
                SpriteView(scene: scene)
                HStack(spacing: 10) {
                    Button(action: onExit) {
                        Text("✕")
                            .font(.system(size: 18, weight: .bold))
                            .foregroundColor(.white)
                            .frame(width: 36, height: 36)
                            .background(Color.black.opacity(0.5))
                            .clipShape(Circle())
                    }
                    Button(action: { flipped.toggle() }) {
                        Text("⟲")
                            .font(.system(size: 18, weight: .bold))
                            .foregroundColor(.white)
                            .frame(width: 36, height: 36)
                            .background(Color.black.opacity(0.5))
                            .clipShape(Circle())
                    }
                }
                .padding(.leading, 56)
                .padding(.top, 6)
            }
            .frame(width: sh, height: sw)
            .rotationEffect(.degrees(flipped ? -90 : 90))
            .frame(width: sw, height: sh)
        }
        .ignoresSafeArea()
    }
}

