        return s
    }

    // world
    let world = SKNode()
    let city = CityData()
    var ready = false
    var didSetup = false
    var loadLabel: SKLabelNode!

    // art
    let palette: [UIColor] = [
        UIColor(red: 0.85, green: 0.12, blue: 0.12, alpha: 1),
        UIColor(red: 0.12, green: 0.30, blue: 0.80, alpha: 1),
        UIColor(red: 0.95, green: 0.78, blue: 0.10, alpha: 1),
        UIColor(white: 0.92, alpha: 1),
        UIColor(white: 0.62, alpha: 1),
        UIColor(red: 0.10, green: 0.55, blue: 0.25, alpha: 1),
        UIColor(red: 0.95, green: 0.50, blue: 0.10, alpha: 1),
        UIColor(white: 0.12, alpha: 1)
    ]
    var carTex: [String: SKTexture] = [:]
    var pedTex: [String: SKTexture] = [:]
