    var peds: [Ped] = []
    var bullets: [Bullet] = []
    var flyers: [Flyer] = []
    var cashes: [Cash] = []
    var skids: [SKSpriteNode] = []

    // player
    let playerNode = SKNode()
    var playerPos = CGPoint(x: 1250, y: 1250)
    var pAngle: CGFloat = 0
    var pHP: CGFloat = 100
    var pVel = CGVector.zero
    var inCar: Car?
    var walkPhase: CGFloat = 0
    var money = 500
    var heat: CGFloat = 0
    var stars = 0
    var weaponIdx = 0
    var fireCD: CGFloat = 0
    var bombCD: CGFloat = 0
    var shotCount = 0
    var invuln: CGFloat = 0
    var hideT: CGFloat = 0
    var hideFrom = CGPoint.zero
    var wastedT: CGFloat = 0
    var crewCount = 0
    var houseOwned = false
    var terrMask = 0
    var incomeT: CGFloat = 0
    var noSeeT: CGFloat = 0
    var shakeT: CGFloat = 0
    var crimeCD: CGFloat = 0
    var heistKind = 0
    var heistT: CGFloat = 0
