    var moneyLabel: SKLabelNode!
    var starsLabel: SKLabelNode!
    var weaponLabel: SKLabelNode!
    var promptLabel: SKLabelNode!
    var toastLabel: SKLabelNode!
    var btnAct: SKShapeNode!
    var btnActLabel: SKLabelNode!
    var btnBomb: SKShapeNode!
    var btnWeapon: SKShapeNode!
    var btnBrake: SKShapeNode!
    var stickBaseL: SKShapeNode!
    var stickKnobL: SKShapeNode!
    var stickBaseR: SKShapeNode!
    var stickKnobR: SKShapeNode!
    var heistBar: SKSpriteNode!
    var heistBack: SKSpriteNode!
