    // MARK: setup

    override func didMove(to view: SKView) {
        view.isMultipleTouchEnabled = true
        if !didSetup {
            didSetup = true
            setup()
        }
    }

    func setup() {
        backgroundColor = UIColor.black
        addChild(world)
        addChild(hud)
        hud.zPosition = 200
        loadLabel = westernLabel("Loading city...", 26, UIColor.white)
        loadLabel.position = CGPoint(x: size.width / 2, y: size.height / 2)
        loadLabel.zPosition = 300
        addChild(loadLabel)
        makeTextures()
        buildHUD()
        loadSave()
        let cityRef = city
        DispatchQueue.global(qos: .userInitiated).async {
            var imgs: [UIImage] = []
            for ty in 0..<2 {
                for tx in 0..<2 {
                    imgs.append(renderCityTile(cityRef, tx, ty))
                }
            }
            DispatchQueue.main.async {
                self.finishLoading(imgs)
            }
        }
    }

    func makeTextures() {
        let types: [CarType] = [.sports, .muscle, .truck, .van, .bike]
        for t in types {
            for i in 0..<palette.count {
                carTex["\(t.rawValue)-\(i)"] = SKTexture(image: carImage(t, palette[i]))
            }
        }
        carTex["police"] = SKTexture(image: carImage(.police, UIColor(white: 0.08, alpha: 1)))
        carTex["swat"] = SKTexture(image: carImage(.swat, UIColor(white: 0.1, alpha: 1)))
        carTex["tank"] = SKTexture(image: carImage(.tank, UIColor(white: 0.3, alpha: 1)))

        let skin = UIColor(red: 0.85, green: 0.65, blue: 0.5, alpha: 1)
        let shirts: [UIColor] = [
            UIColor(red: 0.8, green: 0.2, blue: 0.2, alpha: 1), UIColor(red: 0.2, green: 0.4, blue: 0.8, alpha: 1),
            UIColor(red: 0.9, green: 0.8, blue: 0.2, alpha: 1), UIColor(red: 0.3, green: 0.7, blue: 0.4, alpha: 1),
            UIColor(red: 0.7, green: 0.3, blue: 0.7, alpha: 1), UIColor(white: 0.85, alpha: 1)
        ]
        for i in 0..<shirts.count {
            pedTex["civ\(i)"] = SKTexture(image: pedImage(shirt: shirts[i], cap: nil, skin: skin, gun: false, hair: UIColor(white: 0.15, alpha: 1)))
        }
        pedTex["cop"] = SKTexture(image: pedImage(shirt: UIColor(red: 0.1, green: 0.2, blue: 0.5, alpha: 1), cap: UIColor(red: 0.05, green: 0.1, blue: 0.3, alpha: 1), skin: skin, gun: true, hair: nil))
        pedTex["swat"] = SKTexture(image: pedImage(shirt: UIColor(white: 0.12, alpha: 1), cap: UIColor(white: 0.2, alpha: 1), skin: skin, gun: true, hair: nil))
        pedTex["gang"] = SKTexture(image: pedImage(shirt: UIColor(red: 0.55, green: 0.1, blue: 0.1, alpha: 1), cap: UIColor(red: 0.8, green: 0.1, blue: 0.1, alpha: 1), skin: skin, gun: true, hair: nil))
        pedTex["crew"] = SKTexture(image: pedImage(shirt: UIColor(red: 0.1, green: 0.5, blue: 0.3, alpha: 1), cap: UIColor(red: 0.1, green: 0.3, blue: 0.2, alpha: 1), skin: skin, gun: true, hair: nil))
        pedTex["player"] = SKTexture(image: pedImage(shirt: UIColor(red: 0.95, green: 0.5, blue: 0.1, alpha: 1), cap: nil, skin: skin, gun: true, hair: nil))

        let wc: [UIColor] = [UIColor.white, UIColor(white: 1, alpha: 0)]
        let wl: [CGFloat] = [0, 1]
        glowTex = SKTexture(image: radialImage(CGSize(width: 64, height: 64), 32, wc, wl))
        let sc: [UIColor] = [UIColor(white: 0.35, alpha: 0.8), UIColor(white: 0.35, alpha: 0)]
        smokeTex = SKTexture(image: radialImage(CGSize(width: 64, height: 64), 32, sc, wl))
        coneTex = SKTexture(image: coneImage())
        headTex = SKTexture(image: headImage)
    }

    func finishLoading(_ imgs: [UIImage]) {
        for i in 0..<imgs.count {
            let tx = i % 2
            let ty = i / 2
            let s = SKSpriteNode(texture: SKTexture(image: imgs[i]), size: CGSize(width: 1200, height: 1200))
            s.anchorPoint = CGPoint.zero
            s.position = CGPoint(x: CGFloat(tx) * 1200, y: CGFloat(ty) * 1200)
            s.zPosition = -10
            world.addChild(s)
        }
        addMarkers()
        buildPlayer()
        populate()
        loadLabel.removeFromParent()
        ready = true
        toast("Welcome to the city. Steal a car with ACT!")
    }

    func addMarker(_ p: CGPoint, _ text: String, _ color: UIColor) {
        let ring = SKShapeNode(circleOfRadius: 16)
        ring.strokeColor = color
        ring.lineWidth = 3
        ring.fillColor = color.withAlphaComponent(0.15)
        ring.position = p
        ring.zPosition = 0.5
        world.addChild(ring)
        ring.run(SKAction.repeatForever(SKAction.sequence([SKAction.scale(to: 1.25, duration: 0.7), SKAction.scale(to: 0.9, duration: 0.7)])))
        let l = westernLabel(text, 11, color)
        l.position = CGPoint(x: p.x, y: p.y - 28)
        l.zPosition = 0.6
        world.addChild(l)
    }

    func addMarkers() {
        addMarker(city.bankDoor, "BANK", UIColor.yellow)
        addMarker(city.jewelDoor, "GEMS", UIColor.cyan)
        addMarker(city.houseDoor, "SAFEHOUSE", UIColor.green)
        for m in city.manholes {
            let r = SKShapeNode(circleOfRadius: 14)
            r.strokeColor = UIColor(white: 1, alpha: 0.4)
            r.lineWidth = 2
            r.fillColor = UIColor.clear
            r.position = m
            r.zPosition = 0.5
            world.addChild(r)
        }
    }

    func buildPlayer() {
        playerNode.zPosition = 4
        let body = SKSpriteNode(texture: pedTex["player"], size: CGSize(width: 26, height: 26))
        playerNode.addChild(body)
        let head = SKSpriteNode(texture: headTex, size: CGSize(width: 11, height: 15))
        head.zRotation = -CGFloat.pi / 2
        head.position = CGPoint(x: 0.5, y: 0)
        head.zPosition = 1
        playerNode.addChild(head)
        playerNode.position = playerPos
        world.addChild(playerNode)
        pHP = 100
    }

    func populate() {
        for _ in 0..<18 { spawnTrafficCar(far: false) }
        for _ in 0..<3 { spawnPatrolCar() }
        for _ in 0..<30 { spawnCivilian(far: false) }
        for _ in 0..<3 { spawnPatrolCop() }
        for ti in 0..<city.terr.count where (terrMask & (1 << ti)) == 0 {
            for _ in 0..<5 {
                let a = CGFloat.random(in: 0..<(2 * CGFloat.pi))
                let d = CGFloat.random(in: 20...70)
                let p = CGPoint(x: city.terr[ti].x + cos(a) * d, y: city.terr[ti].y + sin(a) * d)
                let g = makePed(.gang, at: p)
                g.terr = ti
                g.home = city.terr[ti]
                g.hp = 80
            }
        }
    }

