    // MARK: input

    func inButton(_ b: SKShapeNode, _ p: CGPoint) -> Bool {
        return hypot(p.x - b.position.x, p.y - b.position.y) < 44
    }

    override func touchesBegan(_ touches: Set<UITouch>, with event: UIEvent?) {
        if !ready || wastedT > 0 { return }
        for t in touches {
            let p = t.location(in: self)
            if inButton(btnAct, p) { doAction(); continue }
            if inButton(btnBomb, p) { throwBomb(); continue }
            if inButton(btnWeapon, p) {
                weaponIdx = (weaponIdx + 1) % WEAPONS.count
                weaponLabel.text = WEAPONS[weaponIdx].name
                continue
            }
            if inButton(btnBrake, p) {
                brakeTouch = t
                braking = true
                continue
            }
            if p.x < size.width * 0.5 {
                if leftTouch == nil {
                    leftTouch = t
                    leftStart = p
                    stickBaseL.position = p
                    stickKnobL.position = p
                    stickBaseL.alpha = 1
                    stickKnobL.alpha = 1
                }
            } else {
                if rightTouch == nil {
                    rightTouch = t
                    rightStart = p
                    stickBaseR.position = p
                    stickKnobR.position = p
                    stickBaseR.alpha = 1
                    stickKnobR.alpha = 1
                }
            }
        }
    }

    override func touchesMoved(_ touches: Set<UITouch>, with event: UIEvent?) {
        for t in touches {
            let p = t.location(in: self)
            if t === leftTouch {
                var dx = p.x - leftStart.x
                var dy = p.y - leftStart.y
                let d = hypot(dx, dy)
                if d > 46 { dx = dx / d * 46; dy = dy / d * 46 }
                stickKnobL.position = CGPoint(x: leftStart.x + dx, y: leftStart.y + dy)
                moveVec = CGVector(dx: dx / 46, dy: dy / 46)
            } else if t === rightTouch {
                var dx = p.x - rightStart.x
                var dy = p.y - rightStart.y
                let d = hypot(dx, dy)
                if d > 46 { dx = dx / d * 46; dy = dy / d * 46 }
                stickKnobR.position = CGPoint(x: rightStart.x + dx, y: rightStart.y + dy)
                aimVec = CGVector(dx: dx / 46, dy: dy / 46)
            }
        }
    }

    func endTouches(_ touches: Set<UITouch>) {
        for t in touches {
            if t === leftTouch {
                leftTouch = nil
                moveVec = CGVector.zero
                stickBaseL.position = CGPoint(x: 130, y: 90)
                stickKnobL.position = stickBaseL.position
                stickBaseL.alpha = 0.5
                stickKnobL.alpha = 0.5
            } else if t === rightTouch {
                rightTouch = nil
                aimVec = CGVector.zero
                stickBaseR.position = CGPoint(x: size.width - 330, y: 90)
                stickKnobR.position = stickBaseR.position
                stickBaseR.alpha = 0.5
                stickKnobR.alpha = 0.5
            } else if t === brakeTouch {
                brakeTouch = nil
                braking = false
            }
        }
    }

    override func touchesEnded(_ touches: Set<UITouch>, with event: UIEvent?) {
        endTouches(touches)
    }

    override func touchesCancelled(_ touches: Set<UITouch>, with event: UIEvent?) {
        endTouches(touches)
    }

    // MARK: spawning

    func texFor(_ type: CarType, _ idx: Int) -> SKTexture {
        switch type {
        case .police: return carTex["police"]!
        case .swat: return carTex["swat"]!
        case .tank: return carTex["tank"]!
        default: return carTex["\(type.rawValue)-\(idx)"]!
        }
    }

    @discardableResult
    func makeCar(_ type: CarType, at p: CGPoint, angle: CGFloat, ai: CarAI) -> Car {
        let idx = Int.random(in: 0..<palette.count)
        let c = Car(type: type, pos: p, angle: angle, tex: texFor(type, idx))
        c.colorIdx = idx
        c.ai = ai
        let sh = SKSpriteNode(color: UIColor(white: 0, alpha: 0.28), size: CGSize(width: c.spec.len * 0.95, height: c.spec.wid * 0.95))
        sh.position = CGPoint(x: 4, y: -4)
        sh.zPosition = -1
        c.node.addChild(sh)
        let li = SKSpriteNode(texture: coneTex, size: CGSize(width: 150, height: 100))
        li.anchorPoint = CGPoint(x: 0, y: 0.5)
        li.position = CGPoint(x: c.spec.len * 0.45, y: 0)
        li.blendMode = .add
        li.alpha = 0.5
        li.zPosition = -0.5
        c.node.addChild(li)
        c.light = li
        if type == .police || type == .swat {
            let bar = SKNode()
            bar.position = CGPoint(x: c.spec.len * 0.05, y: 0)
            bar.zPosition = 2
            let red = SKSpriteNode(texture: glowTex, color: UIColor.red, size: CGSize(width: 34, height: 34))
            red.colorBlendFactor = 1
            red.blendMode = .add
            red.position = CGPoint(x: 0, y: 7)
            red.name = "red"
            let blue = SKSpriteNode(texture: glowTex, color: UIColor(red: 0.2, green: 0.4, blue: 1, alpha: 1), size: CGSize(width: 34, height: 34))
            blue.colorBlendFactor = 1
            blue.blendMode = .add
            blue.position = CGPoint(x: 0, y: -7)
            blue.name = "blue"
            bar.addChild(red)
            bar.addChild(blue)
            c.node.addChild(bar)
            c.lightBar = bar
        }
        if type == .tank {
            let tur = SKSpriteNode(color: UIColor(red: 0.3, green: 0.34, blue: 0.2, alpha: 1), size: CGSize(width: 40, height: 28))
            tur.zPosition = 1
            let barrel = SKSpriteNode(color: UIColor(white: 0.15, alpha: 1), size: CGSize(width: 44, height: 6))
            barrel.anchorPoint = CGPoint(x: 0, y: 0.5)
            barrel.position = CGPoint(x: 10, y: 0)
            tur.addChild(barrel)
            c.node.addChild(tur)
            c.turret = tur
        }
        world.addChild(c.node)
        cars.append(c)
        return c
    }

    func randomRoadSpot(minD: CGFloat) -> (CGPoint, Int)? {
        for _ in 0..<25 {
            let k = CGFloat(Int.random(in: 1...5)) * PITCH
            let t = CGFloat.random(in: 80...(CITY - 80))
            var p = CGPoint.zero
            var dir = 0
            if Bool.random() {
                dir = Bool.random() ? 1 : 3
                p = CGPoint(x: k + (dir == 1 ? 21 : -21), y: t)
            } else {
                dir = Bool.random() ? 0 : 2
                p = CGPoint(x: t, y: k + (dir == 0 ? -21 : 21))
            }
            if gDist(p, playerPos) < minD { continue }
            var clear = true
            for c in cars where gDist(c.pos, p) < 70 { clear = false }
            if clear { return (p, dir) }
        }
        return nil
    }

    func spawnTrafficCar(far: Bool) {
        guard let (p, dir) = randomRoadSpot(minD: far ? 650 : 120) else { return }
        let roll = Int.random(in: 0..<100)
        var type = CarType.muscle
        if roll < 22 { type = .sports } else if roll < 44 { type = .muscle } else if roll < 64 { type = .van } else if roll < 78 { type = .truck } else if roll < 92 { type = .bike }
        let c = makeCar(type, at: p, angle: CGFloat(dir) * CGFloat.pi / 2, ai: .traffic)
        c.dir = dir
        c.hasDriver = true
        c.vel = gVec(c.angle, 120)
    }

    func spawnPatrolCar() {
        guard let (p, dir) = randomRoadSpot(minD: 300) else { return }
        let c = makeCar(.police, at: p, angle: CGFloat(dir) * CGFloat.pi / 2, ai: .traffic)
        c.dir = dir
        c.hasDriver = true
        c.vel = gVec(c.angle, 120)
    }

    func ringRect(_ bx: Int, _ by: Int) -> CGRect {
        return CGRect(x: CGFloat(bx) * PITCH + 50, y: CGFloat(by) * PITCH + 50, width: 300, height: 300)
    }

    func randomRingPoint(minD: CGFloat) -> (CGPoint, Int) {
        var out = (CGPoint(x: 1250, y: 1250), 0)
        for _ in 0..<15 {
            let bx = Int.random(in: 0..<6)
            let by = Int.random(in: 0..<6)
            let r = ringRect(bx, by)
            let s = CGFloat.random(in: 0...300)
            let e = Int.random(in: 0..<4)
            var p = CGPoint(x: r.minX + s, y: r.minY)
            if e == 1 { p = CGPoint(x: r.maxX, y: r.minY + s) }
            if e == 2 { p = CGPoint(x: r.maxX - s, y: r.maxY) }
            if e == 3 { p = CGPoint(x: r.minX, y: r.maxY - s) }
            out = (p, e)
            if gDist(p, playerPos) >= minD { break }
        }
        return out
    }

    @discardableResult
    func makePed(_ kind: PedKind, at p: CGPoint) -> Ped {
        var key = "civ\(Int.random(in: 0..<6))"
        if kind == .cop { key = "cop" }
        if kind == .swat { key = "swat" }
        if kind == .gang { key = "gang" }
        if kind == .crew { key = "crew" }
        let ped = Ped(kind: kind, pos: p, tex: pedTex[key]!)
        ped.hp = kind == .swat ? 150 : (kind == .cop ? 90 : 60)
        ped.ringOff = CGFloat.random(in: -5...5)
        world.addChild(ped.node)
        peds.append(ped)
        return ped
    }

    func spawnCivilian(far: Bool) {
        let (p, dir) = randomRingPoint(minD: far ? 500 : 60)
        let ped = makePed(.civilian, at: p)
        ped.ringDir = dir
    }

    func spawnPatrolCop() {
        let (p, dir) = randomRingPoint(minD: 200)
        let ped = makePed(.cop, at: p)
        ped.ringDir = dir
    }

    // MARK: main loop

    override func update(_ currentTime: TimeInterval) {
        if !ready { return }
        if lastTime == 0 {
            lastTime = currentTime
            return
        }
        var dt = CGFloat(currentTime - lastTime)
        lastTime = currentTime
        if dt > 0.05 { dt = 0.05 }
        if dt <= 0 { return }

        if wastedT > 0 {
            wastedT -= dt
            wastedOverlay.alpha = min(1, wastedOverlay.alpha + dt * 2)
            wastedLabel.alpha = wastedOverlay.alpha
            if wastedT <= 0 { respawn() }
        }

        fireCD -= dt
        bombCD -= dt
        invuln -= dt
        crimeCD -= dt
        lightT += dt
        for i in 0..<2 { heistCool[i] = max(0, heistCool[i] - dt) }

        updateAimState()
        if wastedT <= 0 {
            updatePlayer(dt)
        }
        updateCars(dt)
        collideCars()
        updatePeds(dt)
        updateBullets(dt)
        updateFlyers(dt)
        updateCash(dt)
        updatePolice(dt)
        updateHeist(dt)
        updateEconomy(dt)
        updateContext()
        updateHUD()
        updateCamera(dt)
    }

    func updateAimState() {
        let m = hypot(aimVec.dx, aimVec.dy)
        if m > 0.25 && wastedT <= 0 && hideT <= 0 {
            aiming = true
            aimAngle = atan2(aimVec.dy, aimVec.dx)
        } else {
            aiming = false
        }
    }

    // MARK: player

    func updatePlayer(_ dt: CGFloat) {
        if hideT > 0 {
            hideT -= dt
            hideOverlay.alpha = min(0.95, hideOverlay.alpha + dt * 3)
            if hideT <= 0 { emergeFromSewer() }
            return
        } else if hideOverlay.alpha > 0 {
            hideOverlay.alpha = max(0, hideOverlay.alpha - dt * 2)
        }

        if let car = inCar {
            playerPos = car.pos
            playerNode.position = car.pos
            if aiming {
                let o = CGPoint(x: car.pos.x + cos(aimAngle) * 20, y: car.pos.y + sin(aimAngle) * 20)
                fireWeapon(from: o, angle: aimAngle)
            }
            return
        }

        let mag = hypot(moveVec.dx, moveVec.dy)
        if mag > 0.12 {
            pVel = CGVector(dx: moveVec.dx * 150, dy: moveVec.dy * 150)
            walkPhase += dt * 12
        } else {
            pVel = CGVector.zero
        }
        playerPos.x += pVel.dx * dt
        playerPos.y += pVel.dy * dt
        _ = city.collide(&playerPos, 8, &pVel, 0)
        // nudged by moving cars
        for c in cars {
            let d = gDist(c.pos, playerPos)
            if d < c.spec.radius + 8 {
                if c.speed > 90 && c.ai != .parked {
                    damagePlayer(c.speed * 0.12)
                }
                let a = gAngle(c.pos, playerPos)
                playerPos.x = c.pos.x + cos(a) * (c.spec.radius + 8)
                playerPos.y = c.pos.y + sin(a) * (c.spec.radius + 8)
            }
        }
        if aiming {
            pAngle = aimAngle
            fireWeapon(from: CGPoint(x: playerPos.x + cos(pAngle) * 16, y: playerPos.y + sin(pAngle) * 16), angle: pAngle)
        } else if mag > 0.12 {
            let want = atan2(moveVec.dy, moveVec.dx)
            pAngle += gAngDiff(want, pAngle) * min(1, dt * 12)
        }
        playerNode.position = playerPos
        playerNode.zRotation = pAngle
        playerNode.setScale(1 + 0.04 * sin(walkPhase))
    }

    func damagePlayer(_ dmg: CGFloat) {
        if invuln > 0 || wastedT > 0 || hideT > 0 { return }
        pHP -= dmg
        hurtOverlay.alpha = 0.35
        hurtOverlay.run(SKAction.fadeOut(withDuration: 0.4))
        if pHP <= 0 { die() }
    }

    func die() {
        if let c = inCar {
            c.ai = .parked
            inCar = nil
        }
        wastedT = 3.2
        playerNode.isHidden = true
        heistKind = 0
        braking = false
        money = max(0, money - 100)
        save()
        toast("-$100")
    }

    func respawn() {
        wastedOverlay.alpha = 0
        wastedLabel.alpha = 0
        pHP = 100
        heat = 0
        stars = 0
        hideT = 0
        invuln = 3
        playerNode.isHidden = false
        playerPos = houseOwned ? city.houseDoor : CGPoint(x: 1250, y: 1250)
        camPos = playerPos
        for c in cars where c.ai == .chase { c.ai = .traffic }
    }

    // MARK: driving

    func driveCar(_ c: Car, throttle: CGFloat, steer: CGFloat, handbrake: Bool, dt: CGFloat) {
        let sp = c.spec
        var fwd = gVec(c.angle, 1)
        var vf = c.vel.dx * fwd.dx + c.vel.dy * fwd.dy
        let sf = gClamp(abs(vf) / 110, 0, 1)
        let rate = sp.turn * (handbrake ? 1.45 : 1.0)
        c.angle += steer * rate * sf * dt * (vf >= 0 ? 1 : -1)
        fwd = gVec(c.angle, 1)
        let rgt = CGVector(dx: fwd.dy, dy: -fwd.dx)
        vf = c.vel.dx * fwd.dx + c.vel.dy * fwd.dy
        var vr = c.vel.dx * rgt.dx + c.vel.dy * rgt.dy
        vf += sp.accel * throttle * dt
        vf -= vf * (throttle == 0 ? 1.1 : 0.35) * dt
        if handbrake { vf -= vf * 1.6 * dt }
        vf = gClamp(vf, -sp.maxSpeed * 0.35, sp.maxSpeed)
        let k: CGFloat = handbrake ? 1.3 : 8.0
        vr *= exp(-k * dt)
        c.vel = CGVector(dx: fwd.dx * vf + rgt.dx * vr, dy: fwd.dy * vf + rgt.dy * vr)
        if abs(vr) > 60 && abs(vf) > 70 {
            c.skidT -= dt
            if c.skidT <= 0 {
                c.skidT = 0.035
                addSkid(c)
            }
        }
    }

    func addSkid(_ c: Car) {
        let fwd = gVec(c.angle, 1)
        let rgt = CGVector(dx: fwd.dy, dy: -fwd.dx)
        for side in [CGFloat(-1), CGFloat(1)] {
            let px = c.pos.x - fwd.dx * c.spec.len * 0.3 + rgt.dx * c.spec.wid * 0.38 * side
            let py = c.pos.y - fwd.dy * c.spec.len * 0.3 + rgt.dy * c.spec.wid * 0.38 * side
            let s = SKSpriteNode(color: UIColor(white: 0, alpha: 0.38), size: CGSize(width: 8, height: 2.6))
            s.position = CGPoint(x: px, y: py)
            s.zRotation = c.angle
            s.zPosition = -4
            world.addChild(s)
            s.run(SKAction.sequence([SKAction.wait(forDuration: 5), SKAction.fadeOut(withDuration: 3), SKAction.removeFromParent()]))
            skids.append(s)
        }
        while skids.count > 200 {
            skids[0].removeFromParent()
            skids.removeFirst()
        }
    }

    func updatePlayerCar(_ c: Car, _ dt: CGFloat) {
        var throttle: CGFloat = 0
        var steer: CGFloat = 0
        let mag = hypot(moveVec.dx, moveVec.dy)
        if mag > 0.15 {
            let desired = atan2(moveVec.dy, moveVec.dx)
            let d = gAngDiff(desired, c.angle)
            if abs(d) > 2.3 {
                throttle = -0.9
            } else {
                throttle = min(1, mag * 1.25)
                steer = gClamp(d * 2.5, -1, 1)
            }
        }
        driveCar(c, throttle: throttle, steer: steer, handbrake: braking, dt: dt)
    }

    func decideTurn(_ c: Car, _ kx: Int, _ ky: Int) {
        func valid(_ d: Int) -> Bool {
            switch d {
            case 0: return kx < 6
            case 1: return ky < 6
            case 2: return kx > 0
            default: return ky > 0
            }
        }
        let straight = c.dir
        let left = (c.dir + 1) % 4
        let right = (c.dir + 3) % 4
        var cands: [Int] = []
        if valid(straight) {
            cands.append(straight)
            cands.append(straight)
            cands.append(straight)
        }
        if valid(left) { cands.append(left) }
        if valid(right) { cands.append(right) }
        if let d = cands.randomElement() { c.dir = d }
    }

    func updateTrafficCar(_ c: Car, _ dt: CGFloat) {
        let kx = Int((c.pos.x / PITCH).rounded())
        let ky = Int((c.pos.y / PITCH).rounded())
        var err: CGFloat = 0
        switch c.dir {
        case 0: err = (CGFloat(ky) * PITCH - 21) - c.pos.y
        case 1: err = (CGFloat(kx) * PITCH + 21) - c.pos.x
        case 2: err = (CGFloat(ky) * PITCH + 21) - c.pos.y
        default: err = (CGFloat(kx) * PITCH - 21) - c.pos.x
        }
        let sign: CGFloat = (c.dir == 0 || c.dir == 3) ? 1 : -1
        let target = CGFloat(c.dir) * CGFloat.pi / 2 + sign * gClamp(err * 0.045, -0.55, 0.55)
        let d = gAngDiff(target, c.angle)
        c.angle += gClamp(d, -2.4 * dt, 2.4 * dt)

        let along = (c.dir % 2 == 0) ? c.pos.x : c.pos.y
        let roadIdx = Int((along / PITCH).rounded())
        let distToCenter = abs(along - CGFloat(roadIdx) * PITCH)
        let crossId = roadIdx * 10 + (c.dir % 2)
        if distToCenter < 14 && c.lastCross != crossId {
            c.lastCross = crossId
            decideTurn(c, kx, ky)
        }

        var spd: CGFloat = c.type == .police ? 150 : 135
        if c.type == .truck { spd = 105 }
        let ahead = gVec(c.angle, 1)
        for o in cars where o !== c && o.ai != .parked {
            let dx = o.pos.x - c.pos.x
            let dy = o.pos.y - c.pos.y
            let proj = dx * ahead.dx + dy * ahead.dy
            let lat = abs(-dx * ahead.dy + dy * ahead.dx)
            if proj > 0 && proj < 90 && lat < 26 {
                spd = min(spd, max(0, (proj - 34) * 2))
            }
        }
        let cur = c.speed
        let nv = cur + gClamp(spd - cur, -260 * dt, 120 * dt)
        c.vel = gVec(c.angle, nv)
    }

    func updateChase(_ c: Car, _ dt: CGFloat) {
        let tp = playerPos
        let a = gAngle(c.pos, tp)
        let d = gDist(c.pos, tp)
        var steer = gClamp(gAngDiff(a, c.angle) * 2.2, -1, 1)
        var throttle: CGFloat = d < 70 ? 0.6 : 1
        if c.reverseT > 0 {
            c.reverseT -= dt
            throttle = -1
            steer = -steer
        } else if c.speed < 14 {
            c.stuckT += dt
            if c.stuckT > 1.0 {
                c.stuckT = 0
                c.reverseT = 0.9
            }
        } else {
            c.stuckT = 0
        }
        driveCar(c, throttle: throttle, steer: steer, handbrake: false, dt: dt)
        c.losTimer -= dt
        if c.losTimer <= 0 {
            c.losTimer = 0.3
            c.sees = d < 520 && city.hasLOS(c.pos, tp)
        }
    }

    func updateTank(_ c: Car, _ dt: CGFloat) {
        let tp = playerPos
        let a = gAngle(c.pos, tp)
        let d = gDist(c.pos, tp)
        let steer = gClamp(gAngDiff(a, c.angle) * 1.5, -1, 1)
        driveCar(c, throttle: d > 320 ? 0.7 : 0, steer: steer, handbrake: false, dt: dt)
        c.turret?.zRotation = a - c.angle
        c.shootCD -= dt
        c.losTimer -= dt
        if c.losTimer <= 0 {
            c.losTimer = 0.3
            c.sees = d < 560 && city.hasLOS(c.pos, tp)
        }
        if c.shootCD <= 0 && c.sees && d < 520 && hideT <= 0 {
            c.shootCD = 3.2
            let o = CGPoint(x: c.pos.x + cos(a) * 52, y: c.pos.y + sin(a) * 52)
            spawnBullet(pos: o, angle: a, speed: 420, dmg: 45, life: 1.6, friendly: false, pierce: false, kind: 5)
            shakeT = max(shakeT, 0.15)
        }
    }

    func updateCars(_ dt: CGFloat) {
        var keep: [Car] = []
        let blink = Int(lightT * 6) % 2 == 0
        for c in cars {
            if c.hp <= 0 {
                destroyCar(c)
                continue
            }
            if c.type == .police && c.ai == .traffic && stars > 0 { c.ai = .chase }
            if c.type == .police && c.ai == .chase && stars == 0 {
                c.ai = .traffic
                c.dir = ((Int((c.angle / (CGFloat.pi / 2)).rounded()) % 4) + 4) % 4
                c.lastCross = -1
            }
            switch c.ai {
            case .traffic: updateTrafficCar(c, dt)
            case .chase: updateChase(c, dt)
            case .player: updatePlayerCar(c, dt)
            case .tank: updateTank(c, dt)
            case .parked:
                let f = CGFloat(pow(0.03, Double(dt)))
                c.vel = CGVector(dx: c.vel.dx * f, dy: c.vel.dy * f)
            case .still:
                c.vel = CGVector.zero
            }
            if c.ai != .still {
                c.pos.x += c.vel.dx * dt
                c.pos.y += c.vel.dy * dt
                let impact = city.collide(&c.pos, c.spec.radius, &c.vel, 0.3)
                if impact > 70 {
                    c.hp -= impact * 0.12
                    if impact > 130 {
                        spark(at: c.pos)
                        if c.ai == .player { shakeT = max(shakeT, 0.25) }
                    }
                }
            }
            c.node.position = c.pos
            c.node.zRotation = c.angle
            if let bar = c.lightBar {
                (bar.childNode(withName: "red") as? SKSpriteNode)?.alpha = (c.ai == .chase || c.ai == .player || c.type == .swat) && blink ? 1 : 0
                (bar.childNode(withName: "blue") as? SKSpriteNode)?.alpha = (c.ai == .chase || c.ai == .player || c.type == .swat) && !blink ? 1 : 0
            }
            c.light?.alpha = c.ai == .player ? 0.65 : 0.4
            if c.hp < 90 {
                c.smokeT -= dt
                if c.smokeT <= 0 {
                    c.smokeT = c.hp < 40 ? 0.05 : 0.14
                    puff(at: c.pos, fire: c.hp < 40)
                }
                if c.hp < 25 { c.hp -= dt * 8 }
            }
            keep.append(c)
        }
        cars = keep
        // keep the street populated
        trafficT -= dt
        if trafficT <= 0 {
            trafficT = 1.5
            var count = 0
            for c in cars where c.ai == .traffic && c.type != .police { count += 1 }
            if count < 18 { spawnTrafficCar(far: true) }
            // clean up far away leftovers
            for c in cars where c.ai == .parked && c !== inCar && gDist(c.pos, playerPos) > 1400 {
                c.hp = -1000
            }
        }
    }

    func destroyCar(_ c: Car) {
        explode(at: c.pos, radius: 80, dmg: 80, byPlayer: c.lastHitByPlayer)
        if c === inCar {
            inCar = nil
            playerPos = c.pos
            playerNode.isHidden = false
            damagePlayer(35)
        }
        let wreck = SKSpriteNode(texture: c.body.texture, color: UIColor.black, size: c.body.size)
        wreck.colorBlendFactor = 0.85
        wreck.position = c.pos
        wreck.zRotation = c.angle
        wreck.zPosition = 1
        world.addChild(wreck)
        wreck.run(SKAction.sequence([SKAction.wait(forDuration: 20), SKAction.fadeOut(withDuration: 3), SKAction.removeFromParent()]))
        c.node.removeFromParent()
    }

    func collideCars() {
        if cars.count < 2 { return }
        for i in 0..<(cars.count - 1) {
            for j in (i + 1)..<cars.count {
                let a = cars[i]
                let b = cars[j]
                let dx = b.pos.x - a.pos.x
                let dy = b.pos.y - a.pos.y
                let d = hypot(dx, dy)
                let minD = a.spec.radius + b.spec.radius
                if d >= minD || d < 0.01 { continue }
                let nx = dx / d
                let ny = dy / d
                let overlap = minD - d
                let wa: CGFloat = a.ai == .still ? 0 : 1
                let wb: CGFloat = b.ai == .still ? 0 : 1
                let tot = wa + wb
                if tot == 0 { continue }
                a.pos.x -= nx * overlap * wa / tot
                a.pos.y -= ny * overlap * wa / tot
                b.pos.x += nx * overlap * wb / tot
                b.pos.y += ny * overlap * wb / tot
                let rv = (b.vel.dx - a.vel.dx) * nx + (b.vel.dy - a.vel.dy) * ny
                if rv < 0 {
                    let imp = -1.3 * rv / tot
                    a.vel.dx -= imp * wa * nx
                    a.vel.dy -= imp * wa * ny
                    b.vel.dx += imp * wb * nx
                    b.vel.dy += imp * wb * ny
                    let dmg = -rv * 0.1
                    a.hp -= dmg
                    b.hp -= dmg
                    if a.ai == .player { b.lastHitByPlayer = true }
                    if b.ai == .player { a.lastHitByPlayer = true }
                    if -rv > 120 {
                        spark(at: CGPoint(x: (a.pos.x + b.pos.x) / 2, y: (a.pos.y + b.pos.y) / 2))
                        if a.ai == .player || b.ai == .player { shakeT = max(shakeT, 0.22) }
                    }
                    if -rv > 90 && (a.ai == .player || b.ai == .player) {
                        let other = a.ai == .player ? b : a
                        if other.type == .police || other.type == .swat { crime(35, at: other.pos) }
                    }
                }
            }
        }
    }

    // MARK: peds

    func ringStep(_ p: Ped, _ dt: CGFloat, _ speed: CGFloat) {
        let bx = city.blockOf(p.pos.x)
        let by = city.blockOf(p.pos.y)
        let r = ringRect(bx, by)
        switch p.ringDir {
        case 0:
            p.pos.x += speed * dt
            p.pos.y = r.minY + p.ringOff
            if p.pos.x >= r.maxX { p.pos.x = r.maxX; p.ringDir = 1 }
        case 1:
            p.pos.y += speed * dt
            p.pos.x = r.maxX + p.ringOff
            if p.pos.y >= r.maxY { p.pos.y = r.maxY; p.ringDir = 2 }
        case 2:
            p.pos.x -= speed * dt
            p.pos.y = r.maxY + p.ringOff
            if p.pos.x <= r.minX { p.pos.x = r.minX; p.ringDir = 3 }
        default:
            p.pos.y -= speed * dt
            p.pos.x = r.minX + p.ringOff
            if p.pos.y <= r.minY { p.pos.y = r.minY; p.ringDir = 0 }
        }
        let angles: [CGFloat] = [0, CGFloat.pi / 2, CGFloat.pi, -CGFloat.pi / 2]
        p.angle = angles[p.ringDir]
    }

    func snapToRing(_ p: Ped) {
        let bx = city.blockOf(p.pos.x)
        let by = city.blockOf(p.pos.y)
        let r = ringRect(bx, by)
        var x = gClamp(p.pos.x, r.minX, r.maxX)
        var y = gClamp(p.pos.y, r.minY, r.maxY)
        let dl = x - r.minX
        let dr = r.maxX - x
        let db = y - r.minY
        let dtop = r.maxY - y
        let m = min(min(dl, dr), min(db, dtop))
        if m == db { y = r.minY; p.ringDir = 0 }
        else if m == dr { x = r.maxX; p.ringDir = 1 }
        else if m == dtop { y = r.maxY; p.ringDir = 2 }
        else { x = r.minX; p.ringDir = 3 }
        p.pos = CGPoint(x: x, y: y)
    }

    func updatePeds(_ dt: CGFloat) {
        var keep: [Ped] = []
        for p in peds {
            if p.dead {
                p.deadT += dt
                if p.deadT > 8 {
                    p.node.removeFromParent()
                    continue
                }
                keep.append(p)
                continue
            }
            p.shootCD -= dt
            p.losTimer -= dt
            switch p.kind {
            case .civilian: updateCivilian(p, dt)
            case .cop, .swat: updateCop(p, dt)
            case .gang: updateGang(p, dt)
            case .crew: updateCrew(p, dt)
            }
            var v = p.vel
            _ = city.collide(&p.pos, 7, &v, 0)
            p.node.position = p.pos
            p.sprite.zRotation = p.angle
            keep.append(p)
        }
        peds = keep

        // run over by cars
        for p in peds where !p.dead {
            for c in cars where c.speed > 90 && c.ai != .parked {
                if gDist(c.pos, p.pos) < c.spec.radius + 5 {
                    hurtPed(p, c.speed * 0.5, byPlayer: c.ai == .player)
                    p.pos.x += c.vel.dx * 0.05
                    p.pos.y += c.vel.dy * 0.05
                }
            }
        }

        pedT -= dt
        if pedT <= 0 {
            pedT = 1.2
            var n = 0
            for p in peds where p.kind == .civilian && !p.dead { n += 1 }
            if n < 30 { spawnCivilian(far: true) }
        }
    }

    func updateCivilian(_ p: Ped, _ dt: CGFloat) {
        if p.fear > 0 {
            p.fear -= dt
            let a = gAngle(p.fearFrom, p.pos)
            p.pos.x += cos(a) * 115 * dt
            p.pos.y += sin(a) * 115 * dt
            p.angle = a
            p.walk += dt * 14
            if p.fear <= 0 { snapToRing(p) }
        } else {
            ringStep(p, dt, 38)
            p.walk += dt * 6
        }
        p.sprite.setScale(1 + 0.05 * sin(p.walk))
    }

    func updateCop(_ p: Ped, _ dt: CGFloat) {
        if stars > 0 {
            p.chasing = true
            let d = gDist(p.pos, playerPos)
            let a = gAngle(p.pos, playerPos)
            p.angle = a
            if p.losTimer <= 0 {
                p.losTimer = 0.3
                p.sees = d < 520 && city.hasLOS(p.pos, playerPos)
            }
            if d > 130 || !p.sees {
                p.pos.x += cos(a) * 105 * dt
                p.pos.y += sin(a) * 105 * dt
            }
            if p.sees && d < 340 && p.shootCD <= 0 && hideT <= 0 && wastedT <= 0 {
                p.shootCD = p.kind == .swat ? 0.7 : 1.0
                enemyShoot(from: p.pos, angle: a + CGFloat.random(in: -0.13...0.13), dmg: p.kind == .swat ? 9 : 6)
            }
            p.walk += dt * 10
        } else {
            if p.chasing {
                p.chasing = false
                if p.terr == -2 || p.terr == -3 {
                    p.hp = 0
                    p.dead = true
                    p.node.removeFromParent()
                    return
                }
                snapToRing(p)
            }
            ringStep(p, dt, 36)
            p.walk += dt * 6
        }
        p.sprite.setScale(1 + 0.05 * sin(p.walk))
    }

    func updateGang(_ p: Ped, _ dt: CGFloat) {
        let d = gDist(p.pos, playerPos)
        if p.losTimer <= 0 {
            p.losTimer = 0.3
            p.sees = d < 300 && city.hasLOS(p.pos, playerPos) && hideT <= 0
        }
        if p.sees {
            let a = gAngle(p.pos, playerPos)
            p.angle = a
            if d > 150 {
                p.pos.x += cos(a) * 85 * dt
                p.pos.y += sin(a) * 85 * dt
            }
            if p.shootCD <= 0 && d < 300 {
                p.shootCD = 0.9
                enemyShoot(from: p.pos, angle: a + CGFloat.random(in: -0.15...0.15), dmg: 7)
            }
        } else if gDist(p.pos, p.home) > 90 {
            let a = gAngle(p.pos, p.home)
            p.pos.x += cos(a) * 50 * dt
            p.pos.y += sin(a) * 50 * dt
            p.angle = a
        }
    }

    func updateCrew(_ p: Ped, _ dt: CGFloat) {
        var target: Ped?
        var best: CGFloat = 320
        for q in peds where !q.dead && (q.kind == .cop || q.kind == .swat || q.kind == .gang) {
            let d = gDist(p.pos, q.pos)
            if d < best && city.hasLOS(p.pos, q.pos) {
                best = d
                target = q
            }
        }
        let dp = gDist(p.pos, playerPos)
        if dp > 650 {
            p.pos = CGPoint(x: playerPos.x + CGFloat.random(in: -60...60), y: playerPos.y + CGFloat.random(in: -60...60))
        }
        if let t = target {
            let a = gAngle(p.pos, t.pos)
            p.angle = a
            if p.shootCD <= 0 {
                p.shootCD = 0.45
                spawnBullet(pos: CGPoint(x: p.pos.x + cos(a) * 14, y: p.pos.y + sin(a) * 14), angle: a + CGFloat.random(in: -0.08...0.08), speed: 800, dmg: 14, life: 0.7, friendly: true, pierce: false, kind: 6)
            }
        }
        if dp > 70 {
            let a = gAngle(p.pos, playerPos)
            p.pos.x += cos(a) * 140 * dt
            p.pos.y += sin(a) * 140 * dt
            if target == nil { p.angle = a }
        }
    }

    func enemyShoot(from p: CGPoint, angle: CGFloat, dmg: CGFloat) {
        spawnBullet(pos: CGPoint(x: p.x + cos(angle) * 14, y: p.y + sin(angle) * 14), angle: angle, speed: 620, dmg: dmg, life: 0.9, friendly: false, pierce: false, kind: 6)
    }

    func alarm(at p: CGPoint, radius: CGFloat) {
        for q in peds where q.kind == .civilian && !q.dead && gDist(q.pos, p) < radius {
            q.fear = 5
            q.fearFrom = p
        }
    }

    func hurtPed(_ p: Ped, _ dmg: CGFloat, byPlayer: Bool) {
        if p.dead { return }
        p.hp -= dmg
        if p.kind == .civilian {
            p.fear = 6
            p.fearFrom = byPlayer ? playerPos : p.pos
        }
        if p.hp <= 0 { killPed(p, byPlayer) }
    }

    func killPed(_ p: Ped, _ byPlayer: Bool) {
        p.dead = true
        p.sprite.alpha = 0.55
        p.sprite.zRotation = CGFloat.random(in: 0..<(2 * CGFloat.pi))
        p.node.zPosition = 1
        if p.kind == .civilian { dropCash(at: p.pos, value: Int.random(in: 20...90)) }
        if p.kind == .gang { dropCash(at: p.pos, value: Int.random(in: 100...220)) }
        if p.kind == .crew { crewCount = max(0, crewCount - 1) }
        if byPlayer {
            if p.kind == .civilian { crime(30, at: p.pos) }
            if p.kind == .cop { crime(70, at: p.pos) }
            if p.kind == .swat { crime(80, at: p.pos) }
        }
    }

    func dropCash(at p: CGPoint, value: Int) {
        let s = SKSpriteNode(color: UIColor(red: 0.3, green: 0.85, blue: 0.35, alpha: 1), size: CGSize(width: 9, height: 5))
        s.position = p
        s.zPosition = 1.5
        world.addChild(s)
        cashes.append(Cash(node: s, pos: p, value: value))
    }

    func updateCash(_ dt: CGFloat) {
        var keep: [Cash] = []
        for c in cashes {
            c.life -= dt
            if gDist(c.pos, playerPos) < 24 && wastedT <= 0 && hideT <= 0 {
                money += c.value
                save()
                c.node.removeFromParent()
                continue
            }
            if c.life <= 0 {
                c.node.removeFromParent()
                continue
            }
            keep.append(c)
        }
        cashes = keep
    }

    // MARK: weapons and bullets

    func fireWeapon(from p: CGPoint, angle: CGFloat) {
        if fireCD > 0 { return }
        let w = WEAPONS[weaponIdx]
        fireCD = w.rate
        for _ in 0..<w.pellets {
            let a = angle + CGFloat.random(in: -w.spread...w.spread)
            var origin = p
            if w.dual {
                let side: CGFloat = (shotCount % 2 == 0) ? 1 : -1
                origin = CGPoint(x: p.x + cos(angle + CGFloat.pi / 2) * 7 * side, y: p.y + sin(angle + CGFloat.pi / 2) * 7 * side)
            }
            spawnBullet(pos: origin, angle: a, speed: w.speed, dmg: w.dmg, life: w.life, friendly: true, pierce: w.pierce, kind: w.kind)
        }
        shotCount += 1
        if w.kind != 1 {
            let f = SKSpriteNode(texture: glowTex, color: UIColor.orange, size: CGSize(width: 28, height: 28))
            f.colorBlendFactor = 1
            f.blendMode = .add
            f.position = CGPoint(x: p.x + cos(angle) * 8, y: p.y + sin(angle) * 8)
            f.zPosition = 6
            world.addChild(f)
            f.run(SKAction.sequence([SKAction.fadeOut(withDuration: 0.06), SKAction.removeFromParent()]))
            alarm(at: p, radius: 420)
        } else {
            alarm(at: p, radius: 200)
        }
        if crimeCD <= 0 {
            crimeCD = 0.6
            crime(6, at: p)
        }
        if w.rate > 0.5 { shakeT = max(shakeT, 0.08) }
    }

    func spawnBullet(pos: CGPoint, angle: CGFloat, speed: CGFloat, dmg: CGFloat, life: CGFloat, friendly: Bool, pierce: Bool, kind: Int) {
        let node: SKSpriteNode
        switch kind {
        case 1:
            node = SKSpriteNode(texture: glowTex, color: UIColor(red: 1, green: 0.5, blue: 0.1, alpha: 1), size: CGSize(width: 14, height: 14))
            node.colorBlendFactor = 1
            node.blendMode = .add
            node.run(SKAction.group([SKAction.scale(to: 2.6, duration: Double(life)), SKAction.fadeOut(withDuration: Double(life))]))
        case 2, 3, 5:
            node = SKSpriteNode(color: kind == 2 ? UIColor(white: 0.6, alpha: 1) : UIColor(red: 0.9, green: 0.2, blue: 0.1, alpha: 1), size: CGSize(width: kind == 5 ? 10 : 15, height: 5))
            let g = SKSpriteNode(texture: glowTex, color: UIColor.orange, size: CGSize(width: 22, height: 22))
            g.colorBlendFactor = 1
            g.blendMode = .add
            g.position = CGPoint(x: -8, y: 0)
            node.addChild(g)
        case 4:
            node = SKSpriteNode(color: UIColor(white: 0.3, alpha: 1), size: CGSize(width: 10, height: 4))
            let g = SKSpriteNode(color: UIColor.red, size: CGSize(width: 3, height: 3))
            g.position = CGPoint(x: 5, y: 0)
            node.addChild(g)
        default:
            node = SKSpriteNode(color: UIColor(red: 1, green: 0.9, blue: 0.55, alpha: 1), size: CGSize(width: 14, height: 2.2))
            node.blendMode = .add
        }
        node.position = pos
        node.zRotation = angle
        node.zPosition = 5
        world.addChild(node)
        let b = Bullet(node: node, pos: pos, vel: gVec(angle, speed), dmg: dmg, life: life, friendly: friendly, pierce: pierce, kind: kind)
        if kind == 3 { b.homing = true }
        bullets.append(b)
    }

    func throwBomb() {
        if bombCD > 0 || wastedT > 0 || hideT > 0 { return }
        bombCD = 1.0
        let a = aiming ? aimAngle : (inCar?.angle ?? pAngle)
        let o = inCar?.pos ?? playerPos
        spawnBullet(pos: o, angle: a, speed: 300, dmg: 0, life: 1.4, friendly: true, pierce: false, kind: 4)
    }

    func spark(at p: CGPoint) {
        for _ in 0..<4 {
            let s = SKSpriteNode(color: UIColor(red: 1, green: 0.85, blue: 0.4, alpha: 1), size: CGSize(width: 3, height: 1.5))
            s.blendMode = .add
            s.position = p
            s.zPosition = 6
            s.zRotation = CGFloat.random(in: 0..<(2 * CGFloat.pi))
            world.addChild(s)
            let a = s.zRotation
            s.run(SKAction.sequence([
                SKAction.group([SKAction.moveBy(x: cos(a) * 22, y: sin(a) * 22, duration: 0.2), SKAction.fadeOut(withDuration: 0.2)]),
                SKAction.removeFromParent()
            ]))
        }
    }

    func puff(at p: CGPoint, fire: Bool) {
        let s = SKSpriteNode(texture: smokeTex, size: CGSize(width: 20, height: 20))
        if fire {
            s.texture = glowTex
            s.color = UIColor.orange
            s.colorBlendFactor = 1
            s.blendMode = .add
        }
        s.position = CGPoint(x: p.x + CGFloat.random(in: -6...6), y: p.y + CGFloat.random(in: -6...6))
        s.zPosition = 7
        world.addChild(s)
        s.run(SKAction.sequence([
            SKAction.group([SKAction.moveBy(x: CGFloat.random(in: -10...10), y: 25, duration: 0.9), SKAction.scale(to: 2.4, duration: 0.9), SKAction.fadeOut(withDuration: 0.9)]),
            SKAction.removeFromParent()
        ]))
    }

    func explode(at p: CGPoint, radius: CGFloat, dmg: CGFloat, byPlayer: Bool) {
        let fb = SKSpriteNode(texture: glowTex, color: UIColor(red: 1, green: 0.55, blue: 0.1, alpha: 1), size: CGSize(width: radius * 2.4, height: radius * 2.4))
        fb.colorBlendFactor = 1
        fb.blendMode = .add
        fb.position = p
        fb.zPosition = 8
        fb.setScale(0.3)
        world.addChild(fb)
        fb.run(SKAction.sequence([SKAction.group([SKAction.scale(to: 1.1, duration: 0.25), SKAction.fadeOut(withDuration: 0.5)]), SKAction.removeFromParent()]))
        let core = SKSpriteNode(texture: glowTex, color: UIColor.white, size: CGSize(width: radius, height: radius))
        core.colorBlendFactor = 0
        core.blendMode = .add
        core.position = p
        core.zPosition = 8.5
        world.addChild(core)
        core.run(SKAction.sequence([SKAction.fadeOut(withDuration: 0.18), SKAction.removeFromParent()]))
        for _ in 0..<7 { puff(at: p, fire: false) }
        for _ in 0..<4 { spark(at: p) }
        let scorch = SKSpriteNode(texture: glowTex, color: UIColor.black, size: CGSize(width: radius * 1.6, height: radius * 1.6))
        scorch.colorBlendFactor = 1
        scorch.alpha = 0.55
        scorch.position = p
        scorch.zPosition = -3
        world.addChild(scorch)
        scorch.run(SKAction.sequence([SKAction.wait(forDuration: 10), SKAction.fadeOut(withDuration: 3), SKAction.removeFromParent()]))
        shakeT = max(shakeT, 0.3 + radius / 400)
        alarm(at: p, radius: 480)

        for q in peds where !q.dead {
            let d = gDist(q.pos, p)
            if d < radius {
                hurtPed(q, dmg * (1 - d / radius) + 10, byPlayer: byPlayer)
            }
        }
        for c in cars {
            let d = gDist(c.pos, p)
            if d < radius + c.spec.radius {
                c.hp -= dmg * (1 - d / (radius + c.spec.radius)) * 1.2
                let a = gAngle(p, c.pos)
                c.vel.dx += cos(a) * 120
                c.vel.dy += sin(a) * 120
                if byPlayer { c.lastHitByPlayer = true }
            }
        }
        if inCar == nil && gDist(playerPos, p) < radius && wastedT <= 0 {
            damagePlayer(dmg * (1 - gDist(playerPos, p) / radius) * 0.9)
        }
        for f in flyers where gDist(f.pos, p) < radius + 20 {
            f.hp -= dmg
        }
        if byPlayer { crime(25, at: p) }
    }

    func updateBullets(_ dt: CGFloat) {
        var keep: [Bullet] = []
        for b in bullets {
            if b.dead {
                b.node.removeFromParent()
                continue
            }
            b.life -= dt
            if b.kind == 4 {
                let f = CGFloat(pow(0.15, Double(dt)))
                b.vel = CGVector(dx: b.vel.dx * f, dy: b.vel.dy * f)
                b.pos.x += b.vel.dx * dt
                b.pos.y += b.vel.dy * dt
                _ = city.collide(&b.pos, 4, &b.vel, 0.5)
                b.node.position = b.pos
                b.node.zRotation += dt * 10
                if b.life <= 0 {
                    explode(at: b.pos, radius: 110, dmg: 170, byPlayer: true)
                    b.node.removeFromParent()
                    continue
                }
                keep.append(b)
                continue
            }
            if b.homing {
                let a = atan2(b.vel.dy, b.vel.dx)
                let want = gAngle(b.pos, playerPos)
                let na = a + gClamp(gAngDiff(want, a), -2.2 * dt, 2.2 * dt)
                let sp = hypot(b.vel.dx, b.vel.dy)
                b.vel = gVec(na, sp)
            }
            let move = hypot(b.vel.dx, b.vel.dy) * dt
            let steps = max(1, Int(ceil(move / 9)))
            let sdt = dt / CGFloat(steps)
            var alive = true
            for _ in 0..<steps {
                let prev = b.pos
                b.pos.x += b.vel.dx * sdt
                b.pos.y += b.vel.dy * sdt
                if bulletHitsWorld(b, prev, hypot(b.vel.dx, b.vel.dy) * sdt) {
                    alive = false
                    break
                }
                if bulletHitsEntities(b) {
                    alive = false
                    break
                }
            }
            if !alive || b.life <= 0 || b.pos.x < 0 || b.pos.x > CITY || b.pos.y < 0 || b.pos.y > CITY {
                if alive && b.life <= 0 && (b.kind == 2 || b.kind == 3 || b.kind == 5) {
                    explode(at: b.pos, radius: 80, dmg: 100, byPlayer: b.friendly)
                }
                b.node.removeFromParent()
                continue
            }
            b.node.position = b.pos
            b.node.zRotation = atan2(b.vel.dy, b.vel.dx)
            keep.append(b)
        }
        bullets = keep
    }

    func bulletHitsWorld(_ b: Bullet, _ prev: CGPoint, _ stepLen: CGFloat) -> Bool {
        let bx = city.blockOf(b.pos.x)
        let by = city.blockOf(b.pos.y)
        for i in city.blocks[bx][by] {
            let bl = city.blds[i]
            if bl.kind == 4 { continue }
            if !bl.rect.contains(b.pos) { continue }
            if b.kind == 2 || b.kind == 3 || b.kind == 5 {
                explode(at: prev, radius: b.kind == 2 ? 90 : 60, dmg: b.kind == 2 ? 150 : 40, byPlayer: b.friendly)
                return true
            }
            if b.kind == 1 { return true }
            if b.pierce {
                b.wall += stepLen
                b.dmg *= 0.99
                if b.wall > 70 {
                    spark(at: b.pos)
                    return true
                }
                return false
            }
            if b.kind == 6 && b.bounces < 2 {
                if prev.x < bl.rect.minX || prev.x > bl.rect.maxX {
                    b.vel.dx = -b.vel.dx
                } else {
                    b.vel.dy = -b.vel.dy
                }
                b.pos = prev
                b.bounces += 1
                b.dmg *= 0.5
                b.life = min(b.life, 0.5)
                spark(at: prev)
                return false
            }
            spark(at: prev)
            return true
        }
        return false
    }

    func bulletHitsEntities(_ b: Bullet) -> Bool {
        if b.friendly {
            for p in peds where !p.dead && p.kind != .crew {
                if gDist(p.pos, b.pos) < 9 {
                    if b.kind == 2 {
                        explode(at: b.pos, radius: 90, dmg: 150, byPlayer: true)
                        return true
                    }
                    hurtPed(p, b.dmg, byPlayer: true)
                    spark(at: b.pos)
                    if b.pierce {
                        b.dmg *= 0.6
                        continue
                    }
                    return true
                }
            }
            for c in cars where c.ai != .player {
                if gDist(c.pos, b.pos) < c.spec.radius + 2 {
                    if b.kind == 2 {
                        explode(at: b.pos, radius: 90, dmg: 150, byPlayer: true)
                        return true
                    }
                    c.hp -= b.dmg * (b.kind == 1 ? 0.6 : 1)
                    c.lastHitByPlayer = true
                    if b.kind != 1 { spark(at: b.pos) }
                    if c.type == .police || c.type == .swat { crime(10, at: c.pos) }
                    if b.pierce {
                        b.dmg *= 0.5
                        continue
                    }
                    return true
                }
            }
            for f in flyers {
                if gDist(f.pos, b.pos) < 28 {
                    f.hp -= b.dmg
                    spark(at: b.pos)
                    if b.kind == 2 {
                        explode(at: b.pos, radius: 90, dmg: 150, byPlayer: true)
                    }
                    return true
                }
            }
        } else {
            if hideT <= 0 && wastedT <= 0 {
                if let car = inCar {
                    if gDist(b.pos, car.pos) < car.spec.radius + 3 {
                        if b.kind == 3 || b.kind == 5 {
                            explode(at: b.pos, radius: b.kind == 3 ? 55 : 70, dmg: b.kind == 3 ? 38 : 45, byPlayer: false)
                        } else {
                            car.hp -= b.dmg * 0.8
                            damagePlayer(b.dmg * 0.2)
                            spark(at: b.pos)
                        }
                        return true
                    }
                } else if gDist(b.pos, playerPos) < 9 {
                    if b.kind == 3 || b.kind == 5 {
                        explode(at: b.pos, radius: b.kind == 3 ? 55 : 70, dmg: b.kind == 3 ? 38 : 45, byPlayer: false)
                    } else {
                        damagePlayer(b.dmg)
                    }
                    return true
                }
            }
            for p in peds where p.kind == .crew && !p.dead {
                if gDist(p.pos, b.pos) < 9 {
                    hurtPed(p, b.dmg, byPlayer: false)
                    return true
                }
            }
        }
        return false
    }

    // MARK: flyers (choppers and drones)

    func spawnFlyer(kind: Int) {
        let a = CGFloat.random(in: 0..<(2 * CGFloat.pi))
        let p = CGPoint(x: playerPos.x + cos(a) * 700, y: playerPos.y + sin(a) * 700)
        let f = Flyer(kind: kind, pos: p)
        f.orbit = a
        if kind == 0 {
            let sh = SKShapeNode(ellipseOf: CGSize(width: 70, height: 26))
            sh.fillColor = UIColor(white: 0, alpha: 0.28)
            sh.strokeColor = UIColor.clear
            sh.position = CGPoint(x: 18, y: -22)
            sh.zPosition = -1
            f.node.addChild(sh)
            let body = SKShapeNode(ellipseOf: CGSize(width: 50, height: 20))
            body.fillColor = UIColor(red: 0.1, green: 0.14, blue: 0.3, alpha: 1)
            body.strokeColor = UIColor(white: 0, alpha: 0.7)
            f.node.addChild(body)
            let tail = SKSpriteNode(color: UIColor(red: 0.1, green: 0.14, blue: 0.3, alpha: 1), size: CGSize(width: 34, height: 5))
            tail.position = CGPoint(x: -38, y: 0)
            f.node.addChild(tail)
            let glass = SKShapeNode(ellipseOf: CGSize(width: 16, height: 14))
            glass.fillColor = UIColor(red: 0.5, green: 0.8, blue: 1, alpha: 0.8)
            glass.strokeColor = UIColor.clear
            glass.position = CGPoint(x: 14, y: 0)
            f.node.addChild(glass)
            let rotor = SKNode()
            rotor.zPosition = 1
            let b1 = SKSpriteNode(color: UIColor(white: 0.1, alpha: 0.85), size: CGSize(width: 80, height: 3))
            let b2 = SKSpriteNode(color: UIColor(white: 0.1, alpha: 0.85), size: CGSize(width: 3, height: 80))
            rotor.addChild(b1)
            rotor.addChild(b2)
            f.node.addChild(rotor)
            f.rotor = rotor
            let l = SKShapeNode()
            l.strokeColor = UIColor(red: 1, green: 0.1, blue: 0.1, alpha: 0.9)
            l.lineWidth = 1.5
            l.zPosition = 20
            l.isHidden = true
            world.addChild(l)
            f.laser = l
        } else {
            let sh = SKShapeNode(circleOfRadius: 12)
            sh.fillColor = UIColor(white: 0, alpha: 0.28)
            sh.strokeColor = UIColor.clear
            sh.position = CGPoint(x: 14, y: -18)
            sh.zPosition = -1
            f.node.addChild(sh)
            let body = SKShapeNode(circleOfRadius: 10)
            body.fillColor = UIColor(white: 0.2, alpha: 1)
            body.strokeColor = UIColor(red: 1, green: 0.2, blue: 0.2, alpha: 1)
            body.lineWidth = 2
            f.node.addChild(body)
            let rotor = SKNode()
            rotor.addChild(SKSpriteNode(color: UIColor(white: 0.8, alpha: 0.7), size: CGSize(width: 34, height: 2)))
            rotor.addChild(SKSpriteNode(color: UIColor(white: 0.8, alpha: 0.7), size: CGSize(width: 2, height: 34)))
            rotor.zPosition = 1
            f.node.addChild(rotor)
            f.rotor = rotor
        }
        world.addChild(f.node)
        flyers.append(f)
    }

    func updateFlyers(_ dt: CGFloat) {
        var keep: [Flyer] = []
        for f in flyers {
            if f.hp <= 0 {
                explode(at: f.pos, radius: 70, dmg: 60, byPlayer: true)
                f.node.removeFromParent()
                f.laser?.removeFromParent()
                continue
            }
            let needed = f.kind == 0 ? 3 : 5
            if stars < needed {
                f.node.removeFromParent()
                f.laser?.removeFromParent()
                continue
            }
            f.orbit += (f.kind == 0 ? 0.5 : 0.9) * dt
            let r: CGFloat = f.kind == 0 ? 170 : 230
            let target = CGPoint(x: playerPos.x + cos(f.orbit) * r, y: playerPos.y + sin(f.orbit) * r)
            let a = gAngle(f.pos, target)
            let d = gDist(f.pos, target)
            let sp: CGFloat = min(d * 2, f.kind == 0 ? 230 : 330)
            f.pos.x += cos(a) * sp * dt
            f.pos.y += sin(a) * sp * dt
            f.node.position = f.pos
            f.node.zRotation = gAngle(f.pos, playerPos)
            f.rotor?.zRotation += dt * 25
            f.cd -= dt
            if f.kind == 0 {
                if f.aimT > 0 {
                    f.aimT -= dt
                    let path = CGMutablePath()
                    path.move(to: f.pos)
                    path.addLine(to: playerPos)
                    f.laser?.path = path
                    f.laser?.isHidden = false
                    if f.aimT <= 0 {
                        f.laser?.isHidden = true
                        if hideT <= 0 && wastedT <= 0 {
                            damagePlayer(inCar == nil ? 20 : 8)
                            if let c = inCar { c.hp -= 25 }
                            spark(at: playerPos)
                        }
                        f.cd = 2.4
                    }
                } else if f.cd <= 0 && hideT <= 0 {
                    f.aimT = 0.8
                }
            } else {
                if f.cd <= 0 && hideT <= 0 {
                    f.cd = 3.2
                    let aa = gAngle(f.pos, playerPos)
                    spawnBullet(pos: f.pos, angle: aa, speed: 230, dmg: 38, life: 5, friendly: false, pierce: false, kind: 3)
                }
            }
            keep.append(f)
        }
        flyers = keep
    }

    // MARK: police

    func copSees(_ p: CGPoint) -> Bool {
        for c in cars where (c.type == .police || c.type == .swat) && c.ai != .player {
            if gDist(c.pos, p) < 430 && city.hasLOS(c.pos, p) { return true }
        }
        for q in peds where !q.dead && (q.kind == .cop || q.kind == .swat) {
            if gDist(q.pos, p) < 430 && city.hasLOS(q.pos, p) { return true }
        }
        for f in flyers where gDist(f.pos, p) < 650 { return true }
        return false
    }

    func crime(_ pts: CGFloat, at p: CGPoint) {
        if wastedT > 0 { return }
        if copSees(p) {
            heat += pts
            noSeeT = 0
        }
    }

    func chaseCount(_ type: CarType) -> Int {
        var n = 0
        for c in cars where c.type == type && (c.ai == .chase || c.ai == .tank || c.ai == .still) { n += 1 }
        return n
    }

    func updatePolice(_ dt: CGFloat) {
        heat = max(0, min(520, heat))
        let th: [CGFloat] = [25, 70, 140, 240, 380]
        var s = 0
        for t in th where heat >= t { s += 1 }
        if s != stars {
            if s > stars { toast(String(repeating: "★", count: s) + " WANTED") }
            stars = s
        }

        var seen = false
        for c in cars where (c.type == .police || c.type == .swat || c.type == .tank) && c.ai != .player && c.sees { seen = true }
        for q in peds where !q.dead && (q.kind == .cop || q.kind == .swat) && q.sees { seen = true }
        for f in flyers where gDist(f.pos, playerPos) < 600 { seen = true }
        if stars > 0 {
            if seen { noSeeT = 0 } else { noSeeT += dt }
            if noSeeT > 9 { heat -= 14 * dt }
        }
        if stars == 0 { return }

        // cruisers
        copT -= dt
        if copT <= 0 {
            copT = 2.5
            if chaseCount(.police) < min(8, stars * 2) {
                if let (p, dir) = randomRoadSpot(minD: 550) {
                    let c = makeCar(.police, at: p, angle: gAngle(p, playerPos), ai: .chase)
                    c.dir = dir
                    c.hasDriver = true
                    c.vel = gVec(c.angle, 140)
                }
            }
        }
        // foot cops
        footT -= dt
        if footT <= 0 {
            footT = 4
            if stars >= 2 {
                var n = 0
                for q in peds where !q.dead && (q.kind == .cop || q.kind == .swat) && q.terr == -2 { n += 1 }
                if n < min(8, (stars - 1) * 2) {
                    let a = CGFloat.random(in: 0..<(2 * CGFloat.pi))
                    let p = CGPoint(x: gClamp(playerPos.x + cos(a) * 420, 60, CITY - 60), y: gClamp(playerPos.y + sin(a) * 420, 60, CITY - 60))
                    if !city.inBuilding(p) {
                        let ped = makePed(stars >= 4 ? .swat : .cop, at: p)
                        ped.terr = -2
                        ped.chasing = true
                    }
                }
            }
        }
        // blockades, choppers, drones, tanks
        blockT -= dt
        if blockT <= 0 {
            blockT = 14
            if stars >= 3 { spawnBlockade() }
            var nChop = 0
            var nDrone = 0
            for f in flyers { if f.kind == 0 { nChop += 1 } else { nDrone += 1 } }
            if stars >= 3 && nChop < (stars >= 4 ? 2 : 1) { spawnFlyer(kind: 0) }
            if stars >= 5 && nDrone < 2 { spawnFlyer(kind: 1) }
            if stars >= 5 && chaseCount(.tank) < 2 {
                if let (p, _) = randomRoadSpot(minD: 600) {
                    let t = makeCar(.tank, at: p, angle: gAngle(p, playerPos), ai: .tank)
                    t.hasDriver = true
                }
            }
        }
    }

    func spawnBlockade() {
        var head: CGFloat = pAngle
        if let c = inCar { head = c.angle }
        let ahead = CGPoint(x: gClamp(playerPos.x + cos(head) * 560, 120, CITY - 120), y: gClamp(playerPos.y + sin(head) * 560, 120, CITY - 120))
        let nx = abs(ahead.x - (ahead.x / PITCH).rounded() * PITCH)
        let ny = abs(ahead.y - (ahead.y / PITCH).rounded() * PITCH)
        var centers: [CGPoint] = []
        var ang: CGFloat = 0
        if nx < ny {
            let x = (ahead.x / PITCH).rounded() * PITCH
            centers = [CGPoint(x: x - 22, y: ahead.y), CGPoint(x: x + 22, y: ahead.y)]
            ang = 0
        } else {
            let y = (ahead.y / PITCH).rounded() * PITCH
            centers = [CGPoint(x: ahead.x, y: y - 22), CGPoint(x: ahead.x, y: y + 22)]
            ang = CGFloat.pi / 2
        }
        for p in centers {
            let v = makeCar(.swat, at: p, angle: ang, ai: .still)
            v.hasDriver = false
            let q = makePed(.swat, at: CGPoint(x: p.x + cos(gAngle(p, playerPos) + CGFloat.pi) * 34, y: p.y + sin(gAngle(p, playerPos) + CGFloat.pi) * 34))
            q.terr = -3
            q.chasing = true
        }
    }

    // MARK: interactions

    func updateContext() {
        ctxKind = 0
        ctxLabel = ""
        ctxCar = nil
        ctxPed = nil
        if wastedT > 0 || hideT > 0 || heistKind != 0 { return }
        if let car = inCar {
            ctxKind = 2
            ctxLabel = "EXIT"
            if gDist(car.pos, city.paintPos) < 55 {
                ctxKind = 8
                ctxLabel = "PAINT $200"
            }
            return
        }
        var best = CGFloat.greatestFiniteMagnitude
        for c in cars where c.type != .tank && c.type != .swat {
            let d = gDist(playerPos, c.pos)
            if d < c.spec.radius + 32 && d < best {
                best = d
                ctxKind = 1
                ctxCar = c
                ctxLabel = c.hasDriver ? "JACK" : "ENTER"
            }
        }
        if crewCount < 3 && money >= 200 {
            for p in peds where p.kind == .civilian && !p.dead {
                let d = gDist(playerPos, p.pos)
                if d < 40 && d < best {
                    best = d
                    ctxKind = 3
                    ctxPed = p
                    ctxCar = nil
                    ctxLabel = "RECRUIT $200"
                }
            }
        }
        let bd = gDist(playerPos, city.bankDoor)
        if bd < 45 && bd < best && heistCool[0] <= 0 {
            best = bd
            ctxKind = 4
            ctxCar = nil
            ctxPed = nil
            ctxLabel = "ROB BANK"
        }
        let jd = gDist(playerPos, city.jewelDoor)
        if jd < 45 && jd < best && heistCool[1] <= 0 {
            best = jd
            ctxKind = 5
            ctxCar = nil
            ctxPed = nil
            ctxLabel = "ROB GEMS"
        }
        let hd = gDist(playerPos, city.houseDoor)
        if hd < 45 && hd < best {
            best = hd
            ctxKind = 6
            ctxCar = nil
            ctxPed = nil
            ctxLabel = houseOwned ? "SAVE & REST" : "BUY HOUSE $5000"
        }
        for m in city.manholes {
            let d = gDist(playerPos, m)
            if d < 34 && d < best {
                best = d
                ctxKind = 7
                ctxCar = nil
                ctxPed = nil
                ctxLabel = "HIDE IN SEWER"
            }
        }
    }

    func doAction() {
        if !ready || wastedT > 0 || hideT > 0 { return }
        switch ctxKind {
        case 1:
            if let c = ctxCar { enterCar(c) }
        case 2:
            exitCar()
        case 3:
            if let p = ctxPed, money >= 200 {
                money -= 200
                p.kind = .crew
                p.sprite.texture = pedTex["crew"]
                p.hp = 120
                p.fear = 0
                crewCount += 1
                save()
                toast("Crew member recruited!")
            }
        case 4:
            heistKind = 1
            heistT = 0
            heat = max(heat, 85)
            toast("ROBBING THE BANK - stay close!")
        case 5:
            heistKind = 2
            heistT = 0
            heat = max(heat, 45)
            toast("ROBBING THE JEWELRY STORE!")
        case 6:
            if houseOwned {
                pHP = 100
                save()
                toast("Game saved. Health restored.")
            } else if money >= 5000 {
                money -= 5000
                houseOwned = true
                save()
                toast("Safehouse bought! You respawn here now.")
            } else {
                toast("Need $5000")
            }
        case 7:
            hideT = 3.5
            hideFrom = playerPos
        case 8:
            if money >= 200, let c = inCar {
                money -= 200
                var idx = Int.random(in: 0..<palette.count)
                if idx == c.colorIdx { idx = (idx + 1) % palette.count }
                c.colorIdx = idx
                c.body.texture = texFor(c.type, idx)
                if !copSees(c.pos) { heat = 0 } else { heat = max(0, heat - 60) }
                save()
                toast("Fresh paint job!")
            } else {
                toast("Need $200")
            }
        default:
            break
        }
    }

    func enterCar(_ c: Car) {
        if c.hasDriver {
            let p = makePed(.civilian, at: CGPoint(x: c.pos.x + cos(c.angle + CGFloat.pi / 2) * 28, y: c.pos.y + sin(c.angle + CGFloat.pi / 2) * 28))
            p.fear = 6
            p.fearFrom = c.pos
            c.hasDriver = false
            crime(c.type == .police ? 55 : 18, at: c.pos)
        }
        inCar = c
        c.ai = .player
        playerNode.isHidden = true
        invuln = max(invuln, 0.3)
    }

    func exitCar() {
        guard let c = inCar else { return }
        let side = c.angle + CGFloat.pi / 2
        playerPos = CGPoint(x: c.pos.x + cos(side) * (c.spec.radius + 14), y: c.pos.y + sin(side) * (c.spec.radius + 14))
        var v = CGVector.zero
        _ = city.collide(&playerPos, 8, &v, 0)
        pAngle = c.angle
        c.ai = .parked
        inCar = nil
        playerNode.isHidden = false
        braking = false
    }

    func emergeFromSewer() {
        var best = hideFrom
        var bestD: CGFloat = 0
        for m in city.manholes {
            let d = gDist(m, hideFrom)
            if d > bestD {
                bestD = d
                best = m
            }
        }
        playerPos = best
        playerNode.position = best
        camPos = best
        var near = false
        for q in peds where !q.dead && (q.kind == .cop || q.kind == .swat) && gDist(q.pos, best) < 200 { near = true }
        for c in cars where c.type == .police && gDist(c.pos, best) < 200 { near = true }
        if !near {
            heat *= 0.3
            toast("You lost them in the sewers")
        } else {
            toast("Cops were waiting at the exit!")
        }
    }

    func updateHeist(_ dt: CGFloat) {
        if heistKind == 0 {
            heistBar.isHidden = true
            heistBack.isHidden = true
            return
        }
        let door = heistKind == 1 ? city.bankDoor : city.jewelDoor
        let need: CGFloat = heistKind == 1 ? 9 : 6
        if inCar != nil || gDist(playerPos, door) > 95 || wastedT > 0 {
            heistKind = 0
            toast("Robbery failed")
            return
        }
        heistT += dt
        heat += 7 * dt
        heistBar.isHidden = false
        heistBack.isHidden = false
        heistBar.size = CGSize(width: 160 * min(1, heistT / need), height: 10)
        if heistT >= need {
            let prize = heistKind == 1 ? 3000 : 1500
            money += prize
            heistCool[heistKind - 1] = 120
            heat += 40
            heistKind = 0
            save()
            toast("+$\(prize)! Get out of there!")
        }
    }

    func updateEconomy(_ dt: CGFloat) {
        incomeT += dt
        if incomeT >= 60 {
            incomeT = 0
            var n = 0
            for i in 0..<city.terr.count where (terrMask & (1 << i)) != 0 { n += 1 }
            let income = n * 150 + (houseOwned ? 50 : 0)
            if income > 0 {
                money += income
                save()
                toast("Passive income +$\(income)")
            }
        }
        terrT += dt
        if terrT >= 1 {
            terrT = 0
            for i in 0..<city.terr.count where (terrMask & (1 << i)) == 0 {
                var alive = 0
                for q in peds where !q.dead && q.kind == .gang && q.terr == i { alive += 1 }
                if alive == 0 && gDist(playerPos, city.terr[i]) < 500 {
                    terrMask |= (1 << i)
                    save()
                    toast("TERRITORY CAPTURED! +$150 / min")
                    addMarker(city.terr[i], "YOUR TURF", UIColor.green)
                }
            }
        }
    }

    // MARK: HUD and camera

    func updateHUD() {
        hpFill.size = CGSize(width: 130 * max(0, pHP) / 100, height: 12)
        moneyLabel.text = "$\(money)"
        starsLabel.text = stars > 0 ? String(repeating: "★", count: stars) : ""
        starsLabel.alpha = (stars > 0 && noSeeT > 0) ? (Int(lightT * 4) % 2 == 0 ? 1 : 0.3) : 1
        btnActLabel.text = ctxKind == 0 ? "ACT" : ctxLabel
        btnAct.alpha = ctxKind == 0 ? 0.4 : 1
        btnBrake.alpha = inCar != nil ? 1 : 0.25
        promptLabel.text = ctxKind == 0 ? "" : "ACT: \(ctxLabel)"
        weaponLabel.text = WEAPONS[weaponIdx].name
        updateMinimap()
    }

    func updateMinimap() {
        var idx = 0
        for d in mapDots { d.isHidden = true }
        func dot(_ p: CGPoint, _ col: UIColor, _ s: CGFloat) {
            if idx >= mapDots.count { return }
            let rx = (p.x - playerPos.x) * (50.0 / 650.0)
            let ry = (p.y - playerPos.y) * (50.0 / 650.0)
            if abs(rx) > 47 || abs(ry) > 47 { return }
            let d = mapDots[idx]
            idx += 1
            d.isHidden = false
            d.color = col
            d.size = CGSize(width: s, height: s)
            d.position = CGPoint(x: rx, y: ry)
        }
        dot(city.bankDoor, UIColor.yellow, 5)
        dot(city.jewelDoor, UIColor.cyan, 5)
        dot(city.houseDoor, UIColor.green, 5)
        dot(city.paintPos, UIColor.blue, 5)
        for t in city.terr { dot(t, UIColor.orange, 6) }
        for c in cars where (c.type == .police || c.type == .swat || c.type == .tank) && c.ai != .player {
            dot(c.pos, UIColor.red, 4)
        }
        for q in peds where !q.dead && (q.kind == .cop || q.kind == .swat) { dot(q.pos, UIColor(red: 1, green: 0.4, blue: 0.4, alpha: 1), 3) }
        for q in peds where !q.dead && q.kind == .crew { dot(q.pos, UIColor.green, 3) }
        for f in flyers { dot(f.pos, UIColor.magenta, 5) }
        dot(playerPos, UIColor.white, 6)
    }

    func updateCamera(_ dt: CGFloat) {
        var focus = playerPos
        var zoom: CGFloat = 1.3
        if let c = inCar {
            focus = CGPoint(x: c.pos.x + c.vel.dx * 0.35, y: c.pos.y + c.vel.dy * 0.35)
            zoom = gClamp(1.15 - c.speed / 650, 0.62, 1.15)
        }
        let k = min(1, dt * 5)
        camPos.x += (focus.x - camPos.x) * k
        camPos.y += (focus.y - camPos.y) * k
        let halfW = size.width / 2 / zoom
        let halfH = size.height / 2 / zoom
        let cx = gClamp(camPos.x, halfW, CITY - halfW)
        let cy = gClamp(camPos.y, halfH, CITY - halfH)
        var ox: CGFloat = 0
        var oy: CGFloat = 0
        if shakeT > 0 {
            shakeT -= dt
            ox = CGFloat.random(in: -4...4) * min(1, shakeT * 4)
            oy = CGFloat.random(in: -4...4) * min(1, shakeT * 4)
        }
        world.setScale(zoom)
        world.position = CGPoint(x: size.width / 2 - cx * zoom + ox, y: size.height / 2 - cy * zoom + oy)
    }
}

// MARK: - Code Geass (story, characters, voice from the hand-off file)
// =====================================================================================
// CodeGeassGame.swift   (single-file hand-off)
// =====================================================================================
//
// BRIEF FOR THE NEXT CLAUDE (read this first)
// -------------------------------------------
// Goal: an iPhone 3D story game based on Code Geass. Player walks with a JOYSTICK to a
// glowing marker, a conversation starts (VOICED with AVSpeechSynthesizer, subtitle only),
// then a FIGHT / key action, then a short cinematic "vision" beat, then the next chapter.
//
// Tech: Swift + SwiftUI + SceneKit. No signing: built as an UNSIGNED IPA by a GitHub
// Actions workflow (YAML at the bottom of this file) and sideloaded (SideStore/LiveContainer).
//
// This file contains:
//   1. GeassStory       : all 27 chapters (background, travel, trigger, dialogue, fight, vision)
//   2. GeassCharacters  : procedural 3D characters (no model files), 22 characters + weapons + walk
//   3. GeassVoice       : TTS with a different pitch/rate per speaker
//   4. GeassGame + views: working skeleton (joystick, markers, dialogue flow, fight button)
//   5. Build workflow   : YAML in a comment at the bottom
//
// What is DONE: story data, character factory, game flow skeleton.
// What is TODO (suggested order): real combat (light/heavy/dodge) per chapter `fight` text,
//   per-chapter environments (see `background`), music/SFX, save progress, nicer camera,
//   limbs animation polish, optional imported .obj/.usdz models (see CHARACTER NOTE).
//
// CHARACTER NOTE: the user wants "proper 3D" models. Characters here are stylized, built from
// SceneKit shapes (toon outline, eyes, hair spikes, capes). Higher quality .obj models can be
// dropped in later: load with SCNScene(url:) and replace GeassCharacters.make(name). A reference
// image of Lelouch's emperor outfit was supplied by the user (dark blue coat, gold trim,
// high collar, red-lined cape, white cravat, black gloves, red Geass eye) and is mirrored in
// the "LelouchEmperor" spec.
//
// To integrate: add this file to the target. Present `GeassGameView()` as your root view.
// If your project already has an @main App, do not add another one.
// =====================================================================================


// MARK: - 1. STORY ---------------------------------------------------------------------

struct GeassLine { let who: String; let text: String }

struct GeassChapter {
    let id: Int
    let season: String
    let title: String
    let player: String        // model the player controls
    let cast: [String]        // NPC models standing at the marker
    let background: String    // setting + music (build the environment from this)
    let travel: String        // where the player walks with the joystick
    let trigger: String       // when the conversation starts
    let lines: [GeassLine]
    let fight: String         // combat / key action ("None" = skip)
    let vision: String        // camera + mood
}

private func GL(_ who: String, _ text: String) -> GeassLine { GeassLine(who: who, text: text) }

